    private String generateInvitationContent(final EdsEvent event, final String recipient) {
        // Creating a new calendar
        final net.fortuna.ical4j.model.Calendar calendar = new net.fortuna.ical4j.model.Calendar();
        final PropertyList calendarProperties = calendar.getProperties();
        calendarProperties.add(new ProdId("-//KPI.com//iCal4j 1.0//EN"));
        calendarProperties.add(Version.VERSION_2_0);
        calendarProperties.add(CalScale.GREGORIAN);
        calendarProperties.add(Method.REQUEST);

        // Creating a meeting event
        final VEvent vEvent = new VEvent(new DateTime(event.getStartDate()), new DateTime(event.getEndDate()), event.getSubject());
        final PropertyList vEventProperties = vEvent.getProperties();
        vEventProperties.add(Priority.MEDIUM);
        vEventProperties.add(Clazz.PUBLIC);
        if (StringUtils.isNotEmpty(event.getDescription())) {
            vEventProperties.add(new Description(event.getDescription()));
        }
        if (StringUtils.isNotEmpty(event.getVenue())) {
            vEventProperties.add(new Location(event.getVenue()));
        }

        if (event.getOwner() != null && StringUtils.isNotEmpty(event.getOwner().getEmail())) {
            vEventProperties.add(new Organizer(URI.create("mailto:" + event.getOwner().getEmail())));
        }
        calendar.getComponents().add(vEvent);

        return calendar.toString();
    }

    private void sendWorkflowTelegramAlert(final EdsWorkflowTelegramAlert alert, final String relationType, final EdsTraceable object, Map<String, Object> keyValues, Integer userId) {
        ViewName viewName = getViewNameByRelationType(relationType);

        if ("saleorder".equals(relationType)) {
            ArrayList<CompanyCustomFieldItem> companyCustomFields = commonService.getCompanyCustomFields(viewName);
            Set<String> customFieldsName = companyCustomFields.stream()
                    .map(CompanyCustomFieldItem::getColumnCode)
                    .collect(Collectors.toSet());
            Map<String, Object> fieldValueAsMap = ((EdsSaleQuote) object).getFieldValueAsMap(customFieldsName);
            keyValues.putAll(fieldValueAsMap);
        }
        if (keyValues == null) {
            keyValues = object.getFieldValueAsMap(this.modelFieldManager.getFieldIDs(LayoutRPC.getFormIDByRelationType(relationType)));
            keyValues = this.getAdditionalFieldValuesAsMap(relationType, object, keyValues, userId != null ? userManager.getUserByUserID(userId) : userManager.getUser());
        }
        if (RelationItem.TYPE_CUSTOM_FORM_ITEM.equals(relationType)) {
            final EdsCustomFormItems edsCustomFormItems = (EdsCustomFormItems) object;
            keyValues = object.getFieldValueAsMap(this.modelFieldManager.getFieldIDs(LayoutRPC.getFormIDByRelationType(edsCustomFormItems.getCustomForm().getFormID())));
            keyValues = this.getAdditionalFieldValuesAsMap(relationType, object, keyValues, userManager.getUser());
        }
        String message = alert.getMessage();
        try {
            message = EdsTemplates.evaluateTemplate(keyValues, message);
        } catch (final EdsTemplateException e) {
            e.printStackTrace();
        }
        final TelegramSettingsItem telegramSettingsItem = this.globalAuthJdbcSpringManager.getTelegramSettingsItem(alert.getTelegramBotId());
        if (telegramSettingsItem == null) {
            LoggerFactory.getLogger(AllInOneServiceImpl.class).info("telegrambotsettings is not set");
            return;
        }
        final TelegramBot telegramBot = new TelegramBot(telegramSettingsItem.getToken());
        if (alert.getTelegramChats() != null && !alert.getTelegramChats().isEmpty()) {
            for (final EdsTelegramChat telegramChat : alert.getTelegramChats()) {
                SendResponse sendResponse = null;
                try {
                    sendResponse = telegramBot.execute(new SendMessage(telegramChat.getChatId(), message).parseMode(ParseMode.HTML));
                } catch (JsonSyntaxException e) {
                    LoggerFactory.getLogger(AllInOneServiceImpl.class).info("Telegram message sent successfully");
                    e.printStackTrace();
                } catch (Exception e) {
                    LoggerFactory.getLogger(AllInOneServiceImpl.class).info("Telegram message sending failed:{}", sendResponse.description());
                    e.printStackTrace();
                }

                final List<FileResource> attachments = this.attachmentUtilsManager.getAttachments(Constants.F_TELEGRAM, alert.getObjectID(), alert.getObjectID());
                if (attachments != null && attachments.size() > 0) {
                    for (final FileResource fileResource : attachments) {
                        SendResponse sendDocumentResponse = null;
                        try {
                            sendDocumentResponse = telegramBot.execute(new SendDocument(telegramChat.getChatId(), fileResource.getDownloadUrl()));
                        } catch (JsonSyntaxException e) {
                            LoggerFactory.getLogger(AllInOneServiceImpl.class).info("Telegram Document sent successfully");
                            e.printStackTrace();
                        } catch (Exception e) {
                            LoggerFactory.getLogger(AllInOneServiceImpl.class).info("Telegram Document sending failed:{}", sendResponse.description());
                            e.printStackTrace();
                        }
                    }
                }
            }
        }

        if (alert.getReceiverAttributes() != null && !"".equals(alert.getReceiverAttributes())) {
            String individualReceiver = alert.getReceiverAttributes();
            try {
                individualReceiver = EdsTemplates.evaluateTemplate(keyValues, individualReceiver);
            } catch (final EdsTemplateException e) {
                e.printStackTrace();
            }
            String[] chats;
            if (individualReceiver.contains(",")) {
                chats = individualReceiver.split(",");
            } else {
                chats = new String[1];
                chats[0] = individualReceiver;
            }
            MultivaluedHashMap<Integer, Integer> bots = new MultivaluedHashMap<>();
            for (String chat : chats) {
                if (chat.contains(":")) {
                    String[] value = chat.split(":");
                    bots.add(Integer.valueOf(value[0]), Integer.valueOf(value[1]));
                }
            }
            String finalMessage = message;
            Optional.ofNullable(bots.get(telegramSettingsItem.getId())).ifPresent(list -> {
                for (Integer chatId : list) {
                    Optional.ofNullable(telegramChatManager.getById(chatId)).ifPresent(chat -> {
                        final SendResponse sendResponse = telegramBot.execute(new SendMessage(chat.getChatId(), finalMessage).parseMode(ParseMode.HTML));
                        if (sendResponse.isOk()) {
                            LoggerFactory.getLogger(AllInOneServiceImpl.class).info("Telegram message sent successfully");
                        } else {
                            LoggerFactory.getLogger(AllInOneServiceImpl.class).info("Telegram message sending failed:{}", sendResponse.description());
                        }

                        final List<FileResource> attachments = this.attachmentUtilsManager.getAttachments(Constants.F_TELEGRAM, alert.getObjectID(), alert.getObjectID());
                        if (attachments != null && attachments.size() > 0) {
                            for (final FileResource fileResource : attachments) {
                                final SendResponse sendDocumentResponse = telegramBot.execute(new SendDocument(chat.getChatId(), fileResource.getDownloadUrl()));
                                if (sendDocumentResponse.isOk()) {
                                    LoggerFactory.getLogger(AllInOneServiceImpl.class).info("Telegram Document sent successfully");
                                } else {
                                    LoggerFactory.getLogger(AllInOneServiceImpl.class).info("Telegram Document sending failed:{}", sendResponse.description());
                                }
                            }
                        }
                    });
                }
            });
        }
    }

    private void sendWorkflowSMSAlert(final EdsWorkflowSMSAlert alert, final String relationType, final EdsTraceable object, Map<String, Object> keyValues) {
        if (keyValues == null) {
            keyValues = object.getFieldValueAsMap(this.modelFieldManager.getFieldIDs(LayoutRPC.getFormIDByRelationType(relationType)));
            keyValues = this.getAdditionalFieldValuesAsMap(relationType, object, keyValues, null);
        }
        String recepient = alert.getPhone();
        String content = alert.getContent();
        try {
            recepient = EdsTemplates.evaluateTemplate(keyValues, recepient);
        } catch (final EdsTemplateException e) {
            e.printStackTrace();
        }
        try {
            content = EdsTemplates.evaluateTemplate(keyValues, content);
        } catch (final EdsTemplateException e) {
            e.printStackTrace();
        }
        final EdsSmsSettings defaultSettings = alert.getProvider() != null ? this.smsManager.get(alert.getProvider().getObjectID()) : null;
        if (recepient != null && !"".equals(recepient)) {
            for (String phone : recepient.split(",")) {
                if (phone != null && !"".equals(phone)) {
                    phone = phone.trim().replaceAll("[|w+]", "");
                    //Knowledge Grid uzini serveri orqali junatadi smsni
                    if ("31287".equals(ServerSecurityContext.getInstance().getCompanyId())) {
                        final EdsSmsMessage edsSmsMessage = new EdsSmsMessage();
                        edsSmsMessage.setStatus(MessageStatusEnum.PENDING);
                        edsSmsMessage.setPhoneNumber(phone);
                        edsSmsMessage.setAttempts(0);
                        edsSmsMessage.setText(content);
                        edsSmsMessage.setSettingID(defaultSettings != null ? defaultSettings.getObjectID() : null);
                        edsSmsMessage.setCompanyID(SecurityContext.getCompanyID());
                        this.smsMessageManager.create(edsSmsMessage);
                    } else {
                        final EdsSmsSendItem item = new EdsSmsSendItem();
                        item.setUserID(this.userManager.getUser() != null ? this.userManager.getUser().getObjectID() : null);
                        item.setToNumber(phone);
                        item.setSentDate(new Date());
                        item.setMessageText(content);
                        item.setEntityID(object.getObjectID());
                        item.setProvider(defaultSettings);
                        final Boolean isSuccess = this.messageManager.generateAndSendSms(item);
                        if (isSuccess) {
                            this.smsSendItemManager.create(item);
                            if (!RelationItem.TYPE_CASE.equals(relationType)) {
                                final ArrayList<RelationItem> relations = new ArrayList<>();
                                relations.add(new RelationItem(null, object.getObjectID(), relationType, object.getName(), null, null, null));
                                this.saveRelations(RelationItem.TYPE_SMS, item.getObjectID(), item.getName(), relations);
                                relations.clear();
                                relations.add(new RelationItem(null, object.getObjectID(), relationType, object.getName(), null, null, null));
                                relations.add(new RelationItem(null, alert.getWorkflow().getObjectID(), RelationItem.TYPE_WORKFLOW, alert.getWorkflow().getName(), null, null, null));

                                final Appointment appointment = new Appointment();
                                appointment.setSubject("New message has been sent to " + recepient);
                                appointment.setStartDate(new Date());
                                appointment.setEndDate(new Date());
                                appointment.setAllDay(false);
                                appointment.setDescription(content);
                                appointment.setStyle("gwt-appointment-blue");
                                appointment.setAction("add_new_event");
                                appointment.setCreatedBy(this.employeeManager.getUser().getName() != null ? this.employeeManager.getUser().getName() : "");
                                appointment.setRegisterNestedWorkflowEvents(true);
                                appointment.setRegisterWorkFlowEventPerDate(true);
                                appointment.setActivityType(Appointment.SMS);
                                appointment.setRelations(relations);
                                appointment.setCreatedFrom(Appointment.FROM_BOTH);
                                this.googleCalendarService.saveCalendarEvent(null, appointment, false);
                            }
                        }
                    }
                }
            }
        }
    }

    @Override
    public void runWebHooks(EdsWorkflowRule rule, String relationType, EdsTraceable object, boolean isRetry, EdsWebHookResponse existingWebHook) {
        List<EdsWorkflowWebHook> webHooks;
        if (isRetry && existingWebHook != null) {
            webHooks = Collections.singletonList(existingWebHook.getWebHook());
        } else {
            ListingFilterParameter filter = new ListingFilterParameter();
            filter.setWorkflowID(rule.getObjectID());
            webHooks = workflowWebHookManager.list(filter);
        }
        if (webHooks != null && webHooks.size() > 0) {
            Map<String, Object> keyValues;
            Set<String> modelFields = modelFieldManager.getFieldIDs(LayoutRPC.getFormIDByRelationType(relationType));
            if ((modelFields == null || modelFields.size() <= 0) && object instanceof EdsStepEmployee) {
                keyValues = object.getFieldValueAsMap(modelFieldManager.getFieldIDs(((EdsStepEmployee) object).getFormID()));
            }
            if (object instanceof EdsItem) {
                List<EdsModelField> categoryCustomFields = modelFieldManager.getModelFieldsCustom(LayoutRPC.getFormIDByRelationType(TYPE_PRODUCT_CATEGORY));

                Set<String> customFieldsName = categoryCustomFields.stream()
                        .map(EdsModelField::getField_ID)
                        .collect(Collectors.toSet());
                keyValues = object.getFieldValueAsMap(modelFields);

                Map<String, Object> categoryKeyValues = null;
                if (((EdsItem) object).getCategory() != null) {
                    categoryKeyValues = ((EdsItem) object).getCategory().getCategoryFieldValueAsMap(customFieldsName);
                    keyValues.putAll(categoryKeyValues);
                }
            } else if (object instanceof EdsPurchaseInvoice) {
                ArrayList<CompanyCustomFieldItem> companyCustomFields = commonService.getCompanyCustomFields(ViewName.PurchaseInvoice);
                Set<String> customFieldsName = companyCustomFields.stream()
                        .map(CompanyCustomFieldItem::getColumnCode)
                        .collect(Collectors.toSet());
                keyValues = object.getFieldValueAsMap(modelFields);
                Map<String, Object> fieldValueAsMap = ((EdsPurchaseInvoice) object).getFieldValueAsMap(customFieldsName);
                keyValues.putAll(fieldValueAsMap);
            } else {
                keyValues = object.getFieldValueAsMap(modelFields);
            }
            ViewName viewName = getViewNameByRelationType(relationType);
            List<EdsCompanyCustomFieldsSettings> cfs = companyCFManager.getEntityCustomFields(viewName.name(), viewName.equals(ViewName.CustomFormItems) ? relationType : null);
            for (EdsCompanyCustomFieldsSettings cf : cfs) {
                SelectItem[] items = companyCFManager.getCustomFieldDataByQuery(SecurityContext.getCompanyID(), cf.getQuery());
                String selectedId = object.getStringValue(cf.getColumnCode());
                Integer id;
                if (StringUtils.isNotBlank(selectedId)) {
                    id = Integer.parseInt(selectedId);
                    for (SelectItem item : items) {
                        if (id.equals(item.getId())) {
                            keyValues.put("${" + cf.getColumnCode() + "}", item.getDescription() != null ? item.getDescription() : item.getName());
                            keyValues.put("${" + cf.getColumnCode() + "_id" + "}", id);
                            break;
                        }
                    }
                }
            }
            if (viewName.equals(ViewName.Placement) && object instanceof EdsPlacement edsPlacement) {
                Set<String> uuids = new HashSet<>();
                Map<String, List<EdsPlacementItemTable>> cfValuesMap = new HashMap<>();
                List<EdsCompanyCustomFieldsSettings> itemCfs = companyCFSettingsManager.getEntityCustomFields(ViewName.PlacementItemTable.name(), null);
                itemCfs.forEach(cf -> uuids.add(cf.getEntityCategoryName()));
                uuids.forEach(uuid -> cfValuesMap.put(uuid, placementItemTableManager.findByUuid(edsPlacement.getObjectID(), uuid)));
                for (EdsCompanyCustomFieldsSettings cf : itemCfs) {
                    SelectItem[] items = companyCFManager.getCustomFieldDataByQuery(SecurityContext.getCompanyID(), cf.getQuery());
                    List<EdsPlacementItemTable> values = cfValuesMap.get(cf.getEntityCategoryName());
                    StringBuilder value = null;
                    StringBuilder entityId = null;
                    if (values != null && !values.isEmpty()) {
                        for (EdsPlacementItemTable itemTable : values) {
                            String selectedId = (String) CustomFieldsUtils.getObjectValue(itemTable.getCustomFields(), cf.getColumnCode());
                            Integer id;
                            if (StringUtils.isNotBlank(selectedId)) {
                                id = Integer.parseInt(selectedId);
                                for (SelectItem item : items) {
                                    if (id.equals(item.getId())) {
                                        if (value != null) {
                                            value.append(",");
                                            entityId.append(",");
                                        } else {
                                            value = new StringBuilder();
                                            entityId = new StringBuilder();
                                        }
                                        value.append(item.getDescription() != null ? item.getDescription() : item.getName());
                                        entityId.append(id);
                                        break;
                                    }
                                }
                            }
                        }
                    }
                    keyValues.put("${product_table_" + cf.getEntityCategoryName() + "_" + cf.getColumnCode(), value != null ? value.toString() : "");
                    keyValues.put("${product_table_" + cf.getEntityCategoryName() + "_" + cf.getColumnCode() + "_id", entityId != null ? entityId.toString() : "");
                }
            }
            if (relationType.equals("opportunity")) {
                ArrayList<CompanyCustomFieldItem> companyCustomFields = commonService.getCompanyCustomFields(ViewName.OpportunitySubItem);
                Set<String> customFieldsName = companyCustomFields.stream()
                        .map(CompanyCustomFieldItem::getColumnCode)
                        .collect(Collectors.toSet());

                if (((EdsOpportunity) object).getOpportunityItems() != null && !((EdsOpportunity) object).getOpportunityItems().isEmpty()) {
                    Map<String, Object> opportunityItem = ((EdsOpportunity) object).getOpportunityItems().get(0).getItemFieldValuesAsMap(customFieldsName);
                    keyValues.putAll(opportunityItem);
                }
            }
            keyValues = getAdditionalFieldValuesAsMap(relationType, object, keyValues, userManager.getUser(), true);
            for (EdsWorkflowWebHook webHook : webHooks) {
                runWebHook(webHook, keyValues, relationType, object.getObjectID(), object, existingWebHook);
            }
        }
    }

    private static Object extractValue(Object data, String field) {
        String[] fieldParts = field.split("\\.");

        for (String part : fieldParts) {
            int openBracketIndex = part.indexOf('[');
            int closeBracketIndex = part.indexOf(']');

            if (openBracketIndex > 0 && closeBracketIndex > openBracketIndex) {
                String arrayFieldName = part.substring(0, openBracketIndex);
                int index = Integer.parseInt(part.substring(openBracketIndex + 1, closeBracketIndex));

                if (data instanceof Map) {
                    data = ((Map<?, ?>) data).get(arrayFieldName);
                }
                if (data instanceof List<?> list) {
                    data = list.get(index);
                } else if (data instanceof Object[] array) {
                    data = array[index];
                }
            } else {
                if (data instanceof Map) {
                    data = ((Map<?, ?>) data).get(part);
                } else if (data instanceof List<?> list) {
                    for (Object o : list) {
                        if (o instanceof Map) {
                            data = ((Map<?, ?>) o).get(part);
                            break;
                        }
                    }
                }
            }
        }
        if (data instanceof JSONArray && (((JSONArray) data).isEmpty() || ((JSONArray) data).size() == 0)) {
            return null;
        }

        return data;
    }

