    private EdsUpload createUpload(final InputStream inputStream, final String originalName, final String contentType, String storage) {
        final EdsUpload upload = new EdsUpload();
        upload.setContentType(contentType);
        upload.setOriginalName(originalName);
        upload.setType(this.referenceManager.findReference(Constants._UPLOAD_TYPE, storage));
        upload.setInputStream(inputStream);
        try {
            this.uploadManager.create(upload);
            System.out.print("****************File Uploaded******************");
        } catch (final Exception ex) {
            System.err.println("****************Failed to Upload File******************");
        }
        return upload;
    }

    private String updateRecipient(final String recipient) {
        StringBuilder newReceipent = new StringBuilder();
        if (recipient.contains(",")) {
            final ArrayList<String> recipients = new ArrayList<>();
            for (String email : recipient.split(",")) {
                email = email.trim();
                if (!"".equals(email)) {
                    final List<EdsCrmContact> crmContacts = this.crmContactManager.getByPrimaryEmail(email);
                    if (crmContacts != null && crmContacts.size() > 0) {
                        for (final EdsCrmContact crmContact : crmContacts) {
                            if ((crmContact.isDeleted() == null || Boolean.FALSE.equals(crmContact.isDeleted())) && (crmContact.getEmailOptOut() == null || Boolean.FALSE.equals(crmContact.getEmailOptOut()))) {
                                recipients.add(email);
                                break;
                            }
                        }
                    } else {
                        recipients.add(email);
                    }
                }
            }
            for (final String email : recipients) {
                newReceipent.append(email).append(",");
            }
        } else {
            final List<EdsCrmContact> crmContacts = this.crmContactManager.getByPrimaryEmail(recipient);
            if (crmContacts != null && crmContacts.size() > 0) {
                for (final EdsCrmContact crmContact : crmContacts) {
                    if ((crmContact.getEmailOptOut() == null || Boolean.FALSE.equals(crmContact.getEmailOptOut()))) {
                        newReceipent = new StringBuilder(recipient);
                        break;
                    }
                }
            } else {
                newReceipent = new StringBuilder(recipient);
            }
        }
        return newReceipent.toString();
    }

