    private LinkedHashMap<String, List<EdsTraceable>> getTraceableDomainObjects(final String module, final Integer companyID, List<Integer> availableItems) {
        final LinkedHashMap<String, List<EdsTraceable>> traceableMap = new LinkedHashMap<>();
        final List<EdsTraceable> traceables = new ArrayList<>();
        final String relation;
        final int startat = 0;
        final int limit = 500000;
        switch (module) {
            case WorkflowRule._WORKFLOW_MODULE_LEAD -> {
                relation = RelationItem.TYPE_LEAD;
                traceables.addAll(this.crmContactManager.getCompanyLeads(companyID, startat, limit));
            }
            case WorkflowRule._WORKFLOW_MODULE_CONTACT -> {
                relation = RelationItem.TYPE_CONTACT;
                traceables.addAll(this.crmContactManager.getCompanyContacts(companyID, startat, limit));
            }
            case WorkflowRule._WORKFLOW_MODULE_CASE -> {
                relation = RelationItem.TYPE_CASE;
                traceables.addAll(this.caseManager.getCompanyCaseList(companyID, startat, limit));
            }
            case WorkflowRule._WORKFLOW_MODULE_PAYRUN -> {
                relation = RelationItem.TYPE_PAYRUN;
                traceables.addAll(this.payslipTableManager.getTables(new ListingFilterParameter()));
            }
            case WorkflowRule._WORKFLOW_MODULE_CASH_ADVANCE -> {
                relation = RelationItem.TYPE_CASH_ADVANCE;
                traceables.addAll(this.cashAdvanceManager.getCashAdvancedList(new ListingFilterParameter()));
            }
            case WorkflowRule._WORKFLOW_MODULE_ACTIVITY, WorkflowRule._WORKFLOW_MODULE_LOGACALL -> {
                relation = RelationItem.TYPE_EVENT;
                traceables.addAll(this.eventManager.getList(new ListingFilterParameter()));
            }
            case WorkflowRule._WORKFLOW_MODULE_SCHEDULED_COURSE -> {
                relation = RelationItem.TYPE_COURCE_SCHEDULE;
                traceables.addAll(this.scheduledCourseManager.getAvailableCourseSchedule(new ListingFilterParameter()));
            }
            case WorkflowRule._WORKFLOW_MODULE_SALE_INVOICE -> {
                relation = TYPE_SALEINVOICE;
                ListingFilterParameter filterParameter = new ListingFilterParameter();
                filterParameter.setObjectIDs(new ArrayList<>(availableItems));
                traceables.addAll(this.invoiceManager.getSaleInvoiceList(filterParameter));
            }
            case WorkflowRule._WORKFLOW_MODULE_CREDIT_NOTE -> {
                relation = TYPE_CREDIT_NOTE;
                ListingFilterParameter filterParameter = new ListingFilterParameter();
                filterParameter.setObjectIDs(new ArrayList<>(availableItems));
                traceables.addAll(this.invoiceManager.getSaleInvoiceList(filterParameter));
            }
            case WorkflowRule._WORKFLOW_MODULE_DEBIT_NOTE -> {
                relation = TYPE_DEBIT_NOTE;
                ListingFilterParameter filterParameter = new ListingFilterParameter();
                filterParameter.setObjectIDs(new ArrayList<>(availableItems));
                traceables.addAll(this.invoiceManager.getPurchaseInvoiceList(filterParameter, false));
            }
            case WorkflowRule._WORKFLOW_MODULE_PURCHASE_INVOICE -> {
                relation = TYPE_PURCHASE_INVOICE;
                traceables.addAll(this.invoiceManager.getPurchaseInvoiceList(new ListingFilterParameter(), false));
            }
            case WorkflowRule._WORKFLOW_MODULE_SALEQUOTE, WorkflowRule._WORKFLOW_MODULE_SALEORDER -> {
                relation = RelationItem.TYPE_SALEQUOTE;
                traceables.addAll(this.quoteManager.getSaleQuoteList(new ListingFilterParameter(), new ListLoadConfig()));
            }
            case WorkflowRule._WORKFLOW_MODULE_STOCK_TRANSFER -> {
                relation = TYPE_STOCK_TRANSFER;
                traceables.addAll(this.stockTransferManager.getList(new ListingFilterParameter()));
            }
            case WorkflowRule._WORKFLOW_MODULE_STOCK_ADJUSTMENT -> {
                relation = TYPE_STOCK_ADJUSTMENT;
                traceables.addAll(this.stockAdjustmentManager.getList(new ListingFilterParameter()));
            }
            case WorkflowRule._WORKFLOW_MODULE_PLACEMENT -> {
                relation = RelationItem.TYPE_PLACEMENT;
                traceables.addAll(this.recruitmentServiceLocal.getPlacements(new ListingFilterParameter()));
            }
            case WorkflowRule._WORKFLOW_MODULE_REQUEST_FOR_PURCHASE -> {
                relation = RelationItem.REQUEST_FOR_PURCHASE;
                traceables.addAll(this.rfpManager.getEdsRFPList(new ListingFilterParameter(), false));
            }
            case WorkflowRule._WORKFLOW_MODULE_PURCHASEORDER -> {
                relation = RelationItem.TYPE_PURCHASE_ORDER;
                traceables.addAll(this.quoteManager.getPurchaseOrderList(new ListingFilterParameter(), new ListLoadConfig()));
            }
            case WorkflowRule._WORKFLOW_MODULE_HRMS_EMPLOYEE -> {
                relation = RelationItem.TYPE_EMPLOYEE;
                traceables.addAll(this.employeeManager.getCompanyEmployees(availableItems));
            }
            case WorkflowRule._WORKFLOW_MODULE_OPPORTUNITY -> {
                relation = RelationItem.TYPE_OPPORTUNITY;
                traceables.addAll(this.opportunityManager.getOpportunityList(new ListingFilterParameter()));
            }
            case WorkflowRule._WORKFLOW_MODULE_CERTIFICATE -> {
                relation = RelationItem.TYPE_CERTIFICATE;
                traceables.addAll(this.certificateManager.getCertificateList(new ListingFilterParameter()));
            }
            case WorkflowRule._WORKFLOW_MODULE_PROJECT -> {
                relation = RelationItem.TYPE_PROJECT;
                traceables.addAll(this.projectManager.list(new ListingFilterParameter()));
            }
            case WorkflowRule._WORKFLOW_MODULE_PRODUCT -> {
                relation = RelationItem.TYPE_PRODUCT;
                traceables.addAll(this.itemManager.getCompanyItemList(new ListingFilterParameter()));
            }
            case WorkflowRule._WORKFLOW_MODULE_ACCOUNT -> {
                relation = RelationItem.TYPE_CRM_ACCOUNT;
                traceables.addAll(this.crmAccountManager.getCompanyCrmAccountsForSolr(new SolrReindexRpc(), startat, limit));
            }
            case WorkflowRule._WORKFLOW_MODULE_MANUAL_JOURNAL -> {
                relation = RelationItem.TYPE_MANUAL_JOURNAL;
                final ListingFilterParameter fp = new ListingFilterParameter();
                fp.setStart(startat);
                fp.setLimit(limit);
                traceables.addAll(this.manualJournalManager.getManualJournals(fp));
            }
            case WorkflowRule._WORKFLOW_MODULE_TASK -> {
                relation = RelationItem.TYPE_TASK;
                traceables.addAll(this.taskManager.list(new ListingFilterParameter()));
            }
            case WorkflowRule._WORKFLOW_MODULE_REQUEST_FOR_QUOTE -> {
                relation = TYPE_REQUEST_FOR_QUOTE;
                final ListingFilterParameter filter = new ListingFilterParameter();
                filter.setStart(startat);
                filter.setLimit(limit);
                traceables.addAll(this.rfqManager.getRFQList(filter));
            }
            case WorkflowRule._WORKFLOW_MODULE_SICK_REQUEST -> {
                relation = RelationItem.TYPE_LEAVE_REQUEST;
                final ListingFilterParameter fn = new ListingFilterParameter();
                fn.setStart(startat);
                fn.setLimit(limit);
                traceables.addAll(this.sickRequestManager.getList(fn));
            }
            case WorkflowRule._WORKFLOW_MODULE_VACANCY -> {
                relation = RelationItem.TYPE_VACANCY;
                final ListingFilterParameter vacancyFilter = new ListingFilterParameter();
                vacancyFilter.setStart(startat);
                vacancyFilter.setLimit(limit);
                traceables.addAll(this.vacancyManager.list(vacancyFilter));
            }
            case WorkflowRule._WORKFLOW_MODULE_EXPENSE_CLAIM -> {
                relation = TYPE_EXPENSE_CLAIM;
                final ListingFilterParameter expenseFilter = new ListingFilterParameter();
                expenseFilter.setStart(startat);
                expenseFilter.setLimit(limit);
                traceables.addAll(this.expenseReportManager.getAllExpenseReports(expenseFilter));
            }
            case WorkflowRule._WORKFLOW_MODULE_PRODUCT_CATEGORY -> {
                relation = RelationItem.TYPE_PRODUCT_CATEGORY;
                final ListingFilterParameter categoryFilter = new ListingFilterParameter();
                categoryFilter.setStart(startat);
                categoryFilter.setLimit(limit);
                traceables.addAll(this.productCategoryManager.getCategoriesByFilter(categoryFilter));
            }
            case WorkflowRule._WORKFLOW_MODULE_SHIFT -> {
                relation = RelationItem.TYPE_SHIFT;
                ListingFilterParameter shiftFp = new ListingFilterParameter();
                shiftFp.setStart(startat);
                shiftFp.setLimit(limit);
                traceables.addAll(shiftManager.getList(shiftFp, null, true));
            }
            case WorkflowRule._WORKFLOW_MODULE_COMPANY_SETTINGS -> {
                relation = RelationItem.TYPE_COMPANY_SETTINGS;
                ListingFilterParameter companySettingsFp = new ListingFilterParameter();
                companySettingsFp.setStart(startat);
                companySettingsFp.setLimit(limit);
//                traceables.addAll(companySettingsManager.getCompanySettingsList(companySettingsFp));
            }
            case WorkflowRule._WORKFLOW_MODULE_EMPLOYEE_DOCUMENTS -> {
                relation = RelationItem.TYPE_EMPLOYEE_DOCUMENTS;
                traceables.addAll(fileHeaderManager.getEmployeeDocuments(availableItems));
            }
            default -> {
                String formId = module.replaceAll(WorkflowRule._WORKFLOW_MODULE + "_", "") + "_FORM";
                EdsCustomForm customForm = customFormManager.findByFormID(formId);
                if (customForm != null) {
                    relation = RelationItem.TYPE_CUSTOM_FORM_ITEM;
                    ListingFilterParameter filterParameter = new ListingFilterParameter();
                    filterParameter.setForm(formId);
                    traceables.addAll(customFormItemManager.allList(filterParameter));
                } else {
                    relation = RelationItem.TYPE_EMPLOYEE_STEP;
                    traceables.addAll(this.stepEmployeeManager.getStepList(new ListingFilterParameter()));
                }
            }
        }
        traceableMap.put(relation, traceables);
        return traceableMap;
    }

    public Map<String, Object> getAdditionalFieldValuesAsMap(final String relationType, final EdsTraceable object, final Map<String, Object> keyValues, final EdsUser user) {
        return getAdditionalFieldValuesAsMap(relationType, object, keyValues, user, false);
    }

    private Map<String, Object> getAdditionalFieldValuesAsMap(final String relationType, final EdsTraceable object, final Map<String, Object> keyValues, final EdsUser user, boolean isWebHook) {
        restTemplate.setRequestFactory(new HttpComponentsClientHttpRequestFactory());
        List<HttpMessageConverter<?>> messageConverters = new ArrayList<>();

        messageConverters.add(new FormHttpMessageConverter());
        messageConverters.add(new StringHttpMessageConverter());
        //Add the Jackson Message converter
        MappingJackson2HttpMessageConverter converter = new MappingJackson2HttpMessageConverter();

        // Note: here we are making this converter to process any kind of response,
        // not only application/*json, which is the default behaviour
        converter.setSupportedMediaTypes(Collections.singletonList(MediaType.ALL));
        messageConverters.add(converter);
        restTemplate.setMessageConverters(messageConverters);
        if (RelationItem.TYPE_LEAD.equals(relationType) || RelationItem.TYPE_CANDIDATE.equals(relationType) || RelationItem.TYPE_CONTACT.equals(relationType)) {
            final EdsCrmContact contact = (EdsCrmContact) object;
            if (RelationItem.TYPE_LEAD.equals(relationType)) {
                return this.getLeadFieldValuesAsMap(contact, keyValues, user);
            } else if (RelationItem.TYPE_CONTACT.equals(relationType)) {
                return this.getContactFieldValuesAsMap(contact, keyValues, user);
            }
            return this.getContactFieldValuesAsMap(contact, keyValues, user);
        } else if (RelationItem.TYPE_EVENT.equals(relationType)) {
            final EdsEvent event = (EdsEvent) object;
            return this.getEventFieldValuesAsMap(event, keyValues, user);
        } else if (RelationItem.TYPE_LEAVE_REQUEST.equals(relationType)) {
            final EdsSickRequest edsEntity = (EdsSickRequest) object;
            return this.getLeaveRequestFieldValuesAsMap(edsEntity, keyValues, user);
        } else if (RelationItem.TYPE_COURCE_SCHEDULE.equals(relationType)) {
            final EdsCourseSchedule courseSchedule = (EdsCourseSchedule) object;
            return this.getCSFieldValuesAsMap(courseSchedule, keyValues);
        } else if (RelationItem.TYPE_CS_STUDENT.equals(relationType)) {
            final EdsCourseScheduleStudent courseScheduleStudent = (EdsCourseScheduleStudent) object;
            return this.getStudentFieldValuesAsMap(courseScheduleStudent, keyValues, user);
        } else if (RelationItem.TYPE_CASE.equals(relationType)) {
            final EdsCase crmCase = (EdsCase) object;
            return this.getCaseFieldValuesAsMap(crmCase, keyValues, user);
        } else if (TYPE_SALEINVOICE.equals(relationType)) {
            final EdsSaleInvoice saleInvoice = (EdsSaleInvoice) object;
            return this.getSaleInvoiceFieldValuesAsMap(saleInvoice, keyValues, user, isWebHook);
        } else if (TYPE_CREDIT_NOTE.equals(relationType) || TYPE_DEBIT_NOTE.equals(relationType)) {
            if (object instanceof EdsSaleInvoice) {
                return this.getSaleInvoiceFieldValuesAsMap((EdsSaleInvoice) object, keyValues, user, isWebHook);
            } else {
                return this.getDebitNoteFieldValuesAsMap((EdsPurchaseInvoice) object, keyValues, user, isWebHook);
            }
        } else if (RelationItem.TYPE_SALEQUOTE.equals(relationType) || RelationItem.TYPE_SALEORDER.equals(relationType)) {
            final EdsSaleQuote saleQuote = (EdsSaleQuote) object;
            return this.getSaleQuoteFieldValuesAsMap(saleQuote, keyValues, user, isWebHook);
        } else if (RelationItem.REQUEST_FOR_PURCHASE.equals(relationType)) {
            final EdsRFP rfp = (EdsRFP) object;
            return this.getRFPFieldValuesAsMap(rfp, keyValues, user);
        } else if (RelationItem.TYPE_PURCHASE_ORDER.equals(relationType)) {
            final EdsPurchaseOrder purchaseOrder = (EdsPurchaseOrder) object;
            return this.getPurchaseOrderFieldValuesAsMap(purchaseOrder, keyValues, user, isWebHook);
        } else if (RelationItem.TYPE_OPPORTUNITY.equals(relationType)) {
            final EdsOpportunity opportunity = (EdsOpportunity) object;
            return this.getOpportunityFieldValuesAsMap(opportunity, keyValues, user);
        } else if (RelationItem.TYPE_CASH_ADVANCE.equals(relationType)) {
            final EdsCashAdvance cashAdvance = (EdsCashAdvance) object;
            return this.getCashAdvanceFieldValuesAsMap(cashAdvance, keyValues, user);
        } else if (TYPE_EXPENSE_CLAIM.equals(relationType)) {
            final EdsExpenseReport report = (EdsExpenseReport) object;
            return this.getExpenseClaimFieldValuesAsMap(report, keyValues, user);
        } else if (RelationItem.TYPE_CERTIFICATE.equals(relationType)) {
            final EdsCertificate edsCertificate = (EdsCertificate) object;
            return this.getCertificateFieldValuesAsMap(edsCertificate, keyValues, user);
        } else if (RelationItem.TYPE_PROJECT.equals(relationType)) {
            final EdsProject edsProject = (EdsProject) object;
            return this.getProjectFieldValuesAsMap(edsProject, keyValues, user);
        } else if (RelationItem.TYPE_PAYRUN.equals(relationType)) {
            final EdsPayslipTable payslipTable = (EdsPayslipTable) object;
            return this.getPayrunFieldValuesAsMap(payslipTable, keyValues, user);
        } else if (TYPE_STOCK_TRANSFER.equals(relationType)) {
            final EdsStockTransfer edsStockTransfer = (EdsStockTransfer) object;
            return this.getStockTransferFieldValuesAsMap(edsStockTransfer, keyValues, user);
        } else if (TYPE_STOCK_ADJUSTMENT.equals(relationType)) {
            EdsStockAdjustment edsStockAdjustment = (EdsStockAdjustment) object;
            return this.getStockAdjustmentFieldValuesAsMap(edsStockAdjustment, keyValues, user);
        } else if (RelationItem.TYPE_CRM_ACCOUNT.equals(relationType)) {
            final EdsCrmAccount edsCrmAccount = (EdsCrmAccount) object;
            return this.getCrmAccountFieldValuesAsMap(edsCrmAccount, keyValues, user, isWebHook);
        } else if (RelationItem.TYPE_CERTIFICATE_OF_EMPLOYMENT.equals(relationType)) {
            final EdsCertificateOfEmployment certificateOfEmployment = (EdsCertificateOfEmployment) object;
            return this.getEmployeeCertificateFieldValuesMap(certificateOfEmployment, keyValues, user);
        } else if (RelationItem.TYPE_MANUAL_JOURNAL.equals(relationType)) {
            final EdsManualJournal edsManualJournal = (EdsManualJournal) object;
            return this.getManualEntryFieldValuesMap(edsManualJournal, keyValues, user);
        } else if (RelationItem.TYPE_EMPLOYEE.equals(relationType) && !(object instanceof EdsStepEmployee)) {
            final EdsEmployee edsEmployee = (EdsEmployee) object;
            return this.getEmployeeFieldValuesMap(edsEmployee, keyValues, user);
        } else if (RelationItem.TYPE_PLACEMENT.equals(relationType)) {
            final EdsPlacement edsPlacement = (EdsPlacement) object;
            return this.getPlacementFieldValuesMap(edsPlacement, keyValues, user);
        } else if (RelationItem.TYPE_GDN.equals(relationType)) {
            final EdsShippingData shippingData = (EdsShippingData) object;
            return this.getGDNFieldValuesMap(shippingData, keyValues, user);
        } else if (RelationItem.TYPE_SHIPPING_DATA.equals(relationType)) {
            final EdsPickList pickList = (EdsPickList) object;
            return this.getShippingDataFieldValuesMap(pickList, keyValues, user);
        } else if (RelationItem.TYPE_TASK.equals(relationType)) {
            final EdsTask edsTask = (EdsTask) object;
            return this.getTaskFieldValuesMap(edsTask, keyValues, user);
        } else if (TYPE_REQUEST_FOR_QUOTE.equals(relationType)) {
            final EdsRFQ edsRfq = (EdsRFQ) object;
            return this.getRequestForQuoteFieldValuesAsMap(edsRfq, keyValues, user);
        } else if (TYPE_PURCHASE_INVOICE.equals(relationType)) {
            final EdsPurchaseInvoice edsPurchaseInvoice = (EdsPurchaseInvoice) object;
            return this.getPurchaseInvoiceFieldValuesAsMap(edsPurchaseInvoice, keyValues, user, isWebHook);
        } else if (RelationItem.TYPE_DEPARTMENT.equals(relationType)) {
            EdsDepartment edsDepartment = (EdsDepartment) object;
            return getDepartmentFieldValuesAsMap(edsDepartment, keyValues, user);
        } else if (RelationItem.TYPE_POSITION.equals(relationType)) {
            EdsPosition edsPosition = (EdsPosition) object;
            return getPositionFieldValuesAsMap(edsPosition, keyValues, user);
        } else if (RelationItem.TYPE_PRODUCT.equals(relationType)) {
            EdsItem edsItem = (EdsItem) object;
            return getProductFieldValuesAsMap(edsItem, keyValues, user, isWebHook);
        } else if (RelationItem.TYPE_ROTATION.equals(relationType)) {
            EdsRotation rotation = (EdsRotation) object;
            return getRotationFieldValuesAsMap(rotation, keyValues, user);
        } else if (RelationItem.TYPE_GROUP_PLACEMENT.equals(relationType)) {
            EdsGroupPlacement placement = (EdsGroupPlacement) object;
//            return getRotationFieldValuesAsMap()
        } else if (RelationItem.TYPE_BATCH_PAYMENT_RECEIVABLE.equals(relationType) || RelationItem.TYPE_BATCH_PAYMENT_PAYABLE.equals(relationType)) {
            EdsBatchPayment payment = (EdsBatchPayment) object;
            return getBatchPaymentFieldValuesAsMap(payment, keyValues, user);
        } else if (RelationItem.TYPE_PRODUCT_CATEGORY.equals(relationType)) {
            EdsProductCategory category = (EdsProductCategory) object;
            return getProductCategoryFieldValuesAsMap(category, keyValues, user);
        } else if (RelationItem.TYPE_EMPLOYEE_DOCUMENTS.equals(relationType)) {
            EdsFileHeader edsFileHeader = (EdsFileHeader) object;
            return getEmployeeDocumentsFieldValuesAsMap(edsFileHeader, keyValues, user);
        } else if (RelationItem.TYPE_COMPANY_SETTINGS.equals(relationType)) {
            EdsCompanySettings settings = (EdsCompanySettings) object;
            return getCompanySettingsFieldValuesAsMap(settings, keyValues, user);
        } else if (RelationItem.TYPE_INCIDENT.equals(relationType)) {
            EdsPerformanceNote incident = (EdsPerformanceNote) object;
            return getIncidentFieldValuesMap(incident, keyValues, user);
        } else if (RelationItem.TYPE_SHIFT.equals(relationType)) {
            EdsShift shift = (EdsShift) object;
            return getShiftFieldValuesMap(shift, keyValues, user);
        } else if (RelationItem.TYPE_VACANCY.equals(relationType)) {
            EdsVacancy vacancy = (EdsVacancy) object;
            return getVacancyFieldValuesMap(vacancy, keyValues, user);
        } else if (object instanceof EdsCustomFormItems) {
            final EdsCustomForm edsForm = this.customFormManager.findByFormID(relationType);
            if (RelationItem.TYPE_CUSTOM_FORM_ITEM.equals(relationType) || edsForm != null) {
                final EdsCustomFormItems edsItem = (EdsCustomFormItems) object;
                return this.getCustomFormItemsFieldValuesMap(edsItem, keyValues, user, isWebHook);
            }
        } else if (object instanceof EdsStepEmployee) {
            final EdsModel model = this.modelManager.get(relationType);
            if (RelationItem.TYPE_EMPLOYEE_STEP.equals(relationType) || (model != null && model.isStepForm())) {
                final EdsStepEmployee employeeStep = (EdsStepEmployee) object;
                return this.getEmployeeStepFieldValuesMap(employeeStep, keyValues, user);
            }
        } else if (object instanceof EdsAdditionalPayment edsAdditionalPayment) {
            return getAdditionalPaymentFieldValuesMap(edsAdditionalPayment, keyValues, user, isWebHook);
        }
        return keyValues;
    }

    private Map<String, Object> getCompanySettingsFieldValuesAsMap(EdsCompanySettings settings, Map<String, Object> keyValues, EdsUser user) {
        EdsTaxillaCredentials taxillaCredential = taxillaCredentialsManager.getTaxillaCredential();
        keyValues.put(EmailTemplateConstants.ET_COMPANY_NAME, settings.getName());
        if (taxillaCredential != null && taxillaCredential.getAccessToken() != null) {
            keyValues.put(EmailTemplateConstants.ACCOUNTING.TAXILLA_ACCESS_TOKEN, "Bearer " + taxillaCredential.getAccessToken());
        }

        // Company Info
        if (user != null) {
            EdsCompany company = user.getCompany();
            if (company != null) {
                keyValues.put(EmailTemplateConstants.CompanyForm.COMPANY_ID, company.getObjectID());
                keyValues.put(EmailTemplateConstants.CompanyForm.NAME, company.getName());
                keyValues.put(EmailTemplateConstants.CompanyForm.EMAIL, company.getEmail());
                keyValues.put(EmailTemplateConstants.CompanyForm.MOBILE_PHONE_NUMBER, company.getMobilePhone());
                keyValues.put(EmailTemplateConstants.CompanyForm.OFFICE_PHONE_NUMBER, company.getPhone());
                keyValues.put(EmailTemplateConstants.CompanyForm.LANGUAGE, company.getLocale());
                keyValues.put(EmailTemplateConstants.CompanyForm.TIME_ZONE, company.getTimeZone());
                keyValues.put(EmailTemplateConstants.CompanyForm.WEBSITE, company.getWebsite());
                EdsAddress mainAddress = company.getBillingAddress();
                if (mainAddress != null) {

                    keyValues.put(EmailTemplateConstants.CompanyForm.FULL_ADDRESS, mainAddress.getAddressData() != null ? mainAddress.getAddressData() : "");
                    keyValues.put(EmailTemplateConstants.CompanyForm.ADDRESS_NAME, mainAddress.getName());
                    keyValues.put(EmailTemplateConstants.CompanyForm.ADDRESS_LINE_1, mainAddress.getAddress());
                    keyValues.put(EmailTemplateConstants.CompanyForm.ADDRESS_LINE_2, mainAddress.getAddressb());
                    keyValues.put(EmailTemplateConstants.CompanyForm.ADDRESS_CITY, mainAddress.getCity());
                    keyValues.put(EmailTemplateConstants.CompanyForm.ADDRESS_STATE, mainAddress.getStateName());
                    keyValues.put(EmailTemplateConstants.CompanyForm.ADDRESS_ZIPCODE, mainAddress.getZipCode());
                    keyValues.put(EmailTemplateConstants.CompanyForm.ADDRESS_COUNTRY, mainAddress.getCountryName());
                }

                List<EdsTimeSlot> timeSlots = timeSlotManager.getTimeslots();
                if (timeSlots != null && !timeSlots.isEmpty()) {
                    Integer objectId = user.getCompany().getObjectID();
                    List<TimeslotDTO> timeslotList = timeSlots.stream().map(ts -> {
                        EdsReferenceLocale locale = ts.getLocale();
                        return new TimeslotDTO(
                                objectId,
                                ts.getObjectID(),
                                locale != null ? locale.getUzbek() : ts.getName(),
                                locale != null ? locale.getRussian() : ts.getName(),
                                locale != null ? locale.getEnglish() : ts.getName()
                        );
                    }).collect(Collectors.toList());

                    String timeslotJson = new Gson().toJson(timeslotList);
                    keyValues.put(EmailTemplateConstants.CompanyForm.TIME_SLOT, timeslotJson);
                } else {
                    keyValues.put(EmailTemplateConstants.CompanyForm.TIME_SLOT, "[]");
                }

            }
        }

        return keyValues;
    }

    private Map<String, Object> getIncidentFieldValuesMap(EdsPerformanceNote edsPerformanceNote, Map<String, Object> keyValues, EdsUser user) {
        keyValues = keyValues == null ? new HashMap<>() : keyValues;
        if (edsPerformanceNote != null) {
            keyValues.put(EmailTemplateConstants.HRMS.INCIDENT.RELATED_EMPLOYEE_EMAIL, edsPerformanceNote.getRelatedTo() != null ? edsPerformanceNote.getRelatedTo().getEmployee().getEmail() : "");
            keyValues.put(EmailTemplateConstants.HRMS.INCIDENT.REPORTED_BY_EMAIL, edsPerformanceNote.getReportedBy() != null ? edsPerformanceNote.getReportedBy().getEmployee().getEmail() : "");
            keyValues.put(EmailTemplateConstants.HRMS.INCIDENT.RELATED_EMPLOYEE_PHONE, edsPerformanceNote.getRelatedTo() != null ? edsPerformanceNote.getRelatedTo().getEmployee().getPrimaryPhone() : "");
            keyValues.put(EmailTemplateConstants.HRMS.INCIDENT.REPORTED_BY_PHONE, edsPerformanceNote.getReportedBy() != null ? edsPerformanceNote.getReportedBy().getEmployee().getPrimaryPhone() : "");
            keyValues.put(EmailTemplateConstants.HRMS.INCIDENT.START_DATE, edsPerformanceNote.getDate_start() != null ? edsPerformanceNote.getDate_start() : "");
            keyValues.put(EmailTemplateConstants.HRMS.INCIDENT.END_DATE, edsPerformanceNote.getDate_end() != null ? edsPerformanceNote.getDate_end() : "");
        }
        return keyValues;
    }

    private Map<String, Object> getShiftFieldValuesMap(EdsShift shift, Map<String, Object> keyValues, EdsUser user) {
        keyValues = keyValues == null ? new HashMap<>() : keyValues;
        if (shift != null) {
            keyValues.put(EmailTemplateConstants.ID, shift.getObjectID());
            keyValues.put(EmailTemplateConstants.HRMS.EMPLOYEE.CURRENT_USER, user.getUserName());
        }
        return keyValues;
    }

    private Map<String, Object> getVacancyFieldValuesMap(EdsVacancy vacancy, Map<String, Object> keyValues, EdsUser user) {
        keyValues = keyValues == null ? new HashMap<>() : keyValues;
        if (vacancy == null) return keyValues;

        String approver = "";
        if (vacancy.getCurrentApprover() != null && vacancy.getCurrentApprover().getExactEmployee() != null) {
            approver = vacancy.getCurrentApprover().getExactEmployee().getName();
        }
        keyValues.put(EmailTemplateConstants.HRMS.VACANCY.VACANCY_APPROVER, approver);
        String vsLink = EdsContextParams.getHost() + "/Hrms.html#vacancy%7Csummary/" + vacancy.getObjectID();
        keyValues.put(EmailTemplateConstants.HRMS.VACANCY.VACANCY_SUMMARY_LINK, vsLink);
        keyValues.put(EmailTemplateConstants.HRMS.VACANCY.VACANCY_NUMBER, vacancy.getVacancyNumber());
        keyValues.put(EmailTemplateConstants.ID, vacancy.getObjectID());
        EdsRecruitmentIntegration credentials = recruitmentIntegrationManager.getCompanyCredentials();
        if (credentials != null && credentials.getHhAccessToken() != null) {
            keyValues.put(EmailTemplateConstants.HRMS.VACANCY.HH_ACCESS_TOKEN, credentials.getHhAccessToken());
        } else {
            keyValues.put(EmailTemplateConstants.HRMS.VACANCY.HH_ACCESS_TOKEN, "");
        }

        String jobTitle = isNotBlank(vacancy.getJobTitle()) ? vacancy.getJobTitle() : "n/a";

        EdsReferenceLocale vLocale = vacancy.getLocale();

        String enName = isNotBlank(vLocale != null ? vLocale.getEnglish() : null) ? vLocale.getEnglish() : jobTitle;
        String ruName = isNotBlank(vLocale != null ? vLocale.getRussian() : null) ? vLocale.getRussian() : jobTitle;
        String arName = isNotBlank(vLocale != null ? vLocale.getArabic() : null) ? vLocale.getArabic() : jobTitle;
        String uzName = isNotBlank(vLocale != null ? vLocale.getUzbek() : null) ? vLocale.getUzbek() : jobTitle;


        keyValues.put(EmailTemplateConstants.HRMS.VACANCY.NAME_EN, enName);
        keyValues.put(EmailTemplateConstants.HRMS.VACANCY.NAME_RU, ruName);
        keyValues.put(EmailTemplateConstants.HRMS.VACANCY.NAME_AR, arName);
        keyValues.put(EmailTemplateConstants.HRMS.VACANCY.NAME_UZ, uzName);
        keyValues.put(EmailTemplateConstants.HRMS.VACANCY.CODE, vacancy.getVacancyNumber() != null ? vacancy.getVacancyNumber() : "");

        Integer locationId = 0;
        String enLocation = "";
        String ruLocation = "";
        String uzLocation = "";

        Integer branchId = 0;
        String enBranch = "";
        String ruBranch = "";
        String uzBranch = "";

        EdsLocation location = vacancy.getLocation();
        String locationName = isNotBlank(location != null ? location.getLocationRealName() : null)
                ? location.getLocationRealName()
                : "n/a";

        if (location != null) {
            EdsReferenceLocale locLocale = location.getLocale();

            if (location.getParent() != null) {
                // This is a branch
                branchId = location.getObjectID();

                if (locLocale != null) {
                    enBranch = getNonEmptyOrDefault(locLocale.getEnglish(), locationName);
                    ruBranch = getNonEmptyOrDefault(locLocale.getRussian(), locationName);
                    uzBranch = getNonEmptyOrDefault(locLocale.getUzbek(), locationName);
                }

                // Set parent as location
                EdsLocation parent = location.getParent();
                String parentName = isNotBlank(parent != null ? parent.getLocationRealName() : null)
                        ? parent.getLocationRealName()
                        : "n/a";
                locationId = parent.getObjectID();

                if (parent.getLocale() != null) {
                    EdsReferenceLocale parentLoc = parent.getLocale();
                    enLocation = getNonEmptyOrDefault(parentLoc.getEnglish(), parentName);
                    ruLocation = getNonEmptyOrDefault(parentLoc.getRussian(), parentName);
                    uzLocation = getNonEmptyOrDefault(parentLoc.getUzbek(), parentName);
                }

            } else {
                // This is a main location (no branch)
                locationId = location.getObjectID();

                if (locLocale != null) {
                    enLocation = getNonEmptyOrDefault(locLocale.getEnglish(), locationName);
                    ruLocation = getNonEmptyOrDefault(locLocale.getRussian(), locationName);
                    uzLocation = getNonEmptyOrDefault(locLocale.getUzbek(), locationName);
                }
            }
        }

        keyValues.put(EmailTemplateConstants.HRMS.VACANCY.LOCATION_ID, locationId);
        keyValues.put(EmailTemplateConstants.HRMS.VACANCY.LOCATION_EN, enLocation);
        keyValues.put(EmailTemplateConstants.HRMS.VACANCY.LOCATION_RU, ruLocation);
        keyValues.put(EmailTemplateConstants.HRMS.VACANCY.LOCATION_UZ, uzLocation);

        keyValues.put(EmailTemplateConstants.HRMS.VACANCY.BRANCH_ID, branchId);
        keyValues.put(EmailTemplateConstants.HRMS.VACANCY.BRANCH_EN, enBranch);
        keyValues.put(EmailTemplateConstants.HRMS.VACANCY.BRANCH_RU, ruBranch);
        keyValues.put(EmailTemplateConstants.HRMS.VACANCY.BRANCH_UZ, uzBranch);


        keyValues.put(EmailTemplateConstants.HRMS.VACANCY.STATUS, vacancy.getStatus().getCode());
        if (vacancy.getPosition() != null) {
            keyValues.put(EmailTemplateConstants.HRMS.VACANCY.POSITION_ID, vacancy.getPosition().getObjectID());
            keyValues.put(EmailTemplateConstants.HRMS.VACANCY.POSITION_NAME, vacancy.getPosition().getName());
        }

        String descriptionLocalize = vacancy.getDescriptionLocalize();
        String responsibilityLocalize = vacancy.getResponsibilityLocalize();
        String jobRequirementsLocalize = vacancy.getJobRequirementsLocalize();

        putLocalizedField(
                keyValues,
                descriptionLocalize,
                EmailTemplateConstants.HRMS.VACANCY.DESCRIPTION_EN,
                EmailTemplateConstants.HRMS.VACANCY.DESCRIPTION_RU,
                EmailTemplateConstants.HRMS.VACANCY.DESCRIPTION_UZ,
                vacancy.getDescription()
        );

        putLocalizedField(
                keyValues,
                responsibilityLocalize,
                EmailTemplateConstants.HRMS.VACANCY.RESPONSIBILITIES_EN,
                EmailTemplateConstants.HRMS.VACANCY.RESPONSIBILITIES_RU,
                EmailTemplateConstants.HRMS.VACANCY.RESPONSIBILITIES_UZ,
                vacancy.getResponsibility()
        );

        putLocalizedField(
                keyValues,
                jobRequirementsLocalize,
                EmailTemplateConstants.HRMS.VACANCY.REQUIREMENTS_EN,
                EmailTemplateConstants.HRMS.VACANCY.REQUIREMENTS_RU,
                EmailTemplateConstants.HRMS.VACANCY.REQUIREMENTS_UZ,
                vacancy.getJobrequirements()
        );

        Integer companyId = user.getCompany().getObjectID();
        keyValues.put(EmailTemplateConstants.ET_COMPANY_ID, companyId);

        if (vacancy.getManager() != null) {
            keyValues.put(EmailTemplateConstants.HRMS.VACANCY.MANAGER_NAME, vacancy.getManager().getFullName());
            keyValues.put(EmailTemplateConstants.HRMS.VACANCY.MANAGER_EMAIL, vacancy.getManager().getEmail());
            keyValues.put(EmailTemplateConstants.HRMS.VACANCY.MANAGER_PHONE, vacancy.getManager().getEmployee() != null ? vacancy.getManager().getEmployee().getPrimaryPhone() : "");
        } else {
            keyValues.put(EmailTemplateConstants.HRMS.VACANCY.MANAGER_NAME, "");
            keyValues.put(EmailTemplateConstants.HRMS.VACANCY.MANAGER_EMAIL, "");
            keyValues.put(EmailTemplateConstants.HRMS.VACANCY.MANAGER_PHONE, "");
        }

        String employment = "";
        if (vacancy.getFullPartTime() != null) {
            EdsReference reference = referenceManager.get(vacancy.getFullPartTime());
            employment = reference != null ? reference.getDescription() != null ? reference.getDescription() : reference.getName() : "";
        }
        keyValues.put(EmailTemplateConstants.HRMS.VACANCY.EMPLOYMENT, employment);
        List<EdsVacancyQuestion> questions = vacancy.getCustomQuestions();

        if (questions != null && !questions.isEmpty()) {
            List<VacancyQuestionDTO> questionItems = questions.stream().map(q -> {
                EdsReference question = q.getQuestionReference();
                String uiType = q.getUiType();


                VacancyQuestionDTO dto = new VacancyQuestionDTO();
                dto.setFieldId(q.getFieldId());
                dto.setFieldName(q.getFieldName());
                dto.setUiType(uiType);

                if (question != null) {
                    dto.setQuestionId(question.getObjectID());
                    dto.setQuestion(question.getOriginalName());

                    if (question.getLocale() != null) {
                        EdsReferenceLocale locale = question.getLocale();
                        dto.setQuestionEn(locale.getEnglish() != null ? locale.getEnglish() : question.getOriginalName());
                        dto.setQuestionRu(locale.getRussian() != null ? locale.getRussian() : question.getOriginalName());
                        dto.setQuestionUz(locale.getUzbek() != null ? locale.getUzbek() : question.getOriginalName());
                    }
                }

                if ("LOOKUP".equals(uiType) || "MultiLookup".equals(uiType)) {
                    EdsReference lookUpReference = q.getLookUpReference();
                    if (lookUpReference != null) {
                        List<EdsReference> referenceItems = referenceManager.listReferencesByLimit(lookUpReference.getCode(), 25);
                        if (referenceItems != null && !referenceItems.isEmpty()) {
                            List<ReferenceValueItems> itemsList = new ArrayList<>();
                            for (EdsReference item : referenceItems) {
                                ReferenceValueItems referenceValueItems = new ReferenceValueItems();
                                referenceValueItems.setReferenceId(item.getObjectID());
                                referenceValueItems.setName(item.getOriginalName());
                                EdsReferenceLocale locale = item.getLocale();
                                if (locale != null) {
                                    referenceValueItems.setNameEn(locale.getEnglish() != null ? locale.getEnglish() : item.getOriginalName());
                                    referenceValueItems.setNameRu(locale.getRussian() != null ? locale.getRussian() : item.getOriginalName());
                                    referenceValueItems.setNameUz(locale.getUzbek() != null ? locale.getUzbek() : item.getOriginalName());
                                } else {
                                    referenceValueItems.setNameEn(item.getOriginalName());
                                    referenceValueItems.setNameRu(item.getOriginalName());
                                    referenceValueItems.setNameUz(item.getOriginalName());
                                }
                                itemsList.add(referenceValueItems);
                            }
                            dto.setReferenceItems(itemsList.toArray(new ReferenceValueItems[0]));
                        } else {
                            dto.setReferenceItems(new ReferenceValueItems[0]);
                        }
                    } else {
                        dto.setReferenceItems(new ReferenceValueItems[0]);
                    }
                } else {
                    dto.setReferenceItems(new ReferenceValueItems[0]);
                }

                return dto;

            }).collect(Collectors.toList());

            String questionsJson = new Gson().toJson(questionItems);
            keyValues.put(EmailTemplateConstants.HRMS.VACANCY.CUSTOM_QUESTIONS, questionsJson);

        } else {
            keyValues.put(EmailTemplateConstants.HRMS.VACANCY.CUSTOM_QUESTIONS, "[]");
        }

        return keyValues;
    }

    private void putLocalizedField(
            Map<String, Object> keyValues,
            String localizedJson,
            String keyEn,
            String keyRu,
            String keyUz,
            String defaultValue
    ) {
        defaultValue = (defaultValue == null) ? "{}" : defaultValue;
        String defaultName = Jsoup.parse(defaultValue.replace("\\n", "").trim()).text();
        if (defaultName.isEmpty() || defaultName.equals("{}")) {
            defaultName = "n/a";
        }

        try {


            if (localizedJson != null && !localizedJson.trim().equals("{}")) {
                Map<String, String> locMap = new ObjectMapper().readValue(localizedJson, new TypeReference<>() {
                });
                String en = Jsoup.parse(locMap.getOrDefault("en", "").replace("\\n", "").trim()).text();
                String ru = Jsoup.parse(locMap.getOrDefault("ru", "").replace("\\n", "").trim()).text();
                String uz = Jsoup.parse(locMap.getOrDefault("uz", "").replace("\\n", "").trim()).text();

                keyValues.put(keyEn, en);
                keyValues.put(keyRu, ru);
                keyValues.put(keyUz, uz);
            } else {
                keyValues.put(keyEn, defaultName);
                keyValues.put(keyRu, defaultName);
                keyValues.put(keyUz, defaultName);
            }
        } catch (Exception e) {
            keyValues.put(keyEn, defaultName);
            keyValues.put(keyRu, defaultName);
            keyValues.put(keyUz, defaultName);
        }
    }

    // Helper method
    private boolean isNotBlank(String value) {
        return value != null && !value.trim().isEmpty();
    }

    private String getNonEmptyOrDefault(String value, String defaultValue) {
        return isNotBlank(value) ? value : defaultValue;
    }

