    private Map<String, Object> getPurchaseInvoiceFieldValuesAsMap(final EdsPurchaseInvoice edsPurchaseInvoice, Map<String, Object> keyValues, final EdsUser user, boolean isWebhook) {
        keyValues = keyValues == null ? new HashMap<>() : keyValues;
        if (edsPurchaseInvoice != null) {
            Gson gson = new Gson();
            String link = "";
            final String host;
            if (user != null) {
                host = EdsContextParams.getHost(user.getCompany().getObjectID());
                link = host + "/Accounting.html?link=" + EncryptionHelper.encryptURL("purchaseinvoice|summary/" + edsPurchaseInvoice.getObjectID()) + "&" + Constants.C_ID + "=" + EncryptionHelper.encryptURL(user.getCompany().getObjectID().toString());
            }
            keyValues.put(EmailTemplateConstants.ET_LINK, link);
            keyValues.put(EmailTemplateConstants.ACCOUNTING.CREATED_DATE, edsPurchaseInvoice.getCreationDate() != null ? ServerUtils.shortDateFormat(ServerUtils.getCompanyDate(edsPurchaseInvoice.getCreationDate(), user.getCompany()), user) : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.UPDATED_DATE, edsPurchaseInvoice.getUpdatedDate() != null ? ServerUtils.shortDateFormat(ServerUtils.getCompanyDate(edsPurchaseInvoice.getModificationDate() != null ? edsPurchaseInvoice.getModificationDate() : new Date(), user.getCompany()), user) : "");

            keyValues.put(EmailTemplateConstants.HRMS.PREV_APPROVER, isOk(edsPurchaseInvoice.getPrevApprover()) && isOk(edsPurchaseInvoice.getPrevApprover().getExactEmployee()) ? edsPurchaseInvoice.getPrevApprover().getExactEmployee().getName() : "");
            keyValues.put(EmailTemplateConstants.HRMS.PREV_APPROVER_EMAIL, isOk(edsPurchaseInvoice.getPrevApprover()) && isOk(edsPurchaseInvoice.getPrevApprover().getExactEmployee()) ? edsPurchaseInvoice.getPrevApprover().getExactEmployee().getEmail() : "");
            keyValues.put(EmailTemplateConstants.HRMS.PREV_APPROVER_STATUS, isOk(edsPurchaseInvoice.getPrevApprover()) && isOk(edsPurchaseInvoice.getPrevApprover().getStatus()) ? edsPurchaseInvoice.getPrevApprover().getStatus().getName() : "");
            keyValues.put(EmailTemplateConstants.HRMS.CURRENT_APPROVER, isOk(edsPurchaseInvoice.getCurrentApprover()) && isOk(edsPurchaseInvoice.getCurrentApprover().getExactEmployee()) ? edsPurchaseInvoice.getCurrentApprover().getExactEmployee().getName() : "");
            keyValues.put(EmailTemplateConstants.HRMS.CURRENT_APPROVER_EMAIL, isOk(edsPurchaseInvoice.getCurrentApprover()) && isOk(edsPurchaseInvoice.getCurrentApprover().getExactEmployee()) ? edsPurchaseInvoice.getCurrentApprover().getExactEmployee().getEmail() : "");
            keyValues.put(EmailTemplateConstants.HRMS.CURRENT_APPROVER_STATUS, isOk(edsPurchaseInvoice.getCurrentApprover()) && isOk(edsPurchaseInvoice.getCurrentApprover().getStatus()) ? edsPurchaseInvoice.getCurrentApprover().getStatus().getName() : "");
            keyValues.put(EmailTemplateConstants.HRMS.NEXT_APPROVER, isOk(edsPurchaseInvoice.getNextApprover()) && isOk(edsPurchaseInvoice.getNextApprover().getExactEmployee()) ? edsPurchaseInvoice.getNextApprover().getExactEmployee().getName() : "");
            keyValues.put(EmailTemplateConstants.HRMS.NEXT_APPROVER_EMAIL, isOk(edsPurchaseInvoice.getNextApprover()) && isOk(edsPurchaseInvoice.getNextApprover().getExactEmployee()) ? edsPurchaseInvoice.getNextApprover().getExactEmployee().getEmail() : "");
            keyValues.put(EmailTemplateConstants.HRMS.NEXT_APPROVER_STATUS, isOk(edsPurchaseInvoice.getNextApprover()) && isOk(edsPurchaseInvoice.getNextApprover().getStatus()) ? edsPurchaseInvoice.getNextApprover().getStatus().getName() : "");

            StringBuilder telegramChats = new StringBuilder();
            List<EdsCrmContactItemParams> itemParams = edsPurchaseInvoice.getSupplier() != null ? edsPurchaseInvoice.getSupplier().getItemParams(CONTACT_TELEGRAMS) : null;
            if (itemParams != null && !itemParams.isEmpty()) {
                for (EdsCrmContactItemParams param : itemParams) {
                    if (telegramChats.toString().equals("")) {
                        telegramChats = new StringBuilder(param.getRelation() + ":" + param.getValue());
                    } else {
                        telegramChats.append(",").append(param.getRelation()).append(":").append(param.getValue());
                    }
                }
            }
            keyValues.put(EmailTemplateConstants.ET_SUPPLIER_TELEGRAM, telegramChats.toString());

            keyValues.put(EmailTemplateConstants.ID, edsPurchaseInvoice.getObjectID() != null ? edsPurchaseInvoice.getObjectID() : "");
            keyValues.put(EmailTemplateConstants.OBJECT_KEY, edsPurchaseInvoice.getObjectKey() != null ? edsPurchaseInvoice.getObjectKey() : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.EXCHANGE_RATE, edsPurchaseInvoice.getExchangeRate());
            String priceLevel = "";
            if (edsPurchaseInvoice.getPriceLevelID() != null) {
                EdsPriceLevel edsPriceLevel = priceLevelManager.get(edsPurchaseInvoice.getPriceLevelID());
                if (edsPriceLevel != null) {
                    if (isWebhook) {
                        priceLevel = gson.toJson(new ItemDto(edsPriceLevel.getObjectID(), edsPriceLevel.getName()));
                    } else {
                        priceLevel = edsPriceLevel.getName();
                    }
                }
            }
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRICE_LEVEL, priceLevel);

            if (isWebhook) {
                String cust = "";
                if (edsPurchaseInvoice.getSupplier() != null) {
                    EdsCrmAccount edsSupplier = edsPurchaseInvoice.getSupplier();
                    ItemDto supplier = new ItemDto(edsSupplier.getObjectID(), edsSupplier.getName(), edsSupplier.getNumber());
                    cust = gson.toJson(supplier);
                    keyValues.put(EmailTemplateConstants.ET_SUPPLIER_INTEGRATION_ID, edsSupplier.getIntegrationId() != null ? edsSupplier.getIntegrationId() : "");
                }
                keyValues.put(EmailTemplateConstants.ET_CUSTOMER, cust);
            }
            keyValues.put(EmailTemplateConstants.ET_NUMBER, edsPurchaseInvoice.getNumber() != null ? edsPurchaseInvoice.getNumber() : "");
            if (isWebhook) {
                String project = "";
                if (edsPurchaseInvoice.getRelatedProject() != null) {
                    EdsProject edsProject = edsPurchaseInvoice.getRelatedProject();
                    ItemDto relatedProject = new ItemDto(edsProject.getObjectID(), edsProject.getName(), edsProject.getNumber());
                    project = gson.toJson(relatedProject);
                }
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PROJECT, project);
            }

            TaxTypeEnum type = TaxTypeEnum.getTaxTypeById(edsPurchaseInvoice.getTaxCalculationType());
            keyValues.put(EmailTemplateConstants.ACCOUNTING.TAX_CALC_TYPE, type != null ? type.getName() : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.INVOICE_DATE, edsPurchaseInvoice.getInvoiceDate() != null ? edsPurchaseInvoice.getInvoiceDate() : "");
            List<EdsInvoiceItem> invoiceItems = invoiceItemManager.getByInvoiceIds(List.of(edsPurchaseInvoice.getObjectID()));
            keyValues.put(EmailTemplateConstants.ACCOUNTING.INVOICE_ITEMS, invoiceItems);

            if (edsPurchaseInvoice.getInvoiceItems() != null) {
                if (isWebhook) {
                    List<LineItemDto> lineItemDtoList = new ArrayList<>();
                    for (EdsInvoiceItem invoiceItem : edsPurchaseInvoice.getInvoiceItems()) {
                        LineItemDto lineItemDto = invoiceCircularResolver.wrapListItemToDto(invoiceItem, edsPurchaseInvoice.getItemCustomFields(), ApiConstants.PURCHASE_INVOICE);
                        lineItemDtoList.add(lineItemDto);
                    }
                    keyValues.put(EmailTemplateConstants.ACCOUNTING.ITEMS, gson.toJson(lineItemDtoList));
                }
            }
            keyValues.put(EmailTemplateConstants.ACCOUNTING.IS_CREDIT_NOTE, edsPurchaseInvoice.isCreditNote() != null && edsPurchaseInvoice.isCreditNote());
            String accountsReceivable = "";
            if (edsPurchaseInvoice.getReceivablePayable() != null) {
                EdsAccount rpAccount = edsPurchaseInvoice.getReceivablePayable();
                if (isWebhook) {
                    accountsReceivable = gson.toJson(new IdCode(rpAccount.getObjectID(), rpAccount.getAccountCode()));
                } else {
                    accountsReceivable = rpAccount.getName();
                }
            }
            keyValues.put(EmailTemplateConstants.ACCOUNTING.ACCOUNTS_RECEIVABLE, accountsReceivable);
            String convertedItem = "";
            if (!org.springframework.util.CollectionUtils.isEmpty(edsPurchaseInvoice.getConvertedQuotes())) {
                EdsQuote quote = edsPurchaseInvoice.getConvertedQuotes().iterator().next();
                if (isWebhook) {
                    convertedItem = gson.toJson(new IdCode(quote.getObjectID(), quote.getNumber(), quote.getObjectKey()));
                } else {
                    convertedItem = quote.getNumber();
                }
            }
            keyValues.put(EmailTemplateConstants.ACCOUNTING.CONVERTED_ITEM, convertedItem);

            BigDecimal paidAmount = null;
            if (!org.springframework.util.CollectionUtils.isEmpty(edsPurchaseInvoice.getPayments())) {
                if (isWebhook) {
                    String payments = gson.toJson(edsPurchaseInvoice.getPayments().stream().filter(payment -> !payment.isDeleted() && (payment.getStatus() == null || !REVERSED.equals(payment.getStatus().getCode()))).map(payment -> invoiceCircularResolver.wrapPaymentToDto(payment)).collect(Collectors.toList()));
                    keyValues.put(EmailTemplateConstants.ACCOUNTING.PAYMENTS, payments);
                }
                paidAmount = edsPurchaseInvoice.getPayments().stream()
                        .filter(payment -> !payment.isDeleted() && (payment.getStatus() == null || !REVERSED.equals(payment.getStatus().getCode())))
                        .reduce(BigDecimal.ZERO, (total, payment) -> total.add(Optional.ofNullable(payment.getAmountInInvoiceCurrency()).orElse(payment.getAmount())), BigDecimal::add);
            } else {
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PAYMENTS, "");
            }
            if (!org.springframework.util.CollectionUtils.isEmpty(edsPurchaseInvoice.getRefunds())) {
                if (isWebhook) {
                    String refunds = gson.toJson(edsPurchaseInvoice.getRefunds().stream().filter(refund -> !refund.isDeleted() && (refund.getStatus() == null || !REVERSED.equals(refund.getStatus().getCode()))).map(refund -> invoiceCircularResolver.wrapPaymentToDto(refund)).collect(Collectors.toList()));
                    keyValues.put(EmailTemplateConstants.ACCOUNTING.REFUNDS, refunds);
                }
                paidAmount = edsPurchaseInvoice.getRefunds().stream()
                        .filter(refund -> !refund.isDeleted() && (refund.getStatus() == null || !REVERSED.equals(refund.getStatus().getCode())))
                        .reduce(BigDecimal.ZERO, (total, refund) -> total.add(Optional.ofNullable(refund.getAmountInInvoiceCurrency()).orElse(refund.getAmount())), BigDecimal::add);
            } else {
                keyValues.put(EmailTemplateConstants.ACCOUNTING.REFUNDS, "");
            }
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PAID_AMOUNT, paidAmount != null ? paidAmount : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.DUE_AMOUNT, edsPurchaseInvoice.getDueAmount() != null ? edsPurchaseInvoice.getDueAmount() : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.CURRENCY, edsPurchaseInvoice.getCurrency() != null ? edsPurchaseInvoice.getCurrency().getName() : "");

            if (edsPurchaseInvoice.getInvoiceTerms() != null) {
                if (isWebhook) {
                    keyValues.put(EmailTemplateConstants.ACCOUNTING.TERMS, gson.toJson(new IdName(edsPurchaseInvoice.getInvoiceTerms().getObjectID(), edsPurchaseInvoice.getInvoiceTerms().getName())));
                }
            } else {
                keyValues.put(EmailTemplateConstants.ACCOUNTING.TERMS, "");
            }
            keyValues.put(EmailTemplateConstants.ACCOUNTING.DUE_DATE_TYPE, edsPurchaseInvoice.getInvoiceTerms() != null ? "TERMS" : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.STATUS_CODE, edsPurchaseInvoice.getStatus() != null ? edsPurchaseInvoice.getStatus().getCode() : "");
        }
        if (isWebhook && ServerUtils.isArabicCompany(userManager.getUser().getCompany())) {
            keyValues.put(EmailTemplateConstants.ACCOUNTING.TAXILLA_ACCESS_TOKEN, "");
        }
        return keyValues;
    }

