    private Map<String, Object> getDepartmentFieldValuesAsMap(EdsDepartment department, Map<String, Object> keyValues, EdsUser user) {
        keyValues = keyValues == null ? new HashMap<>() : keyValues;
        if (department != null) {
            keyValues.put(EmailTemplateConstants.HRMS.UNIQUE_ID, department.getExternalGUID() != null ? department.getExternalGUID() : "");
            SelectItem parentDept = departmentTreeManager.getParentItem(department.getObjectID());
            keyValues.put(EmailTemplateConstants.HRMS.PARENT_UNIQUE_ID, parentDept != null ? parentDept.getDescription() : "");
            String englishName = "";
            String russianName = "";
            String uzbekName = "";
            String arabicName = "";
            if (department.getLocale() != null) {
                englishName = department.getLocale().getEnglish();
                russianName = department.getLocale().getRussian();
                uzbekName = department.getLocale().getUzbek();
                arabicName = department.getLocale().getArabic();
            }
            keyValues.put(EmailTemplateConstants.HRMS.ENGLISH_NAME, englishName != null ? englishName : "");
            keyValues.put(EmailTemplateConstants.HRMS.RUSSIAN_NAME, russianName != null ? russianName : "");
            keyValues.put(EmailTemplateConstants.HRMS.UZBEK_NAME, uzbekName != null ? uzbekName : "");
            keyValues.put(EmailTemplateConstants.HRMS.ARABIC_NAME, arabicName != null ? arabicName : "");
        }
        return keyValues;
    }

