    private Map<String, Object> getProductFieldValuesAsMap(EdsItem edsItem, Map<String, Object> keyValues, EdsUser user, boolean isWebHook) {
        keyValues = keyValues == null ? new HashMap<>() : keyValues;
        if (edsItem != null) {
            Gson gson = new Gson();
            keyValues.put(EmailTemplateConstants.ID, edsItem.getObjectID());
            keyValues.put(EmailTemplateConstants.OBJECT_KEY, edsItem.getObjectKey());
            keyValues.put(EmailTemplateConstants.ACCOUNTING.ACTIVE, edsItem.isActive());
            keyValues.put(EmailTemplateConstants.ACCOUNTING.TYPE, edsItem.getTypeName());

            String id = "";
            String name = "";
            String code = "";
            if (edsItem.getAccount() != null) {
                id = edsItem.getAccount().getObjectID().toString();
                name = edsItem.getAccount().getName();
                code = edsItem.getAccount().getCodeString();
            }
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.SALES_ACCOUNT_ID, id);
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.SALES_ACCOUNT_NAME, name);
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.SALES_ACCOUNT_CODE, code);

            id = "";
            code = "";
            if (edsItem.getCogsAccount() != null) {
                id = edsItem.getCogsAccount().getObjectID().toString();
                code = edsItem.getCogsAccount().getCodeString();
            }
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.COGS_ACCOUNT_ID, id);
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.COGS_ACCOUNT_CODE, code);
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.PURCHASED_FROM_SUPPLIER, edsItem.isPurchasedFromSupplier() != null ? edsItem.isPurchasedFromSupplier() : true);
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.CATEGORY_ID, edsItem.getCategory() != null ? edsItem.getCategory().getObjectID() : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.BRAND_ID, edsItem.getBrand() != null ? edsItem.getBrand().getObjectID() : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.TAX_ID, edsItem.getVat() != null ? edsItem.getVat().getObjectID() : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.SKU_NUMBER, edsItem.getInternalSKUNumber() != null ? edsItem.getInternalSKUNumber() : "");

            id = "";
            code = "";
            if (edsItem.getUnitMeasurement() != null) {
                id = edsItem.getUnitMeasurement().getObjectID().toString();
                code = edsItem.getUnitMeasurement().getName();
            }
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.UNIT_MEASUREMENT_ID, id);
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.UNIT_MEASUREMENT_CODE, code);

            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.PART_NUMBER, edsItem.getPartNumber() != null ? edsItem.getPartNumber() : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.UPC_NUMBER, edsItem.getUpcNumber() != null ? edsItem.getUpcNumber() : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.MANUFACTURER, edsItem.getManufacturer() != null ? edsItem.getManufacturer() : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.CREATED_DATE, edsItem.getCreationTime());
            keyValues.put(EmailTemplateConstants.ACCOUNTING.UPDATED_DATE, edsItem.getLastUpdateTime());
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.SELLING_PRICE, edsItem.getSellingPrice() != null ? edsItem.getSellingPrice() : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.PURCHASE_PRICE, edsItem.getUnitPrice() != null ? edsItem.getUnitPrice() : "");

            if (edsItem.getDiscounts() != null && !edsItem.getDiscounts().isEmpty()) {
                String discount;
                if (isWebHook) {
                    List<IdCode> discounts = edsItem.getDiscounts().stream().map(d -> new IdCode(d.getObjectID(), d.getName())).collect(Collectors.toList());
                    discount = gson.toJson(discounts);
                } else {
                    discount = edsItem.getDiscounts().stream().map(EdsDiscount::getName).collect(Collectors.joining(","));
                }
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.DISCOUNT, discount);
            } else {
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.DISCOUNT, "");
            }

            if (edsItem.getItemsInStock() != null) {
                String quantity = edsItem.getItemsInStock().compareTo(BigDecimal.ZERO) < 0 ? "(" + new BigDecimal(-1).multiply(edsItem.getItemsInStock()) + ")" : edsItem.getItemsInStock().toString();
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.QUANTITY, quantity);
            } else {
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.QUANTITY, "0");
            }

            String pictureLink = "";
            List<EdsProductPicture> pictures = productPictureManager.getProductPictures(edsItem, 0);
            if (pictures != null && !pictures.isEmpty()) {
                for (EdsProductPicture p : pictures) {
                    if (p.isDefaultPicture()) {
                        pictureLink = uploadManager.getFileURL(p);
                    }
                }
            }
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.IMAGE_URL, pictureLink);

            if (edsItem.getSuppliers() != null && !edsItem.getSuppliers().isEmpty()) {
                String supplier;
                if (isWebHook) {
                    List<IdCode> suppliers = edsItem.getSuppliers().stream().map(d -> new IdCode(d.getObjectID(), d.getName())).collect(Collectors.toList());
                    supplier = gson.toJson(suppliers);
                } else {
                    supplier = edsItem.getSuppliers().stream().map(EdsCrmAccount::getName).collect(Collectors.joining(","));
                }
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.SUPPLIER, supplier);
            } else {
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.SUPPLIER, "");
            }
            String warehouse = "";
            if (edsItem.getDefaultWarehouse() != null) {
                if (isWebHook) {
                    warehouse = gson.toJson(new ItemDto(edsItem.getDefaultWarehouse().getObjectID(), edsItem.getDefaultWarehouse().getName()));
                } else {
                    warehouse = edsItem.getDefaultWarehouse().getName();
                }
            }
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.WAREHOUSE, warehouse);

            List<EdsPriceLevelPP> priceLevels = priceLevelPPManager.getByPriceLevelsByProductId(edsItem.getObjectID());
            if (isWebHook && priceLevels != null && !priceLevels.isEmpty()) {
                List<PriceLevelDto> dtos = new ArrayList<>();
                for (EdsPriceLevelPP pp : priceLevels) {
                    if (pp.getPriceLevel() != null) {
                        PriceLevelDto dto = new PriceLevelDto();
                        dto.setPriceLevel(new IdCode(pp.getPriceLevel().getObjectID(), pp.getPriceLevel().getName()));
                        dto.setCustomPrice(BigDecimal.valueOf(pp.getCustomPrice()));
                        dtos.add(dto);
                    }
                }
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRICE_LEVEL, gson.toJson(dtos));
            } else {
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRICE_LEVEL, "");
            }

            if (edsItem.getType().equals(INVENTORY_ITEM)) {
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.INVENTORY_STOCK_AS_OF_DATE, edsItem.getAsOf() != null ? new DateNonConvertable(edsItem.getAsOf()).getDate() : "");
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.INVENTORY_STOCK_BATCH_TRACKING, edsItem.getBatchTrackingEnabled());
                String assetAccount = "";
                if (isWebHook) {
                    assetAccount = gson.toJson(new IdCode(edsItem.getAssetAccount().getObjectID(), edsItem.getAssetAccount().getAccountCode(), edsItem.getObjectKey()));
                } else {
                    assetAccount = edsItem.getAssetAccount().getName();
                }
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.INVENTORY_ASSET_ACCOUNT, assetAccount);
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.INVENTORY_TRACKING, edsItem.getInventoryTrackingEnabled());
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.TRACK_BATCH, edsItem.getTrackBatchesEnabled());
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.TOTAL_VALUE, edsItem.getTotalValue());

                NewProduct newProduct = new NewProduct();
                productServiceLocal.initProductWarehouseLocations(newProduct, edsItem, null);
                if (newProduct.getProductLocations() != null && newProduct.getProductLocations().length > 0) {
                    String location;
                    if (isWebHook) {
                        List<ProductLocationDto> productLocations = new ArrayList<>();
                        for (ProductLocationItem productLocationItem : newProduct.getProductLocations()) {
                            ProductLocationDto productLocationDto = new ProductLocationDto();
                            productLocationDto.setQtyOnHand(productLocationItem.getQty());
                            productLocationDto.setReorderPoint(productLocationItem.getMinReorderPoint());
                            productLocationDto.setWarehouse(new IdName(productLocationItem.getWarehouseID(), productLocationItem.getWarehouseName()));
                            productLocationDto.setObjectId(productLocationItem.getObjectID());

                            productLocations.add(productLocationDto);
                        }
                        location = gson.toJson(productLocations);
                    } else {
                        location = Arrays.stream(newProduct.getProductLocations()).map(ProductLocationItem::getWarehouseName).collect(Collectors.joining(","));
                    }
                    keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.LOCATION, location);
                } else {
                    keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.LOCATION, "");
                }
            } else {
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.INVENTORY_STOCK_AS_OF_DATE, "");
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.INVENTORY_STOCK_BATCH_TRACKING, "");
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.INVENTORY_ASSET_ACCOUNT, "");
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.INVENTORY_TRACKING, "");
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.TRACK_BATCH, "");
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.TOTAL_VALUE, "");
                keyValues.put(EmailTemplateConstants.ACCOUNTING.PRODUCT.LOCATION, "");
            }
        }
        return keyValues;
    }

