    private void getCustomFieldValues(EdsCustomFormItems edsCustomForm, Map<String, Object> keyValues, EdsUser user, boolean isWebhook) {
        List<EdsModelField> fields = this.modelFieldManager.getFieldsForWorkflowAlert(edsCustomForm.getCustomForm().getFormID());
        List<EdsCompanyCustomFieldsSettings> cfs = companyCFManager.getCompanyCustomFieldsWithCategory("CustomFormItems", CUSTOM_VIEW + edsCustomForm.getCustomForm().getFormID().substring(0, edsCustomForm.getCustomForm().getFormID().indexOf("_FORM")));
        Map<String, EdsCompanyCustomFieldsSettings> cfsMap = new LinkedHashMap<>();
        Gson gson = new Gson();
        Map<String, String> map = gson.fromJson(edsCustomForm.getFormCustomFields().getJsonEntities(), Map.class);
        cfs.forEach(cf -> cfsMap.put(cf.getColumnCode(), cf));
        if (user != null) {
            for (EdsModelField field : fields) {
                if (field.getField_ID().contains("string_value")) {
                    EdsCompanyCustomFieldsSettings cfSettings = cfsMap.get(field.getField_ID());
                    if (cfSettings.getUiType().equals(TYPE_ENTITY_LOOKUP)) {
                        String value = edsCustomForm.getFormCustomFields().getStringValue(field.getField_ID());
                        SelectItem[] result = companyCFManager.getCustomFieldDataByQuery(SecurityContext.getCompanyID(), cfSettings.getQuery());
                        String name = "";
                        if (value != null && !"".equals(value)) {
                            Integer id = Integer.parseInt(value);
                            for (SelectItem item : result) {
                                if (item.getId().equals(id)) {
                                    name = item.getDescription() != null ? item.getDescription() : item.getName();
                                }
                            }
                        }
                        keyValues.put("${" + field.getField_ID() + "}", name);
                        keyValues.put("${" + field.getField_ID() + "_id}", value);
                    } else if (cfSettings.getUiType().equals(UI_TYPE_LOOKUP) && isWebhook) {
                        keyValues.put("${" + field.getField_ID() + "}", map.get(field.getField_ID()) != null ? map.get(field.getField_ID()) : "");
                    } else {
                        keyValues.put("${" + field.getField_ID() + "}", edsCustomForm.getFormCustomFields().getStringValue(field.getField_ID()) != null ?
                                edsCustomForm.getFormCustomFields().getStringValue(field.getField_ID()) : "");
                    }
                } else if (field.getField_ID().contains("date_value")) {
                    String value = "";
                    Date date = ServerUtils.getCompanyDate(edsCustomForm.getFormCustomFields().getDateValue(field.getField_ID()), user.getCompany());
                    if (isWebhook) {
                        SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd");
                        if (date != null) {
                            value = dateFormat.format(date);
                        }
                    } else {
                        value = ServerUtils.shortDateFormat(date, false, user);
                    }
                    keyValues.put("${" + field.getField_ID() + "}", value);
                } else if (field.getField_ID().contains("double_value")) {
                    keyValues.put("${" + field.getField_ID() + "}", edsCustomForm.getFormCustomFields().getDoubleValue(field.getField_ID()) != null ?
                            edsCustomForm.getFormCustomFields().getDoubleValue(field.getField_ID()) : "");
                }
            }
        }

    }

    private Map<String, Object> getEmployeeStepFieldValuesMap(final EdsStepEmployee employeeStep, Map<String, Object> keyValues, final EdsUser user) {
        keyValues = keyValues == null ? new HashMap<>() : keyValues;
        if (employeeStep != null) {
            String stepEmployeeLink = "";
            final String host;
            if (user != null) {
                host = EdsContextParams.getHost(user.getCompany().getObjectID());
                stepEmployeeLink = host + "/Hrms.html?link=" + EncryptionHelper.encryptURL(Constants.EMPLOYEE_STEP + "|add/add/" + employeeStep.getObjectID() + "/" + employeeStep.getOnboardingStep().getObjectID() + "/" + employeeStep.getOnboardingStep().getFormID() + "/" + employeeStep.getOnboardingStep().getName()) + "&" + Constants.C_ID + "=" + EncryptionHelper.encryptURL(user.getCompany().getObjectID().toString());
            }
            keyValues.put(EmailTemplateConstants.ET_LINK, stepEmployeeLink);
            final StringBuilder approvers = new StringBuilder();
            boolean isNotFirst = false;
            for (final EdsApprover approver : employeeStep.getApprovers()) {
                if (isNotFirst) {
                    approvers.append(", ");
                }
                isNotFirst = true;
                approvers.append(approver.getExactEmployee().getFullName());
            }
            String firstApprover = "";
            String secondApprover = "";
            String thirdApprover = "";
            String fourthApprover = "";
            String fifthApprover = "";
            boolean first = true, second = true, third = true, fourth = true, fifth = true;
            if (employeeStep.getApprovers() != null && employeeStep.getApprovers().size() > 0) {
                final ListIterator<EdsApprover> iterator = employeeStep.getApprovers().listIterator();
                while (iterator.hasNext()) {
                    if (first) {
                        final EdsApprover edsApprover = iterator.next();
                        if (edsApprover != null && edsApprover.getExactEmployee() != null) {
                            firstApprover = edsApprover.getExactEmployee().getEmail();
                            first = false;
                        }
                    } else if (second) {
                        final EdsApprover edsApprover = iterator.next();
                        if (edsApprover != null && edsApprover.getExactEmployee() != null) {
                            secondApprover = edsApprover.getExactEmployee().getEmail();
                            second = false;
                        }
                    } else if (third) {
                        final EdsApprover edsApprover = iterator.next();
                        if (edsApprover != null && edsApprover.getExactEmployee() != null) {
                            thirdApprover = edsApprover.getExactEmployee().getEmail();
                            third = false;
                        }
                    } else if (fourth) {
                        final EdsApprover edsApprover = iterator.next();
                        if (edsApprover != null && edsApprover.getExactEmployee() != null) {
                            fourthApprover = edsApprover.getExactEmployee().getEmail();
                            fourth = false;
                        }
                    } else {
                        final EdsApprover edsApprover = iterator.next();
                        if (edsApprover != null && edsApprover.getExactEmployee() != null) {
                            fifthApprover = edsApprover.getExactEmployee().getEmail();
                            fifth = false;
                        }
                    }
                    if (!first && !second && !third && !fourth && !fifth) {
                        break;
                    }
                }
            }
            String employeeOrCandidateName = employeeStep.getType() != null && EdsStepEmployee.CANDIDATE_TYPE.equals(employeeStep.getType().getCode()) && employeeStep.getCandidate() != null ? employeeStep.getCandidate().getName() : null;
            employeeOrCandidateName = employeeOrCandidateName != null ? employeeOrCandidateName : (employeeStep.getEmployee() != null ? employeeStep.getEmployee().getName() : null);
            keyValues.put(EmailTemplateConstants.ET_EMPLOYEE, employeeOrCandidateName != null ? employeeOrCandidateName : "");
            String employeeOrCandidateCode = employeeStep.getType() != null && EdsStepEmployee.CANDIDATE_TYPE.equals(employeeStep.getType().getCode()) && employeeStep.getCandidate() != null ? employeeStep.getCandidate().getNumber() : null;
            employeeOrCandidateCode = employeeOrCandidateCode != null ? employeeOrCandidateCode : (employeeStep.getEmployee() != null && employeeStep.getEmployee().getProfile() != null ? employeeStep.getEmployee().getProfile().getEmployeeCode() : null);
            keyValues.put(EmailTemplateConstants.HRMS.EMPLOYEE_CODE, employeeOrCandidateCode != null ? employeeOrCandidateCode : "");
            keyValues.put(EmailTemplateConstants.ET_APPROVERS, approvers.toString());
            keyValues.put(EmailTemplateConstants.ET_EMAIL, employeeStep.getEmployee() != null && employeeStep.getEmployee().getEmail() != null ? employeeStep.getEmployee().getEmail() :
                    (employeeStep.getCandidate() != null && employeeStep.getCandidate().getPrimaryEmail() != null ? employeeStep.getCandidate().getPrimaryEmail() : ""));
            keyValues.put(EmailTemplateConstants.ACCOUNTING.CREATED_DATE, employeeStep.getAuditInfo() != null ? ServerUtils.shortDateFormat(ServerUtils.getCompanyDate(employeeStep.getAuditInfo().getCreationDate(), user.getCompany()), user) : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.UPDATED_DATE, employeeStep.getAuditInfo() != null ? ServerUtils.shortDateFormat(ServerUtils.getCompanyDate(employeeStep.getAuditInfo().getModificationDate(), user.getCompany()), user) : "");
            keyValues.put(EmailTemplateConstants.PAYROLL.FIRST_APPROVER_EMAIL, firstApprover != null ? firstApprover : "");
            keyValues.put(EmailTemplateConstants.PAYROLL.SECOND_APPROVER_EMAIL, secondApprover != null ? secondApprover : "");
            keyValues.put(EmailTemplateConstants.PAYROLL.THIRD_APPROVER_EMAIL, thirdApprover != null ? thirdApprover : "");
            keyValues.put(EmailTemplateConstants.PAYROLL.FOURTH_APPROVER_EMAIL, fourthApprover != null ? fourthApprover : "");
            keyValues.put(EmailTemplateConstants.PAYROLL.FIFTH_APPROVER_EMAIL, fifthApprover != null ? fifthApprover : "");

            keyValues.put(EmailTemplateConstants.HRMS.PREV_APPROVER, isOk(employeeStep.getPrevApprover()) && isOk(employeeStep.getPrevApprover().getExactEmployee()) ? employeeStep.getPrevApprover().getExactEmployee().getName() : "");
            keyValues.put(EmailTemplateConstants.HRMS.PREV_APPROVER_EMAIL, isOk(employeeStep.getPrevApprover()) && isOk(employeeStep.getPrevApprover().getExactEmployee()) ? employeeStep.getPrevApprover().getExactEmployee().getEmail() : "");
            keyValues.put(EmailTemplateConstants.HRMS.PREV_APPROVER_STATUS, isOk(employeeStep.getPrevApprover()) && isOk(employeeStep.getPrevApprover().getStatus()) ? employeeStep.getPrevApprover().getStatus().getName() : "");
            keyValues.put(EmailTemplateConstants.HRMS.CURRENT_APPROVER, isOk(employeeStep.getCurrentApprover()) && isOk(employeeStep.getCurrentApprover().getExactEmployee()) ? employeeStep.getCurrentApprover().getExactEmployee().getName() : "");
            keyValues.put(EmailTemplateConstants.HRMS.CURRENT_APPROVER_EMAIL, isOk(employeeStep.getCurrentApprover()) && isOk(employeeStep.getCurrentApprover().getExactEmployee()) ? employeeStep.getCurrentApprover().getExactEmployee().getEmail() : "");
            keyValues.put(EmailTemplateConstants.HRMS.CURRENT_APPROVER_STATUS, isOk(employeeStep.getCurrentApprover()) && isOk(employeeStep.getCurrentApprover().getStatus()) ? employeeStep.getCurrentApprover().getStatus().getName() : "");
            keyValues.put(EmailTemplateConstants.HRMS.NEXT_APPROVER, isOk(employeeStep.getNextApprover()) && isOk(employeeStep.getNextApprover().getExactEmployee()) ? employeeStep.getNextApprover().getExactEmployee().getName() : "");
            keyValues.put(EmailTemplateConstants.HRMS.NEXT_APPROVER_EMAIL, isOk(employeeStep.getNextApprover()) && isOk(employeeStep.getNextApprover().getExactEmployee()) ? employeeStep.getNextApprover().getExactEmployee().getEmail() : "");
            keyValues.put(EmailTemplateConstants.HRMS.NEXT_APPROVER_STATUS, isOk(employeeStep.getNextApprover()) && isOk(employeeStep.getNextApprover().getStatus()) ? employeeStep.getNextApprover().getStatus().getName() : "");
        }
        return keyValues;
    }

    private Map<String, Object> getEmployeeCertificateFieldValuesMap(final EdsCertificateOfEmployment employeeCertificate, Map<String, Object> keyValues, final EdsUser user) {
        keyValues = keyValues == null ? new HashMap<>() : keyValues;
        if (employeeCertificate != null) {
            String link = "";
            final String host;
            if (user != null) {
                host = EdsContextParams.getHost(user.getCompany().getObjectID());
                link = host + "/Hrms.html?link=" + EncryptionHelper.encryptURL("certificate|summary/" + employeeCertificate.getObjectID() + "&" + Constants.C_ID + "=" + EncryptionHelper.encryptURL(user.getCompany().getObjectID().toString()));
            }
            final StringBuilder approvers = new StringBuilder();
            boolean isNotFirst = false;
            for (final EdsApprover approver : employeeCertificate.getApprovers()) {
                if (isNotFirst) {
                    approvers.append(", ");
                }
                isNotFirst = true;
                approvers.append(approver.getExactEmployee().getFullName());
            }
            if (employeeCertificate.getEmployee() != null) {
                keyValues.put(EmailTemplateConstants.ET_EMAIL, employeeCertificate.getEmployee().getEmail() != null ? employeeCertificate.getEmployee().getEmail() : "");
                keyValues.put(EmailTemplateConstants.HRMS.EMPLOYEE_CODE, employeeCertificate.getEmployee().getProfile() != null &&
                        employeeCertificate.getEmployee().getProfile().getEmployeeCode() != null ? employeeCertificate.getEmployee().getProfile().getEmployeeCode() : "");
            }
            keyValues.put(EmailTemplateConstants.ET_APPROVERS, approvers.toString());
            keyValues.put(EmailTemplateConstants.CRM.EVENT.CREATOR_EMAIL, employeeCertificate.getCreaterBy() != null ? employeeCertificate.getCreaterBy().getFullName() : "");
            keyValues.put(EmailTemplateConstants.PENALTIES_PROMOTIONS.PP_CREATOR_NAME, employeeCertificate.getCreaterBy() != null ? employeeCertificate.getCreaterBy().getEmail() : "");
            keyValues.put(EmailTemplateConstants.HRMS.EMPLOYEE_CERTIFICATE.REJECTION_NOTE, employeeCertificate.getRejectionNote() != null ? employeeCertificate.getRejectionNote() : "");
            keyValues.put(EmailTemplateConstants.ET_LINK, link);

            StringBuilder employeeTelegramChats = new StringBuilder();
            List<EdsCrmContactItemParams> employeeItemParams = employeeCertificate.getEmployee() != null && employeeCertificate.getEmployee().getContact() != null ?
                    employeeCertificate.getEmployee().getContact().getItemParams(CONTACT_TELEGRAMS) : null;
            if (employeeItemParams != null && !employeeItemParams.isEmpty()) {
                for (EdsCrmContactItemParams param : employeeItemParams) {
                    if (employeeTelegramChats.toString().equals("")) {
                        employeeTelegramChats = new StringBuilder(param.getRelation() + ":" + param.getValue());
                    } else {
                        employeeTelegramChats.append(",").append(param.getRelation()).append(":").append(param.getValue());
                    }
                }
            }
            keyValues.put(EmailTemplateConstants.ET_EMPLOYEE_TELEGRAM, employeeTelegramChats.toString());
        }
        return keyValues;
    }

