            keyValues.put(EmailTemplateConstants.HRMS.CURRENT_APPROVER, isOk(edsManualJournal.getCurrentApprover()) && isOk(edsManualJournal.getCurrentApprover().getExactEmployee()) ? edsManualJournal.getCurrentApprover().getExactEmployee().getName() : "");
            keyValues.put(EmailTemplateConstants.HRMS.CURRENT_APPROVER_EMAIL, isOk(edsManualJournal.getCurrentApprover()) && isOk(edsManualJournal.getCurrentApprover().getExactEmployee()) ? edsManualJournal.getCurrentApprover().getExactEmployee().getEmail() : "");
            keyValues.put(EmailTemplateConstants.HRMS.CURRENT_APPROVER_STATUS, isOk(edsManualJournal.getCurrentApprover()) && isOk(edsManualJournal.getCurrentApprover().getStatus()) ? edsManualJournal.getCurrentApprover().getStatus().getName() : "");
            keyValues.put(EmailTemplateConstants.HRMS.NEXT_APPROVER, isOk(edsManualJournal.getNextApprover()) && isOk(edsManualJournal.getNextApprover().getExactEmployee()) ? edsManualJournal.getNextApprover().getExactEmployee().getName() : "");
            keyValues.put(EmailTemplateConstants.HRMS.NEXT_APPROVER_EMAIL, isOk(edsManualJournal.getNextApprover()) && isOk(edsManualJournal.getNextApprover().getExactEmployee()) ? edsManualJournal.getNextApprover().getExactEmployee().getEmail() : "");
