    private Map<String, Object> getAdditionalPaymentFieldValuesMap(final EdsAdditionalPayment edsAdditionalPayment, Map<String, Object> keyValues, final EdsUser user, boolean isWebhook) {
        keyValues = keyValues == null ? new HashMap<>() : keyValues;
        Gson gson = new Gson();
        if (edsAdditionalPayment != null) {
            keyValues.put(EmailTemplateConstants.ID, edsAdditionalPayment.getObjectID());
            keyValues.put(EmailTemplateConstants.PAYROLL.CATEGORY, edsAdditionalPayment.getCategoryType() != null ? edsAdditionalPayment.getCategoryType() : "");
            keyValues.put(EmailTemplateConstants.PAYROLL.TYPE, edsAdditionalPayment.getType() != null ? edsAdditionalPayment.getType() : "");
            keyValues.put(EmailTemplateConstants.PAYROLL.STATUS, edsAdditionalPayment.getStatus() != null ? edsAdditionalPayment.getStatus() : "");
            keyValues.put(EmailTemplateConstants.PAYROLL.REFERENCE, edsAdditionalPayment.getReference() != null ? edsAdditionalPayment.getReference() : "");
            keyValues.put(EmailTemplateConstants.PAYROLL.MONTH, edsAdditionalPayment.getMonth() != null ? edsAdditionalPayment.getMonth() : "");
            keyValues.put(EmailTemplateConstants.PAYROLL.YEAR, edsAdditionalPayment.getYear() != null ? edsAdditionalPayment.getYear() : "");
            keyValues.put(EmailTemplateConstants.PAYROLL.PAYMENT_TYPE, edsAdditionalPayment.getPaymentType() != null ? edsAdditionalPayment.getPaymentType() : "");

            String payrollBatch = "";
            if (edsAdditionalPayment.getPayrollBatch() != null) {
                if (isWebhook) {
                    payrollBatch = gson.toJson(new ItemDto(edsAdditionalPayment.getPayrollBatch().getObjectID(), null));
                } else {
                    payrollBatch = edsAdditionalPayment.getPayrollBatch().getName();
                }
            }
            keyValues.put(EmailTemplateConstants.PAYROLL.PAYROLL_BATCH, payrollBatch);

            String employee = "";
//            if (edsAdditionalPayment.getEmployee() != null) {
//                if (isWebhook) {
//                    employee = gson.toJson(new ItemDto(edsAdditionalPayment.getEmployee().getObjectID(), edsAdditionalPayment.getEmployee().getFullName(), edsAdditionalPayment.getEmployee().getProfile().getEmployeeCode()));
//                } else {
//                    employee = edsAdditionalPayment.getEmployee().getFullName();
//                }
//            }
//            keyValues.put(EmailTemplateConstants.PAYROLL.EMPLOYEE, employee);

            String approvers = "";
            if (edsAdditionalPayment.getApprovers() != null) {
                if (isWebhook) {
                    List<ItemDto> approversDto = new ArrayList<>();
                    edsAdditionalPayment.getApprovers().forEach(a -> approversDto.add(new ItemDto(a.getObjectID(), null)));
                    approvers = gson.toJson(approversDto);
                } else {
                    approvers = edsAdditionalPayment.getApprovers().stream().map(a -> a.getExactEmployee() != null ? a.getExactEmployee().getFullName() : "").collect(Collectors.joining(","));
                }
            }
            keyValues.put(EmailTemplateConstants.PAYROLL.APPROVERS, approvers);
            keyValues.put(EmailTemplateConstants.PAYROLL.SHOW_IN_PAYSLIP, edsAdditionalPayment.getShowInPaySlip() != null && edsAdditionalPayment.getShowInPaySlip() ? "true" : "false");

            String paymentType = edsAdditionalPayment.getPaymentType();
            String items = "";
            if (isWebhook && edsAdditionalPayment.getItems() != null && !edsAdditionalPayment.getItems().isEmpty()) {
                List<APaymentItemDto> itemsList = new ArrayList<>();
                for (EdsPaymentDeduction item : edsAdditionalPayment.getItems()) {
                    APaymentItemDto dto = new APaymentItemDto();
                    dto.setEmployee(new ItemDto(item.getEmployee().getObjectID(), item.getEmployee().getFullName(), item.getEmployee().getProfile().getEmployeeCode()));
                    dto.setAmount(item.getPaymentAmount());
                    if (item.getCategory() != null) {
                        dto.setCategory(new ItemDto(item.getCategory().getObjectID(), item.getCategory().getName(), item.getCategory().getCode()));
                    }
                    if (item.getPaymentDate() != null) {
                        dto.setPaymentDate(item.getPaymentDate());
                    }
                    dto.setPercentage(item.getPercentage() != null ? item.getPercentage() : BigDecimal.ZERO);
                    dto.setTotalAmount(paymentType.equals("BASIC_SALARY") ? item.getBasicSalaryAmount() : paymentType.equals("BASIC_SALARY_ALLOWANCE") ? item.getBasicAndadditionalAmount() : BigDecimal.ZERO);
                    itemsList.add(dto);
                }
                items = gson.toJson(itemsList);
            }
            keyValues.put(EmailTemplateConstants.PAYROLL.ITEMS, items);
        }
        return keyValues;
    }

    private Map<String, Object> getGDNFieldValuesMap(final EdsShippingData shippingData, Map<String, Object> keyValues, final EdsUser user) {
        keyValues = keyValues == null ? new HashMap<>() : keyValues;
        if (shippingData != null) {
            String link = "";
            final String host;

            if (user != null) {
                host = EdsContextParams.getHost(user.getCompany().getObjectID());
                link = host + "/Accounting.html?link=" + EncryptionHelper.encryptURL("gdn|summary/" + shippingData.getObjectID()) + "&" + Constants.C_ID + "=" + EncryptionHelper.encryptURL(user.getCompany().getObjectID().toString());
            }

            String number = "", creator = "";
            number = shippingData.getNumber();
            if (shippingData.getCreator() != null) {
                creator = shippingData.getCreator().getFullName();
            }

            keyValues.put(EmailTemplateConstants.ET_NUMBER, number);
            keyValues.put(EmailTemplateConstants.ET_CREATOR, creator);
            keyValues.put(EmailTemplateConstants.ACCOUNTING.CREATED_DATE, ServerUtils.shortDateFormat(ServerUtils.getCompanyDate(shippingData.getCreationTime(), user.getCompany()), user));

            keyValues.put(EmailTemplateConstants.ACCOUNTING.UPDATED_DATE,
                    ServerUtils.shortDateFormat(ServerUtils.getCompanyDate(shippingData.getLastUpdateTime() != null ? shippingData.getLastUpdateTime() : new Date(), user.getCompany()), user));
            keyValues.put(EmailTemplateConstants.ET_LINK, link);
        }
        return keyValues;
    }

    private Map<String, Object> getShippingDataFieldValuesMap(final EdsPickList pickList, Map<String, Object> keyValues, final EdsUser user) {
        keyValues = keyValues == null ? new HashMap<>() : keyValues;
        if (pickList != null) {
            String link = "";
            final String host;

            if (user != null) {
                host = EdsContextParams.getHost(user.getCompany().getObjectID());
                link = host + "/Accounting.html?link=" + EncryptionHelper.encryptURL("picklist|edit/" + pickList.getObjectID()) + "&" + Constants.C_ID + "=" + EncryptionHelper.encryptURL(user.getCompany().getObjectID().toString());
            }

            EdsSaleQuote saleQuote = this.quoteManager.getSaleQuote(pickList.getSaleQuote().getObjectID());
            String number = "", creator = "";
            number = saleQuote.getNumber();
            creator = user.getFullName();

            keyValues.put(EmailTemplateConstants.ET_NUMBER, number);
            keyValues.put(EmailTemplateConstants.ET_CREATOR, creator);

            keyValues.put(EmailTemplateConstants.ACCOUNTING.PICK_DATE, pickList.getPickDate() != null ? pickList.getPickDate() : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.PACK_DATE, pickList.getPackDate() != null ? pickList.getPackDate() : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.SHIP_DATE, pickList.getShipDate() != null ? pickList.getShipDate() : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.EXPECTED_DATE, pickList.getExpectedDate() != null ? pickList.getExpectedDate() : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.GROSS_WEIGHT, pickList.getGrossWeight() != null ? pickList.getGrossWeight() : "");


            keyValues.put(EmailTemplateConstants.ACCOUNTING.CREATED_DATE,
                    ServerUtils.shortDateFormat(ServerUtils.getCompanyDate(pickList.getCreationDate() != null
                                    ? pickList.getCreationDate()
                                    : new Date(),
                            user.getCompany()), user));

            keyValues.put(EmailTemplateConstants.ACCOUNTING.UPDATED_DATE,
                    ServerUtils.shortDateFormat(ServerUtils.getCompanyDate(pickList.getModificationDate() != null
                            ? pickList.getModificationDate()
                            : new Date(), user.getCompany()), user));
            keyValues.put(EmailTemplateConstants.ET_LINK, link);
        }
        return keyValues;
    }

    private Map<String, Object> getTaskFieldValuesMap(final EdsTask edsTask, Map<String, Object> keyValues, final EdsUser user) {
        keyValues = keyValues == null ? new HashMap<>() : keyValues;
        if (edsTask != null) {
            String link = "";
            final String host;
            if (user != null) {
                host = EdsContextParams.getHost(user.getCompany().getObjectID());
                link = host + "/ProjectManagement.html?link=" + EncryptionHelper.encryptURL("task|summary/" + edsTask.getObjectID()) + "&" + Constants.C_ID + "=" + EncryptionHelper.encryptURL(user.getCompany().getObjectID().toString());
            }
            final StringBuilder emails = new StringBuilder();
            final Iterator<EdsEmployeeTask> iter = this.employeeTaskManager.sort(edsTask.getUnDeletedAssignments()).iterator();
            if (iter.hasNext()) {
                final EdsEmployeeTask edsEmployeeTask = iter.next();
                if (StringUtils.isNotEmpty(edsEmployeeTask.getProjectEmployee().getEmployeeDepartment().getEmployee().getEmail())) {
                    emails.append(edsEmployeeTask.getProjectEmployee().getEmployeeDepartment().getEmployee().getEmail());
                }
            }
            while (iter.hasNext()) {
                final EdsEmployeeTask edsEmployeeTask = iter.next();
                if (StringUtils.isNotEmpty(edsEmployeeTask.getProjectEmployee().getEmployeeDepartment().getEmployee().getEmail())) {
                    emails.append(',');
                    emails.append(edsEmployeeTask.getProjectEmployee().getEmployeeDepartment().getEmployee().getEmail());
                }
            }
            String managerName = "";
            String managerEmail = "";
            if (edsTask.getProject() != null && edsTask.getProject().getManager() != null) {
                managerName = edsTask.getProject().getManager().getFullName();
                managerEmail = edsTask.getProject().getManager().getEmail();
            }
            final List<EdsEmployee> edsDirectors = this.employeeManager.getDirectors();
            final StringBuilder directorNames = new StringBuilder();
            final StringBuilder directorEmails = new StringBuilder();
            if (edsDirectors != null) {
                final Iterator<EdsEmployee> iterator = edsDirectors.iterator();
                if (iterator.hasNext()) {
                    final EdsEmployee edsEmployee = iterator.next();
                    if (StringUtils.isNotEmpty(edsEmployee.getEmail())) {
                        directorEmails.append(edsEmployee.getEmail());
                        directorNames.append(edsEmployee.getFullName());
                    }
                }
                while (iterator.hasNext()) {
                    final EdsEmployee edsEmployee = iterator.next();
                    if (StringUtils.isNotEmpty(edsEmployee.getEmail())) {
                        directorEmails.append(',');
                        directorEmails.append(edsEmployee.getEmail());
                        directorNames.append(',');
                        directorNames.append(edsEmployee.getFullName());
                    }
                }
            }
            String clientEmail = "";
            if (edsTask.getProject().getClient() != null &&
                    StringUtils.isNotEmpty(edsTask.getProject().getClient().getEmail())) {
                clientEmail = edsTask.getProject().getClient().getEmail();
            }
            final StringBuilder predecessorString = new StringBuilder();
            for (final EdsTask predecessor : edsTask.getPredecessors()) {
                if (predecessorString.length() > 0) {
                    predecessorString.append(", ");
                }
                predecessorString.append(predecessor.getName());
            }
            final StringBuilder successorString = new StringBuilder();
            for (final EdsTask successor : edsTask.getSuccessors()) {
                if (successorString.length() > 0) {
                    successorString.append(", ");
                }
                successorString.append(successor.getName());
            }
            if (edsTask.getProject() != null) {
                final List<EdsModelField> edsCustomFields = this.modelFieldManager.getCustomFieldsForWorkflowAttributes(LayoutRPC.PROJECT_FORM);
                if (!edsCustomFields.isEmpty()) {
                    final Set<String> fieldIds = Sets.newHashSet();
                    for (final EdsModelField edsCustomField : edsCustomFields) {
                        fieldIds.add(edsCustomField.getField_ID());
                    }
                    keyValues.putAll(edsTask.getProjectCustomFieldValueAsMap(fieldIds));
                }
            }
            setProjectKeysToMap(edsTask.getProject(), keyValues);
            keyValues.put(EmailTemplateConstants.ID, edsTask.getObjectID());
            keyValues.put(EmailTemplateConstants.TASK.WORKSTREAM, edsTask.getParentWS() != null ? edsTask.getParentWS().getName() : "");
            keyValues.put(EmailTemplateConstants.TASK.PREDECESSOR_TASKS, predecessorString.toString());
            keyValues.put(EmailTemplateConstants.TASK.SUCCESSOR_TASKS, successorString.toString());
            keyValues.put(EmailTemplateConstants.TASK.DIRECTORS, directorNames.toString());
            keyValues.put(EmailTemplateConstants.TASK.DIRECTORS_EMAILS, directorEmails.toString());
            keyValues.put(EmailTemplateConstants.TASK.DURATION, edsTask.getDuration());
            keyValues.put(EmailTemplateConstants.TASK.TASK_NUMBER, edsTask.getNumber());
            keyValues.put(
                    EmailTemplateConstants.TASK.TASK_NAME,
                    Optional.ofNullable(edsTask.getName()).orElse("").trim()
            );

            keyValues.put(
                    EmailTemplateConstants.TASK.TASK_DESCRIPTION,
                    Optional.ofNullable(edsTask.getDescription()).orElse("").trim()
            );
            SimpleDateFormat sdf = new SimpleDateFormat("dd.MM.yyyy");
            String date = sdf.format(edsTask.getDueDate());
            keyValues.put(EmailTemplateConstants.TASK.TASK_DUE_DATE, date);
            keyValues.put(EmailTemplateConstants.TASK.PROJECT_CLIENT, edsTask.getProject().getClient() != null ? edsTask.getProject().getClient().getName() : "");
            keyValues.put(EmailTemplateConstants.TASK.PROJECT_NUMBER, edsTask.getProject().getNumber() != null ? edsTask.getProject().getNumber() : "");
            keyValues.put(EmailTemplateConstants.TASK.PROJECT_CLIENT_EMAIL, clientEmail);
            keyValues.put(EmailTemplateConstants.TASK.PROJECT_MANAGER, managerName);
            keyValues.put(EmailTemplateConstants.TASK.PROJECT_MANAGER_EMAIL, managerEmail);
            keyValues.put(EmailTemplateConstants.TASK.ASSIGNEES, this.messageManager.mergeAssignees(edsTask.getUnDeletedAssignments()));
            keyValues.put(EmailTemplateConstants.TASK.ASSIGNEES_EMAILS, emails.toString());
            keyValues.put(EmailTemplateConstants.TASK.COMPLETED, this.getCompletedPercent(edsTask.getPercent() != null ? edsTask.getPercent().intValue() : 0));
            keyValues.put(EmailTemplateConstants.CRM.EVENT.CREATOR_EMAIL, edsTask.getCreator() != null ? edsTask.getCreator().getEmail() : "");
            keyValues.put(EmailTemplateConstants.PENALTIES_PROMOTIONS.PP_CREATOR_NAME, edsTask.getCreator() != null ? edsTask.getCreator().getFirstAndLastname() : "");
            keyValues.put(EmailTemplateConstants.ACCOUNTING.CREATED_DATE, ServerUtils.shortDateFormat(ServerUtils.getCompanyDate(edsTask.getCreationDate() != null ? edsTask.getCreationDate() : new Date(), user.getCompany()), user));
            keyValues.put(EmailTemplateConstants.ACCOUNTING.UPDATED_DATE, ServerUtils.shortDateFormat(ServerUtils.getCompanyDate(edsTask.getModificationDate() != null ? edsTask.getModificationDate() : new Date(), user.getCompany()), user));
            keyValues.put(EmailTemplateConstants.TASK.MODIFIER_NAME, edsTask.getUpdater() != null ? edsTask.getUpdater().getFullName() : "");
            keyValues.put(EmailTemplateConstants.TASK.MODIFIER_EMAIL, edsTask.getUpdater() != null ? edsTask.getUpdater().getEmail() : "");
            keyValues.put(EmailTemplateConstants.ET_LINK, link);
            keyValues.put(EmailTemplateConstants.TASK.DEVICE_TOKEN, user.getDeviceToken() != null ? user.getDeviceToken() : "");
            keyValues.put(EmailTemplateConstants.TASK.PROJECT_ID, edsTask.getProject() != null && edsTask.getProject().getObjectID() != null ? edsTask.getProject().getObjectID() : "");

            EdsFirebaseCredentials firebaseCredential = firebaseCredentialsManager.getFirebaseCredential();
            keyValues.put(EmailTemplateConstants.TASK.FIREBASE_ASSERTION_TOKEN, firebaseCredential != null ? firebaseCredential.getAssertionToken() : "");
            keyValues.put(EmailTemplateConstants.TASK.FIREBASE_OAUTH2_TOKEN, firebaseCredential != null ? firebaseCredential.getOAuth2Token() : "");

            StringBuilder assigneeTelegramChats = new StringBuilder();
            for (EdsEmployeeTask assignee : edsTask.getUnDeletedAssignments()) {
                List<EdsCrmContactItemParams> itemParams = null;
                if (assignee.getProjectEmployee() != null && assignee.getProjectEmployee().getEmployeeDepartment() != null &&
                        assignee.getProjectEmployee().getEmployeeDepartment().getEmployee() != null
                        && assignee.getProjectEmployee().getEmployeeDepartment().getEmployee().getContact() != null) {
                    itemParams = assignee.getProjectEmployee().getEmployeeDepartment().getEmployee().getContact().getItemParams(CONTACT_TELEGRAMS);
                }
                if (itemParams != null && !itemParams.isEmpty()) {
                    for (EdsCrmContactItemParams param : itemParams) {
                        if (assigneeTelegramChats.toString().equals("")) {
                            assigneeTelegramChats = new StringBuilder(param.getRelation() + ":" + param.getValue());
                        } else {
                            assigneeTelegramChats.append(",").append(param.getRelation()).append(":").append(param.getValue());
                        }
                    }
                }
            }
            keyValues.put(EmailTemplateConstants.ET_ASSIGNEE_TELEGRAM, assigneeTelegramChats.toString());

            StringBuilder projectManagerTelegramChats = new StringBuilder();
            List<EdsCrmContactItemParams> managerItemParams = edsTask.getProject().getManager() != null &&
                    edsTask.getProject().getManager().getContact() != null ?
                    edsTask.getProject().getManager().getContact().getItemParams(CONTACT_TELEGRAMS) : null;
            if (managerItemParams != null && !managerItemParams.isEmpty()) {
                for (EdsCrmContactItemParams param : managerItemParams) {
                    if (projectManagerTelegramChats.toString().equals("")) {
                        projectManagerTelegramChats = new StringBuilder(param.getRelation() + ":" + param.getValue());
                    } else {
                        projectManagerTelegramChats.append(",").append(param.getRelation()).append(":").append(param.getValue());
                    }
                }
            }
            keyValues.put(EmailTemplateConstants.ET_PROJECT_MANAGER_TELEGRAM, projectManagerTelegramChats.toString());
        }
        return keyValues;
    }

    private String getCompletedPercent(final Integer percent) {
        return " " + percent + "%";
    }

