    private Map<String, Object> getCaseFieldValuesAsMap(final EdsCase crmCase, Map<String, Object> keyValues, final EdsUser user) {
        keyValues = keyValues == null ? new HashMap<>() : keyValues;
        if (crmCase != null) {
            String crmAccount = "";
            String caseLink = "";
            final String host;
            if (crmCase.getCrmAccount() != null && crmCase.getCrmAccount().getName() != null) {
                crmAccount = crmCase.getCrmAccount().getName();
            } else if (crmCase.getCrmContact() != null && crmCase.getCrmContact().getCrmAccount() != null && crmCase.getCrmContact().getCrmAccount().getName() != null) {
                crmAccount = crmCase.getCrmContact().getCrmAccount().getName();
            } else if (crmCase.getLead() != null && crmCase.getLead().getCrmAccount() != null && crmCase.getLead().getCrmAccount().getName() != null) {
                crmAccount = crmCase.getLead().getCrmAccount().getName();
            }
            if (user != null) {
                host = EdsContextParams.getHost(user.getCompany().getObjectID());
                caseLink = host + "/Crm.html?link=" + EncryptionHelper.encryptURL("case|summary/" + crmCase.getObjectID()) + "&" + Constants.C_ID + "=" + EncryptionHelper.encryptURL(user.getCompany().getObjectID().toString());
            }
            final List<Integer> relationIDs = new ArrayList<>();
            relationIDs.add(crmCase.getObjectID());
            final Map<Integer, String> notes = this.noteHistoryManager.getLastNotesAsMap(EdsNoteHistory.getRelatedToByEntityType(RelationItem.TYPE_CASE), relationIDs);
            final String note = notes.get(crmCase.getObjectID());

            if (user != null && Integer.valueOf(3737).equals(user.getCompany().getObjectID())) {
                final EdsCrmCustomFields edsCrmCustomFields = crmCase.getCustomFields();
                if (edsCrmCustomFields != null) {
                    final EdsCompanyCustomFieldsSettings edsCaseCustomFieldSettings = this.companyCFManager.getCompanyCustomFieldByEntityNameAndFieldName(Constants.CFCRMCASE, "Support Person");
                    if (edsCaseCustomFieldSettings != null && Constants.DATA_TYPE_TEXT.equals(edsCaseCustomFieldSettings.getDataType())) {
                        final String supportPersonValue = edsCrmCustomFields.getStringValue(edsCaseCustomFieldSettings.getColumnCode());
                        if (supportPersonValue != null) {
                            final EdsEmployee edsEmployee = this.employeeManager.getEmployeeByFirstNameViaLastName(supportPersonValue);
                            final String supportPersonEmail = edsEmployee != null && edsEmployee.getEmail() != null ? edsEmployee.getEmail() : "";
                            keyValues.put(EmailTemplateConstants.CRM.CRM_CASE.CASE_SUPPORT_PERSON_EMAIL, supportPersonEmail);
                        }
                    }
                }
            }

            keyValues.put(EmailTemplateConstants.CRM.ASSIGNEE_EMAIL, crmCase.getAssignee() != null && crmCase.getAssignee().getEmail() != null ? crmCase.getAssignee().getEmail() : "");
            keyValues.put(EmailTemplateConstants.CRM.RESOLVER_EMAIL, crmCase.getResolver() != null && crmCase.getResolver().getEmail() != null ? crmCase.getResolver().getEmail() : "");
            String assigneePhone = "";
            if (crmCase.getAssignee() != null) {
                final EdsEmployee assignee = this.employeeManager.get(crmCase.getAssignee().getObjectID());
                assigneePhone = assignee != null && assignee.getPrimaryPhone() != null ? assignee.getPrimaryPhone() : "";
            }
            keyValues.put(EmailTemplateConstants.CRM.CRM_CASE.ASSIGNEE_PHONE, assigneePhone);
            String resolverPhone = "";
            if (crmCase.getResolver() != null) {
                final EdsEmployee resolver = this.employeeManager.get(crmCase.getAssignee().getObjectID());
                resolverPhone = resolver != null && resolver.getPrimaryPhone() != null ? resolver.getPrimaryPhone() : "";
            }
            keyValues.put(EmailTemplateConstants.CRM.CRM_CASE.RESOLVER_PHONE, resolverPhone);
            keyValues.put(EmailTemplateConstants.CRM.CRM_CASE.LEAD_PHONE, crmCase.getLead() != null && crmCase.getLead().getPrimaryPhone() != null ? crmCase.getLead().getPrimaryPhone() : "");
            keyValues.put(EmailTemplateConstants.CRM.CRM_CASE.CONTACT_PHONE, crmCase.getCrmContact() != null && crmCase.getCrmContact().getPrimaryPhone() != null ? crmCase.getCrmContact().getPrimaryPhone() : "");
            keyValues.put(EmailTemplateConstants.CRM.CRM_CASE.CASE_REPORTER, crmCase.getReportedBy() != null ? crmCase.getReportedBy() : "");
            keyValues.put(EmailTemplateConstants.CRM.CRM_CASE.CASE_REPORTER_EMAIL, crmCase.getEmail() != null ? crmCase.getEmail() : "");
            keyValues.put(EmailTemplateConstants.CRM.CRM_CASE.CASE_NUMBER, crmCase.getCaseNumberString() != null ? crmCase.getCaseNumberString() : "");
            keyValues.put(EmailTemplateConstants.CRM.CRM_CASE.CASE_ACCOUNT, crmCase.getDescription());
            keyValues.put(EmailTemplateConstants.CRM.CRM_CASE.CASE_LINK, caseLink);
            keyValues.put(EmailTemplateConstants.CRM.LAST_NOTE, note != null ? note : "");
            keyValues.put(EmailTemplateConstants.CRM.CREATION_DATE, ServerUtils.shortDateFormat(ServerUtils.getCompanyDate(crmCase.getAuditInfo().getCreationDate(), user.getCompany()), user));
            keyValues.put(EmailTemplateConstants.CRM.MODIFIED_DATE, ServerUtils.shortDateFormat(ServerUtils.getCompanyDate(crmCase.getAuditInfo().getModificationDate(), user.getCompany()), user));

            StringBuilder resolverTelegramChats = new StringBuilder();
            List<EdsCrmContactItemParams> resolverItemParams = null;
            if (crmCase.getResolver() != null && crmCase.getResolver().getEmployee() != null && crmCase.getResolver().getEmployee().getContact() != null) {
                resolverItemParams = crmCase.getResolver().getEmployee().getContact().getItemParams(CONTACT_TELEGRAMS);
            }
            if (resolverItemParams != null && !resolverItemParams.isEmpty()) {
                for (EdsCrmContactItemParams param : resolverItemParams) {
                    if (resolverTelegramChats.toString().equals("")) {
                        resolverTelegramChats = new StringBuilder(param.getRelation() + ":" + param.getValue());
                    } else {
                        resolverTelegramChats.append(",").append(param.getRelation()).append(":").append(param.getValue());
                    }
                }
            }
            keyValues.put(EmailTemplateConstants.ET_RESOLVER_TELEGRAM, resolverTelegramChats.toString());
            EdsEmployee employee = crmCase.getAssignee() != null ? crmCase.getAssignee().getEmployee() : null;
            keyValues.put(EmailTemplateConstants.ET_ASSIGNEE_TO_TELEGRAM, crmCase.getAssignee() != null && employee != null && employee.getPrimaryTelegram() != null ? employee.getPrimaryTelegram() : "");
        }
        return keyValues;
    }

