                keyValues.put(EmailTemplateConstants.HRMS.LEAVE_REQUEST.CREATED_DATE, edsEntity.getCreatedDate() != null ? ServerUtils.longDateFormat(ServerUtils.getCompanyDate(edsEntity.getCreatedDate(), user.getCompany()), user) : "");

                keyValues.put(EmailTemplateConstants.HRMS.LEAVE_REQUEST.CREATOR_NAME, edsEntity.getRegisteredBy() != null ? edsEntity.getRegisteredBy().getFullName() : "");
                keyValues.put(EmailTemplateConstants.HRMS.LEAVE_REQUEST.CREATOR_EMAIL, edsEntity.getRegisteredBy() != null ? edsEntity.getRegisteredBy().getEmail() : "");
