                final Map<Integer, Double[]> durationMap = this.sickRequestDurationManager.getLeaveRequestsDurationByIds(String.valueOf(edsEntity.getObjectID()));
                final Double[] dd = durationMap != null ? durationMap.get(edsEntity.getObjectID()) : null;
                final boolean isAllDay = dd != null && dd[1] != null && (dd[1] % 1) == 0 && dd[1] != 0d;
                final String datePeriod = ServerUtils.formatFromTo(edsEntity.getStartDate(), edsEntity.getEndDate(), isAllDay, edsEntity.getEmployee());
