    @Override
    @Transactional
    public ArrayList<RelationItem> saveRelations(final String relationType, final Integer relationID, final String relationName, final ArrayList<RelationItem> relationItems, final boolean indexToSolr) {
        return this.saveRelations(relationType, relationID, relationName, relationItems, indexToSolr, false);
    }

    /**
     * this method deletes all Relations related to relationType+ relationID then adds newOnes(relationItems)...
     *
     * @param relationType
     * @param relationID
     * @param relationName
     * @param relationItems
     * @return
     */
    @Override
    public ArrayList<RelationItem> saveRelations(final String relationType, final Integer relationID, final String relationName, final ArrayList<RelationItem> relationItems, final boolean indexToSolr, final boolean fromConvert) {
        if (relationItems != null && !relationItems.isEmpty()) {
            if (fromConvert) {
                final List<EdsRelation> oldRelations = this.relationManager.getRelationsByRelationFromTypeFromID(relationType, relationID);
                for (final EdsRelation relation : oldRelations) {
                    this.relationManager.delete(relation.getObjectID());
                }
            }

            for (final RelationItem relationItem : relationItems) {
                boolean create = false;
                if (relationItem.getObjectID() == null && !relationItem.isRemove()) {
                    create = true;
                } else {
                    if (relationItem.isRemove()) {
                        this.relationManager.delete(relationItem.getObjectID());
                    } else {
                        final EdsRelation relation = this.relationManager.get(relationItem.getObjectID());
                        if (relation == null) {
                            create = true;
                        } else {   //update it...
                            if (relationItem.isNew()) {
                                relation.setFromID(relationID);
                                relation.setFromName(relationName);
                                relation.setFromType(relationItem.getFromType());
                                relation.setToID(relationItem.getToID());
                                relationItem.setToType(relationItem.getToType());
                                relationItem.setToName(relationItem.getToName());
                            } else {
                                if (relationID != null && (relationItem.getFromID() == null || !relationID.equals(relationItem.getFromID()) || relationItem.getFromType() == null || !relationType.equals(relationItem.getFromType())) && relationItem.getToID() == null && (relationItem.getToType() != null && relationType.equals(relationItem.getToType()))) {
                                    relation.setToID(relationID);
                                    relation.setToType(relationType);
                                    relation.setToName(relationName);
                                    relation.setFromID(relationItem.getFromID());
                                    relation.setFromName(relationItem.getFromName());
                                    relation.setFromType(relationItem.getFromType());
                                }
                            }
                        }
                    }
                }
                if (create) {
                    if (relationItem.isNew()) {
                        relationItem.setFromID(relationID);
                        relationItem.setFromType(relationType);
                        relationItem.setFromName(relationName);
                    } else {
                        if (relationID != null && (relationItem.getFromID() == null || !relationID.equals(relationItem.getFromID()) || relationItem.getFromType() == null || !relationType.equals(relationItem.getFromType())) && relationItem.getToID() == null && (relationItem.getToType() != null && relationType.equals(relationItem.getToType()))) {
                            relationItem.setToID(relationID);
                            relationItem.setToType(relationType);
                            relationItem.setToName(relationName);
                        }
                    }
                    final EdsRelation relation = new EdsRelation(relationItem);
                    this.relationManager.create(relation);
                    if (relation.getEntityID() == null && relationType.contains("_FORM")) { /// custom form un ham tekshirib quyish kere
                        EdsCustomForm customForm = customFormManager.findByFormID(relationType);
                        if (customForm != null) {
                            relation.setEntityID(customForm.getObjectID());
                            relationManager.update(relation);
                        }
                    }
                    relationItem.setObjectID(relation.getObjectID());
                }
            }
            if (indexToSolr) {
                try {
                    if (RelationItem.TYPE_EVENT.equals(relationType)) {
                        eventSolrComponent.index(eventManager.get(relationID));
                    } else if (RelationItem.TYPE_CASE.equals(relationType)) {
                        caseSolrComponent.index(caseManager.get(relationID));
                    } else if (RelationItem.TYPE_OPPORTUNITY.equals(relationType)) {
                        opportunitySolrComponent.index(opportunityManager.get(relationID));
                    } else if (RelationItem.TYPE_PROJECT.equals(relationType)) {
                        projectSolrComponent.index(this.projectManager.get(relationID));
                    } else if (RelationItem.TYPE_TASK.equals(relationType)) {
                        taskSolrComponent.index(taskManager.get(relationID));
                    }
                } catch (final InterruptedException | SolrServerException | IOException e) {
                    e.printStackTrace();
                }
            }
        }
        return relationItems;
    }

