    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public ModelForm getModelForm(final String formID) {
        final EdsModel model = this.modelManager.get(formID);
        final ModelForm rpc = model != null ? model.getRPC(null) : null;
        if (rpc != null) {
            final List<EdsCustomFormSection> sections = this.customFormSectionManager.getSections(formID);
            rpc.setCollapse(sections.stream().filter(EdsCustomFormSection::isActive).count() > 1);

            rpc.setColumnMap(this.getCustomizeForm(formID, sections, model.getViewName()));

            rpc.setSectionsRpcMap(this.getCustomizeFormSections(formID, sections, false));
        }
        return rpc;
    }

