    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public LinkedHashMap<String, DynamicSectionsRpc> getCustomizeFormSections(final String formID, List<EdsCustomFormSection> sections, boolean isFormCustomizeForm) {
        final LinkedHashMap<String, DynamicSectionsRpc> map = new LinkedHashMap<>();
        if (sections == null || sections.isEmpty()) {
            sections = this.customFormSectionManager.getSections(formID);
        }
        EdsUser loggedUser = userManager.getUser();
        EdsUserEmailSettings userSettings = userEmailSettingsManager.getUserSettings(loggedUser);
        sections.forEach(x -> {
                    if (!("PRODUCT".equals(formID) && "PRODUCT_CATEGORY_CUSTOM_FIELDS".equals(x.getSection()))) {
                        if (x.getEdsCustomFormLocalization() != null) {
                            map.put(x.getSection(), x.toRpc(isFormCustomizeForm ? null : userSettings.getInternationalization()));
                        } else {
                            map.put(x.getSection(), x.toRpc(null));
                        }
                    }
                }
        );

        return map;
    }

    @Override
    @Transactional
    public ArrayList<CustomFormLocalization> getCFFLocalizations(final String formID) {
        ArrayList<CustomFormLocalization> listOfLocalization = new ArrayList<>();

        final List<EdsModelField> fields = this.modelFieldManager.getModelFieldsCustom(formID);
        final List<EdsCustomFormSection> sections = this.customFormSectionManager.getSections(formID);

        sections.forEach(
                section -> {
                    if (section.getEdsCustomFormLocalization() != null) {
                        listOfLocalization.add(section.getEdsCustomFormLocalization().getRPC());
                        String sectionName = section.getSection();
                        fields.forEach(
                                edsModelField -> {
                                    if (sectionName.equals(edsModelField.getFsection())) {
                                        if (edsModelField.getCustomFormLocalization() != null) {
                                            listOfLocalization.add(edsModelField.getCustomFormLocalization().getRPC());
                                        } else {
                                            saveToCFLtable(edsModelField, listOfLocalization);
                                        }
                                    }
                                }
                        );
                    } else {
                        EdsCustomFormLocalization item = new EdsCustomFormLocalization();
                        item.setSection(section.getSection());
                        item.setFormId(section.getForm_ID());
                        item.setType(Constants.SECTION);
                        item.setDefaultName(section.getSection());
                        item.setEnglishName(section.getSection());
                        item.setArabicName(section.getSection());
                        item.setRussianName(section.getSection());
                        item.setUzbekName(section.getSection());
                        customFormLocalizationManager.create(item);

                        section.setEdsCustomFormLocalization(item);
                        customFormSectionManager.update(section);

                        listOfLocalization.add(item.getRPC());
                        String sectionName = section.getSection();
                        fields.forEach(
                                edsModelField -> {
                                    if (sectionName.equals(edsModelField.getFsection())) {
                                        if (edsModelField.getCustomFormLocalization() != null) {
                                            listOfLocalization.add(edsModelField.getCustomFormLocalization().getRPC());
                                            if (Constants.UI_TYPE_ITEM_TABLE.equals(edsModelField.getWidget())) {
                                                List<EdsCompanyCustomFieldsSettings> companyCustomFieldsSettings = companyCFSettingsManager.getCompanyCustomFieldsByCategoryForListView(CustomFieldSection.CustomFormItemTable.name(), edsModelField.getField_ID());
                                                companyCustomFieldsSettings.forEach(customfield -> {
                                                    if (customfield.getCustomFormlocalization() != null) {
                                                        listOfLocalization.add(customfield.getCustomFormlocalization().getRPC());
                                                    }
                                                });
                                            }
                                        } else {
                                            saveToCFLtable(edsModelField, listOfLocalization);
                                        }
                                    }
                                }
                        );

                    }
                }
        );

        return listOfLocalization;
    }

    private void saveToCFLtable(EdsModelField edsModelField, List<CustomFormLocalization> listOfLocalization) {
        EdsCustomFormLocalization fieldItem = new EdsCustomFormLocalization();
        fieldItem.setSection(edsModelField.getSection());
        fieldItem.setFormId(edsModelField.getForm_ID());
        fieldItem.setType(Constants.FIELD);
        fieldItem.setDefaultName(edsModelField.getLabel());
        fieldItem.setEnglishName(edsModelField.getLabel());
        fieldItem.setArabicName(edsModelField.getLabel());
        fieldItem.setRussianName(edsModelField.getLabel());
        fieldItem.setUzbekName(edsModelField.getLabel());

        customFormLocalizationManager.create(fieldItem);
        edsModelField.setCustomFormLocalization(fieldItem);
        modelFieldManager.update(edsModelField);
        listOfLocalization.add(edsModelField.getCustomFormLocalization().getRPC());

        if ((edsModelField.getSource() != null && edsModelField.getSource().isEmpty()) &&
                (Constants.UI_TYPE_CHECKBOX.equals(edsModelField.getWidget()) || Constants.UI_TYPE_DROPDOWN.equals(edsModelField.getWidget()) || Constants.UI_TYPE_RADIOBUTTON.equals(edsModelField.getWidget()))) {
            for (String value : edsModelField.getSource().split("-:-")) {
                EdsCustomFormLocalization source = new EdsCustomFormLocalization();
                source.setDefaultName(value);
                source.setEnglishName(value);
                source.setArabicName(value);
                source.setRussianName(value);
                source.setUzbekName(value);
                source.setType(Constants.PREDEFINED);
                source.setSection(edsModelField.getSection());
                source.setFormId(edsModelField.getForm_ID());
                source.setParent(edsModelField.getCustomFormLocalization());
                customFormLocalizationManager.create(source);
                listOfLocalization.add(source.getRPC());
            }
        }
    }

    @Override
    @Transactional
    public void saveCFLItems(LinkedList<CustomFormLocalization> items) {
        items.forEach(item -> {
            EdsCustomFormLocalization localization = customFormLocalizationManager.get(item.getId());
            if (localization != null) {
                localization.setEnglishName(item.getEnglishName());
                localization.setArabicName(item.getArabicName());
                localization.setRussianName(item.getRussianName());
                localization.setUzbekName(item.getUzbekName());
                customFormLocalizationManager.update(localization);
            }
        });
    }

    @Override
    @Transactional
    public void saveSectionOrder(final String formID, final LinkedList<DynamicSectionsRpc> sections) {
        int[] sorder = {0};
        sections.forEach(s -> {
            EdsCustomFormSection section = this.customFormSectionManager.getCustomizeFormSection(formID, s.getName());
            if (section == null) {
                section = new EdsCustomFormSection();
            }
            section.setSorder(sorder[0]);
            section.setActive(s.isActive());
            section.setForm_ID(formID);
            section.setSection(s.getName());
            sorder[0]++;
            this.customFormSectionManager.createOrUpdate(section);
        });
    }

    @Override
    public int saveCustomDynamicFormSection(final DynamicSectionsRpc rpc) {

        final List<EdsCustomFormSection> sectionList = this.customFormSectionManager.getSections(rpc.getFormID());
        if (sectionList.size() > 25) {
            return Constants.LIMIT_EXCEEDED;
        }

        final String name = rpc.getLabel().trim().replaceAll(" +", " ");

        final EdsCustomFormSection edsCustomFormSection = this.customFormSectionManager.getSectionByName(rpc.getFormID(), name);
        if (edsCustomFormSection != null && !edsCustomFormSection.getObjectID().equals(rpc.getId())) {
            return Constants.VALIDATION;
        }

        EdsCustomFormSection section = rpc.getId() != null ? this.customFormSectionManager.get(rpc.getId()) : null;

        if (section == null) {
            section = new EdsCustomFormSection();
        }
        section.setActive(true);
        section.setLabel(name);
        if (rpc.isCustom() || rpc.getId() == null) {
            section.setSection(name);
            section.setCustom(true);
            section.setForm_ID(rpc.getFormID());

            Integer sorder = customFormSectionManager.getSorder(rpc.getFormID());
            section.setSorder(sorder != null ? sorder + 1 : 0);
        }

        String label = rpc.getLabel();
        EdsCustomFormLocalization customFormLocalization = section.getEdsCustomFormLocalization();

        // Update existing localization if user changes is directly from costomize form
        if (customFormLocalization != null) {
            customFormLocalization.setDefaultName(label);
            customFormLocalization.setEnglishName(label);
            customFormLocalization.setArabicName(label);
            customFormLocalization.setRussianName(label);
            customFormLocalization.setUzbekName(label);
        }
        // Create new localization
        else {
            customFormLocalization = new EdsCustomFormLocalization();
            customFormLocalization.setDefaultName(label);

            if (rpc.getId() == null) {
                customFormLocalization.setEnglishName(label);
                customFormLocalization.setArabicName(label);
                customFormLocalization.setRussianName(label);
                customFormLocalization.setUzbekName(label);
            }

            customFormLocalization.setFormId(rpc.getFormID());
            customFormLocalization.setSection(section.getSection());
            customFormLocalization.setType(Constants.SECTION);
        }

        section.setPagination(rpc.isPagination());
        customFormLocalizationManager.createOrUpdate(customFormLocalization);
        section.setEdsCustomFormLocalization(customFormLocalization);

        customFormSectionManager.createOrUpdate(section);

        return Constants.SUCCESS;

    }

