    @Override
    public Integer deletCustomSection(final Integer id) {
        final EdsCustomFormSection section = this.customFormSectionManager.get(id);
        if (section != null) {
            final Integer count = this.modelFieldManager.getSectionFields(section.getForm_ID(), section.getSection());
            if (count != null && count > 0) {
                return Constants.ERROR;
            }
            this.customFormSectionManager.delete(section);
        }
        return Constants.SUCCESS;
    }

