    private LinkedHashMap<String, HashMap<ColumnType, LinkedList<CustomizeFormItem>>> getCustomizeForm(final String formID, List<EdsCustomFormSection> sections, final String viewName) {

        final LinkedHashMap<String, HashMap<ColumnType, LinkedList<CustomizeFormItem>>> map = new LinkedHashMap<>();

        // fields with custom sections created in old UI or recently created custom fields in OLD UI without fieldSection
        final LinkedList<CustomizeFormItem> oldUIFields = new LinkedList<>();
        final List<String> inactiveSections = new ArrayList<>();
        String[] lastSection = new String[1];

        final List<EdsModelField> fields = this.modelFieldManager.getModelFields(formID);
        if (sections == null) {
            sections = this.customFormSectionManager.getSections(formID);
        }

        if (CollectionUtils.isEmpty(sections)) {
            return null;
        }

        if (fields.size() == 0) {
            final HashMap<ColumnType, LinkedList<CustomizeFormItem>> columnMap = new HashMap<>();
            final LinkedList<CustomizeFormItem> list = new LinkedList<>();
            final CustomizeFormItem formItem = new CustomizeFormItem(false, viewName);
            formItem.setCustomForm(true);
            list.add(formItem);
            columnMap.put(ColumnType.COL_1, list);
            map.putIfAbsent(sections.get(0).getSection(), columnMap);
        }

        sections.forEach(
                o -> {
                    if (o.isActive()) {
                        map.putIfAbsent(o.getSection(), new LinkedHashMap<>());
                        lastSection[0] = o.getSection();
                    } else {
                        inactiveSections.add(o.getSection());
                    }
                }
        );

        EdsUser loggedUser = userManager.getUser();
        EdsUserEmailSettings userSettings = userEmailSettingsManager.getUserSettings(loggedUser);

        final ArrayList<SelectItem> allRoles = new ArrayList<>();
        final List<EdsRole> roles = this.roleManager.list();
        for (final EdsRole role : roles) {
            allRoles.add(new SelectItem(role.getObjectID(), this.commonLocalizer.localize(role.getCode(), role.getName())));
        }

        final EdsFormProperty formProperty = this.formPropertyManager.getByFormID(formID);
        final Gson gson = new Gson();
        final FormProperty[] formFields = Optional.ofNullable(formProperty)
                .filter(Objects::nonNull)
                .map(EdsFormProperty::getSettingsJSONData)
                .map(f -> gson.fromJson(f, FormProperty[].class))
                .orElse(new FormProperty[0]);

        fields.forEach(
                edsModelField -> {
                    if (edsModelField != null) {

                        CustomizeFormItem formItem = edsModelField.toRpc(viewName, userSettings.getInternationalization());
                        formItem.setFormID(formID);

                        if (formItem.isCustomField() && formItem.getUiType().equals(UI_TYPE_LOOKUP) && formItem.getDefaultValue() != null && formItem.getDefaultValue().equals("0#_#Current Value")) {
                            EdsCompanyCustomFieldsSettings cfSettings = companyCFManager.getCompanyCustomField(viewName, formItem.getName());
                            if (cfSettings != null && cfSettings.getLookUpType() != null && (cfSettings.getLookUpType().equals(CustomFieldLookUpTypeEnum.LOCATION) || cfSettings.getLookUpType().equals(CustomFieldLookUpTypeEnum.EMPLOYEE) ||
                                    cfSettings.getLookUpType().equals(CustomFieldLookUpTypeEnum.POSITION) || cfSettings.getLookUpType().equals(CustomFieldLookUpTypeEnum.DEPARTMENT))) {
                                String actualValue = null;
                                switch (cfSettings.getLookUpType()) {
                                    case LOCATION -> {
                                        if (loggedUser.getLocation() != null) {
                                            actualValue = loggedUser.getLocation().getObjectID() + DELIMITR + loggedUser.getLocation().getName();
                                        }
                                    }
                                    case EMPLOYEE -> {
                                        if (loggedUser != null) {
                                            actualValue = loggedUser.getObjectID() + DELIMITR + loggedUser.getFullName();
                                        }
                                    }
                                    case POSITION -> {
                                        if (loggedUser.getEmployee().getPosition() != null) {
                                            actualValue = loggedUser.getEmployee().getPosition().getObjectID() + DELIMITR + loggedUser.getEmployee().getPosition().getName();
                                        }
                                    }
                                    case DEPARTMENT -> {
                                        if (loggedUser.getEmployee().getEmployeeDepartment() != null && loggedUser.getEmployee().getEmployeeDepartment().getTeam() != null) {
                                            actualValue = loggedUser.getEmployee().getEmployeeDepartment().getTeam().getObjectID() + DELIMITR + loggedUser.getEmployee().getEmployeeDepartment().getTeam().getName();
                                        }
                                    }
                                }
                                formItem.setDefaultValue(actualValue);
                            }
                        }


                        if (formFields != null) {
                            for (final FormProperty field : formFields) {
                                if (field != null) {
                                    if (edsModelField.getField_ID().equals(field.getCode())) {
                                        formItem.setFormProperty(field);
                                    }
                                    if (CollectionUtils.isNotEmpty(field.getRoleEdit())) {
                                        if (loggedUser.hasEitherRoles(field.getRoleEdit().toArray(new Integer[]{}))) {
                                            field.setDisabled(false);
                                        }
                                    }
                                }
                            }
                        }
                        FormProperty field = Optional.ofNullable(formItem.getFormProperty()).orElse(new FormProperty());
                        field.setAllRoles(allRoles);
                        field.setLang(ServerUtils.getUserLocale().getLanguage());
                        if (map.containsKey(edsModelField.getFsection())) {
                            map.get(edsModelField.getFsection())
                                    .computeIfAbsent(edsModelField.getColumnType(), v -> new LinkedList<>())
                                    .add(formItem);
                        } else if (!inactiveSections.contains(edsModelField.getFsection()) || StringUtils.isBlank(edsModelField.getFsection())) {
                            formItem = edsModelField.toRpc(viewName, null);
                            formItem.setSection(lastSection[0]);
                            oldUIFields.add(formItem);
                        }
                        String messageCode = getMessageCode(edsModelField.getForm_ID(), edsModelField.getField_ID());
                        field.setTitleEn(commonLocalizer.localize(messageCode, edsModelField.getField_ID(), Locale.ENGLISH));
                        field.setTitleRu(commonLocalizer.localize(messageCode, edsModelField.getField_ID(), new Locale("RU")));
                        field.setTitleAr(commonLocalizer.localize(messageCode, edsModelField.getField_ID(), new Locale("AR")));
                        field.setTitleUz(commonLocalizer.localize(messageCode, edsModelField.getField_ID(), new Locale("UZ")));
                        formItem.setFormProperty(field);
                    }
                }
        );


        if (oldUIFields.size() > 0 && StringUtils.isNotEmpty(lastSection[0])) {
            map.get(lastSection[0])
                    .computeIfAbsent(ColumnType.COL_1, x -> new LinkedList<>()) //COL_1 - default column
                    .addAll(oldUIFields);
        }

        return map;
    }

    private static String getMessageCode(String formId, String fieldCode) {
        if (SALEINVOICE_FORM.equals(formId)) {
            return switch (fieldCode) {
                case CustomFormConstants.NUMBER -> "invoiceNumber";
                case CustomFormConstants.START_DATE -> "invoiceDate";
                case CustomFormConstants.ACCOUNTING.TOTAL_DISCOUNT -> "overalDiscount";
                default -> StringUtil.snakeToCamelCase(fieldCode);
            };
        }
        if (PROJECT_FORM.equals(formId)) {
            return switch (fieldCode) {
                case CustomFormConstants.PROJECT.CLIENT -> "customers";
                case CustomFormConstants.PROJECT.INVOLVED_EMPLOYEE -> "members";
                case CustomFormConstants.PROJECT.COMPLETED -> "percent";
                case CustomFormConstants.PROJECT.BACKUP_MANAGER -> "backupManagers";
                case CustomFormConstants.PROJECT.TIME_SPENT -> "timeSpentOnly";
                case CustomFormConstants.PROJECT.WAITING_HOURS -> "waitingForApproval";
                case CustomFormConstants.PROJECT.ESTIMATED_COST -> "costEstimated";
                case CustomFormConstants.PROJECT.WAITING_FOR_SOMEONE_ELSE -> "waitingForSomeone";
                case CustomFormConstants.PROJECT.PROJECT_NOTE -> "notes";
                case CustomFormConstants.PROJECT.PROJECT_INVOICES -> "invoices";
                case CustomFormConstants.PROJECT.PROJECT_CHART -> "chartOnly";
                default -> StringUtil.snakeToCamelCase(fieldCode);
            };
        }
        return switch (fieldCode) {
            case CustomFormConstants.CRM_OPPORTUNITY_NUMBER -> "number";
            case CustomFormConstants.CRM_OPPORTUNITY_ASSIGNEE -> "assignee";
            case CustomFormConstants.CRM_OPPORTUNITY_BACKUP_ASSIGNEE -> "backupAssignee";
            case CustomFormConstants.TAX_CALC_TYPE, CRM_OPPORTUNITY_AMOUNT -> "amount";
            case CustomFormConstants.CRM_OPPORTUNITY_NAME -> "name";
            case CustomFormConstants.CRM_OPPORTUNITY_ACCOUNT_NAME -> "customer";
            case CustomFormConstants.CRM_OPPORTUNITY_CONTACT_NAME -> "contact";
            case CustomFormConstants.CRM_OPPORTUNITY_LEAD_SOURCE, CustomFormConstants.LEAD_SOURCE -> "source";
            case CustomFormConstants.CRM_OPPORTUNITY_CAMPAIGN_SOURCE, CustomFormConstants.CRM_CAMPAIGN_NAME ->
                    "campaign";
            case CustomFormConstants.CRM_OPPORTUNITY_TYPE -> "type";
            case CustomFormConstants.CRM_OPPORTUNITY_NEXT_STEP -> "nextStep";
            case CustomFormConstants.CRM_OPPORTUNITY_CLOSING_DATE -> "closeDate";
            case CustomFormConstants.CRM_OPPORTUNITY_STAGE -> "stage";
            case CustomFormConstants.CRM_OPPORTUNITY_PROBABILITY -> "probability";
            case CustomFormConstants.CRM_OPPORTUNITY_EXPECTED_REVENUE -> "expectedRevenue";
            case CustomFormConstants.PROJECT_FIELD -> "project";
            case CustomFormConstants.CRM_NOTE -> "notes";
            case CustomFormConstants.CRM_OPPORTUNITY_CONTACT_PRIMARY_PHONE -> "phone";
            case CustomFormConstants.CRM_OPPORTUNITY_ATTACHMENTS -> "attachments";
            case CustomFormConstants.CRM_OPPORTUNITY_LINKS -> "links";
            case CustomFormConstants.PROJECT.INVOLVED_EMPLOYEE -> "members";
            case CustomFormConstants.CRM_ACCOUNT_NAME -> "company";
            case CustomFormConstants.CRM_OPPORTUNITY_CONTACT_PRIMARY_EMAIL -> "email";
            case CustomFormConstants.TAKE_LIVE_TYPE -> "takeLeaveBy";
            case CustomFormConstants.CUSTOM_HTML_TEMPLATE -> "template";
            case CustomFormConstants.SHARED_WITH -> "share";
            case CustomFormConstants.ENABLE_REMINDER -> "reminders";
            case "SALES_PRICE" -> "sellingPrice";
            case CustomFormConstants.USEFUL_LIFE -> "useFulLife";
            case CustomFormConstants.FIXED_ASSET_ACCOUNT -> "accumulatedDepreciationAccount";
            case CustomFormConstants.EXPENSE_ACCOUNT -> "depreciationExpenseAccount";
            default -> StringUtil.snakeToCamelCase(fieldCode);
        };
    }

