    private void createFieldForCustomForms(final String form_ID) {
        EdsModelField approvers = this.modelFieldManager.getByFieldID(form_ID, CustomFormConstants.APPROVERS);
        if (approvers == null) {
            approvers = new EdsModelFieldCustom();
        }
        approvers.setForm_ID(form_ID);
        approvers.setLabel("Approvers");
        approvers.setFsection(CustomFormConstants.GENERAL_INFORMATION);
        approvers.setField_ID(CustomFormConstants.APPROVERS);
        approvers.setSystemMandatory(true);
        approvers.setWidget(Constants.UI_TYPE_DROPDOWN);
        approvers.setCustomField(false);
        approvers.setUsableByWorkflow(true);
        this.modelFieldManager.createOrUpdate(approvers);
    }

    @Transactional
    public void approvedOrRejected(final String entityType, final Integer entityID, final EdsBusinessEvent eventType) {
        if (entityType == null || entityID == null) {
            return;
        }
        Integer companyID = null;
        if (ServerSecurityContext.getInstance().getCompanyId() != null) {
            companyID = Integer.valueOf(ServerSecurityContext.getInstance().getCompanyId());
        }

        EdsApprovable approvable = switch (entityType) {
            case RelationItem.TYPE_LEAVE_REQUEST -> this.sickRequestManager.get(entityID);
            case RelationItem.TYPE_EMPLOYEE_STEP -> this.stepEmployeeManager.get(entityID);
            case RelationItem.TYPE_CASH_ADVANCE -> this.cashAdvanceManager.get(entityID);
            case TYPE_EXPENSE_CLAIM -> this.expenseReportManager.get(entityID);
            case RelationItem.TYPE_ADDITIONAL_PAYMENT -> this.additionalPaymentManager.get(entityID);
            case RelationItem.TYPE_SALEQUOTE, RelationItem.TYPE_SALEORDER, RelationItem.TYPE_PURCHASE_ORDER ->
                    this.quoteManager.get(entityID);
            case RelationItem.TYPE_STOCK_TRANSFER -> this.stockTransferManager.get(entityID);
            case RelationItem.TYPE_STOCK_ADJUSTMENT -> this.stockAdjustmentManager.get(entityID);
            case RelationItem.TYPE_PLACEMENT -> this.placementManager.get(entityID);
            case RelationItem.TYPE_CERTIFICATE_OF_EMPLOYMENT -> this.certificateOfEmploymentManager.get(entityID);
            case RelationItem.REQUEST_FOR_PURCHASE -> this.rfpManager.get(entityID);
            case RelationItem.TYPE_MANUAL_JOURNAL -> this.manualJournalManager.get(entityID);
            case TYPE_REQUEST_FOR_QUOTE -> this.rfqManager.get(entityID);
            case RelationItem.TYPE_CUSTOM_FORM_ITEM -> this.customFormItemManager.get(entityID);
            case RelationItem.TYPE_SALEINVOICE, TYPE_CREDIT_NOTE -> this.invoiceManager.get(entityID);
            case RelationItem.TYPE_PURCHASE_INVOICE, TYPE_DEBIT_NOTE ->
                    this.invoiceManager.getPurchaseInvoice(entityID);
            case RelationItem.TYPE_GROUP_GOAL -> this.groupGoalManager.get(entityID);
            case TYPE_BACKUPS_EMPLOYEE -> this.backupsEmployeeManager.get(entityID);
            case RelationItem.TYPE_VACANCY -> this.vacancyManager.get(entityID);
            case RelationItem.TYPE_SHIFT -> this.shiftManager.get(entityID);
            case RelationItem.TYPE_ROTATION -> this.rotationManager.get(entityID);
            case RelationItem.TYPE_GROUP_PLACEMENT -> this.groupPlacementManager.get(entityID);
            case RelationItem.TYPE_RECURRING_PAY_DEDUCTION -> recurringPayDeductionManager.get(entityID);
            case RelationItem.TYPE_OVERTIME -> overtimeManager.get(entityID);
            case RelationItem.TYPE_OPPORTUNITY -> opportunityManager.get(entityID);
            case RelationItem.TYPE_RENTAL_ORDER -> rentalOrderManager.get(entityID);
            case TYPE_BUILD_ASSEMBLY -> savedAssemblyItemManager.get(entityID);
            default -> null;
        };
        log.info("||||||||||||||||||||||| APPROVABLE IS OK " + isOk(approvable) + " |||||||||||||||||||||||");
        log.info("||||||||||||||||||||||| CURRENT APPROVER IS OK " + isOk(approvable.getCurrentApprover()) + " |||||||||||||||||||||||");
        if (isOk(approvable) && isOk(approvable.getCurrentApprover())) {
            // run workflows
            if ((approvable.isCurrentApproverRejected() && isOk(approvable.getCurrentApprover().getOnRejectedWorkflow()))
                    || (approvable.isCurrentApproverApproved() && isOk(approvable.getCurrentApprover().getOnApprovedWorkflow()))) {
                this.runActions(approvable.isCurrentApproverApproved() ? approvable.getCurrentApprover().getOnApprovedWorkflow() : approvable.getCurrentApprover().getOnRejectedWorkflow(), entityType, approvable, false, true);
            }
            log.info("||||||||||||||||||||||| IS APPROVED " + approvable.isCurrentApproverApproved() + " |||||||||||||||||||||||");
            log.info("||||||||||||||||||||||| APPROVED ACTION NUMBER IS " + approvable.getCurrentApprover().getOnApprovedAction() + " |||||||||||||||||||||||");
            if (ApproverItem.MARK_AS_APPROVED.equals(approvable.getCurrentApprover().getOnApprovedAction()) && approvable.isCurrentApproverApproved()) {
                log.info("||||||||||||||||||||||| " + entityType + " IS APPROVED " + "|||||||||||||||||||||||");
                approvable.updateOverAllStatusIfMarked();
                if (RelationItem.TYPE_SALEQUOTE.equals(entityType) ||
                        RelationItem.TYPE_SALEORDER.equals(entityType) ||
                        RelationItem.TYPE_PURCHASE_ORDER.equals(entityType) ||
                        RelationItem.TYPE_PURCHASE_INVOICE.equals(entityType) ||
                        RelationItem.TYPE_DEBIT_NOTE.equals(entityType) ||
                        RelationItem.TYPE_SALEINVOICE.equals(entityType) ||
                        RelationItem.TYPE_CREDIT_NOTE.equals(entityType) ||
                        RelationItem.TYPE_LEAVE_REQUEST.equals(entityType)) {

                    Object[] result = getBaseInvoiceAndFolder(entityType, entityID);
                    EdsBaseInvoice edsBaseInvoice = (EdsBaseInvoice) result[0];
                    ByteArrayOutputStream baos = (ByteArrayOutputStream) result[1];
                    FolderResource folderResource = (FolderResource) result[2];
                    EdsSickRequest edsSickRequest = (EdsSickRequest) result[3];

                    createAndUploadPDF(edsBaseInvoice, baos, folderResource, approvable, edsSickRequest);
                }
            } else if (ApproverItem.MARK_AS_REJECTED.equals(approvable.getCurrentApprover().getOnRejectedAction()) && approvable.isCurrentApproverRejected()) {
                approvable.jumpToFirstApprover();
                approvable.updateOverAllStatusIfMarked();
            } else if (WorkflowExecutionCriteriaEnum._WORKFLOW_ACTION_EDIT.name().equals(eventType != null && eventType.getEventType() != null ? eventType.getEventType() : "")) {
                approvable.jumpToFirstApprover();
            } else if (approvable.isCurrentApproverApproved()) {
                approvable.jumpToNextApprover();
                approvable.updateRejectedStatus();
            } else if (approvable.isCurrentApproverRejected()) {
                if (isOk(approvable.getCurrentApprover().getOnRejectedAction()) && ApproverItem.SEND_TO_PREV_APPROVER.equals(approvable.getCurrentApprover().getOnRejectedAction())) {
                    approvable.jumpToPreviousApprover();
                    switch (entityType) {
                        case RelationItem.TYPE_CASH_ADVANCE ->
                                approvable.setEntityStatus(this.referenceManager.getByCode(Constants.SUBMITTED_TO_MANAGER));
                        case TYPE_EXPENSE_CLAIM ->
                                approvable.setEntityStatus(this.referenceManager.findReference(Constants.EXPENSE_STATUS, Constants.EXPENSE_SUBMITTED));
                        case RelationItem.TYPE_ADDITIONAL_PAYMENT ->
                                approvable.setEntityStatus(this.referenceManager.findReference(Constants.PAYMENT_STATUS, Constants.PAYMENT_STATUS_SUBMITTED));
                        case RelationItem.TYPE_SALEQUOTE, RelationItem.TYPE_SALEORDER, RelationItem.TYPE_SALEINVOICE,
                             TYPE_CREDIT_NOTE, RelationItem.TYPE_PURCHASE_INVOICE, RelationItem.TYPE_DEBIT_NOTE,
                             RelationItem.TYPE_PURCHASE_ORDER, RelationItem.REQUEST_FOR_PURCHASE ->
                                approvable.setEntityStatus(this.referenceManager.findReference(Constants.INVOICE_STATUS, Constants.SUBMITTED_TO_MANAGER));
                        case RelationItem.TYPE_CERTIFICATE_OF_EMPLOYMENT ->
                                approvable.setEntityStatus(this.referenceManager.findReference(Constants.CERTIFICATE_OF_EMPLOYMENT_STATUS, Constants.CERTIFICATE_OF_EMPLOYMENT_STATUS_SUBMITTED));
                        case RelationItem.TYPE_MANUAL_JOURNAL ->
                                approvable.setEntityStatus(this.referenceManager.findReference(Constants.MANUAL_JOURNAL_STATUS, EdsManualJournal.SUBMITTED));
                        case TYPE_REQUEST_FOR_QUOTE ->
                                approvable.setEntityStatus(this.referenceManager.findReference(Constants.RFQ_STATUS, Constants.RFQ_SUBMITTED));
                        case RelationItem.TYPE_CUSTOM_FORM_ITEM ->
                                approvable.setEntityStatus(this.referenceManager.findReference(Constants.CUSTOM_FORM_ITEM_STATUS, Constants.CUSTOM_FORM_ITEM_STATUS_SUBMITTED));
                        case RelationItem.TYPE_GROUP_GOAL ->
                                approvable.setEntityStatus(this.referenceManager.findReference(EdsTask.TASK_STATUS, EdsTask.NOT_STARTED));
                        case TYPE_STOCK_TRANSFER ->
                                approvable.setEntityStatus(this.referenceManager.findReference(Constants.STOCK_TRANSFER_STATUS, Constants.STOCK_TRANSFER_SUBMITTED));
                        case TYPE_STOCK_ADJUSTMENT ->
                                approvable.setEntityStatus(this.referenceManager.findReference(Constants.STOCK_ADJUSTMENT_STATUS, Constants.STOCK_ADJUSTMENT_SUBMITTED));
                        case RelationItem.TYPE_PLACEMENT ->
                                approvable.setEntityStatus(this.referenceManager.findReference(Constants.PLACEMENT_STATUS, Constants.PLACEMENT_STATUS_SUBMITTED));
                        case RelationItem.TYPE_VACANCY ->
                                approvable.setEntityStatus(this.referenceManager.findReference(Constants.VACANCY_APPROVAL_STATUS, Constants.VACANCY_APPROVAL_STATUS_SUBMITTED));
                        case RelationItem.TYPE_SHIFT ->
                                approvable.setEntityStatus(this.referenceManager.findReference(Constants.SHIFT_STATUS, Constants.SHIFT_SUBMITTED));
                        case RelationItem.TYPE_ROTATION ->
                                approvable.setEntityStatus(this.referenceManager.findReference(Constants.ROTATION_STATUS, Constants.ROTATION_SUBMITTED));
                        case TYPE_BACKUPS_EMPLOYEE ->
                                approvable.setEntityStatus(this.referenceManager.findReference(Constants.BACKUPS_EMPLOYEE_STATUS, Constants.BACKUPS_EMPLOYEE_SUBMITTED));
                        case TYPE_OPPORTUNITY ->
                                approvable.setEntityStatus(this.referenceManager.findReference(Constants.OPPORTUNITY_STATUS, Constants.OPPORTUNITY_SUBMITTED));
                        case RelationItem.TYPE_GROUP_PLACEMENT ->
                                approvable.setEntityStatus(this.referenceManager.findReference(Constants.GROUP_PLACEMENT_STATUS, Constants.GROUP_PLACEMENT_SUBMITTED));
                        case TYPE_BUILD_ASSEMBLY ->
                                approvable.setEntityStatus(this.referenceManager.findReference(Constants.BUILD_ASSEMBLY_STATUS, Constants.BUILD_ASSEMBLY_STATUS_SUBMITTED));
                    }
                } else if (ApproverItem.SEND_TO_CREATOR.equals(approvable.getCurrentApprover().getOnRejectedAction()) || ApproverItem.SEND_TO_DIRECTORS.equals(approvable.getCurrentApprover().getOnRejectedAction())) {
                    approvable.updateOverAllStatusIfMarked();
                }
            }
            switch (entityType) {
                case RelationItem.TYPE_LEAVE_REQUEST:
                    EdsSickRequest leaveRequest = (EdsSickRequest) approvable;
                    if (isOk(approvable.getOverallStatus()) && (EdsSickRequest.APPROVED.equals(approvable.getOverallStatus().getCode()) || EdsSickRequest.DENIED.equals(approvable.getOverallStatus().getCode()))) {
                        this.baseEventPostProcessor.registerEvent(LeaveRequestEventListenerImpl.TYPE, EdsSickRequest.APPROVED.equals(approvable.getOverallStatus().getCode()) ? LeaveRequestEventListenerImpl.LEAVE_REQUEST_APPROVED : LeaveRequestEventListenerImpl.LEAVE_REQUEST_DENIED, (EdsSickRequest) approvable, this.userManager.getUser());
                        if (leaveRequest.getRecallDate() != null && EdsSickRequest.APPROVED.equals(leaveRequest.getOverallStatus().getCode())) {
                            payrollServiceLocal.createCashAdvanceByLeaveRequest(leaveRequest.getObjectID());
                        }
                    }
                    if (isOk(approvable.getOverallStatus()) && (EdsSickRequest.APPROVED.equals(approvable.getOverallStatus().getCode()))) {
                        payrollServiceLocal.createAdditionalPaymentForLeaveRequestBackups(leaveRequest.getObjectID());
                        payrollServiceLocal.createAdditionalPaymentByLeaveRequest(leaveRequest.getObjectID());
                        if ("СОЦИАЛЬНЫЙ_ОТПУСК_-_ПО_УХОДУ_ЗА_РЕБЕНКОМ".equals(leaveRequest.getLeaveReason().getCode()) || "ОТПУСК_ПО_УХОДУ_ЗА_РЕБЕНКОМ_(ДО_3_ЛЕТ)".equals(leaveRequest.getLeaveReason().getCode())) {
                            availabilityService.updateOrRemoveLabourPeriod(leaveRequest.getObjectID());
                        }
                    }
                    if (leaveRequest.getLeaveReason() != null && "Б/С".equalsIgnoreCase(leaveRequest.getLeaveReason().getCode())) {
                        calculateAdditionalLogicForBCLeaveReason(leaveRequest);
                    }
                    break;
                case RelationItem.TYPE_EMPLOYEE_STEP:
                    final EdsStepEmployee employeeStep = (EdsStepEmployee) approvable;
                    try {
                        employeeStepSolrComponent.index(employeeStep);
                    } catch (final IOException | SolrServerException | InterruptedException e) {
                        e.printStackTrace();
                    }
                    final EdsBusinessEvent workflowEvent = this.baseEventPostProcessor.registerEvent(WorkflowActionDetectedEventListenerImpl.TYPE, eventType != null && eventType.getCustomStringField() != null ? eventType.getCustomStringField() : BaseEventsPostProcessorImpl.EVENT_TYPE_EDIT, employeeStep, this.userManager.getUser());
                    workflowEvent.setEntityType(employeeStep.getOnboardingStep().getFormID());
                    break;
                case RelationItem.TYPE_CASH_ADVANCE:
                    if (approvable.getOverallStatus().getCode().equals(EdsCashAdvance.APPROVED)) {
                        this.payrollService.approvedActionForCashAdvance(approvable.getObjectID(), false);
                    }
                    try {
                        cashAdvanceSolrComponent.index((EdsCashAdvance) approvable);
                        final WebSocketServerObject message = new WebSocketServerObject();
                        message.setEventType(WfmUiEventType.ON_CASH_SAVED);
                        final Integer userId = ((EdsUser) ServerSecurityContext.getInstance().getUser()).getObjectID();
                        message.setUserId(userId);
                        this.rabbitMQService.sendWebPushNotification(message);
                    } catch (final SolrServerException | IOException | InterruptedException e) {
                        e.printStackTrace();
                    }
                    break;
                case RelationItem.TYPE_ADDITIONAL_PAYMENT:
                    try {
                        if (isOk(approvable.getOverallStatus()) && PAYMENT_STATUS_APPROVED.equals(approvable.getOverallStatus().getCode())) {
                            EdsAdditionalPayment payment = (EdsAdditionalPayment) approvable;
                            payment.setApprovedDate(new Date());
                            if (!payment.getShowInPaySlip()) {
                                payrollServiceLocal.additionalPaymentTransaction(payment);
                            }
                        }

//                        this.solrManager.addAdditionalPaymentToIndex((EdsAdditionalPayment) approvable);
                        additionalPaymentSolrComponent.index((EdsAdditionalPayment) approvable);
                    } catch (final InterruptedException e) {
                        e.printStackTrace();
                    }
                    break;
                case TYPE_EXPENSE_CLAIM:
                    if (EdsExpenseReport.EXPENSE_APPROVED.equals(approvable.getOverallStatus().getCode())) {
                        this.accountingServiceLocal.createOrUpdateTransactionForExpense((EdsExpenseReport) approvable);
                    } else if (EdsExpenseReport.EXPENSE_DECLINED.equals(approvable.getOverallStatus().getCode())) {
                        transactionManager.deleteExpenseReportTransaction((EdsExpenseReport) approvable);
                    }
                    try {
//                        this.solrManager.addExpenseReportToIndex((EdsExpenseReport) approvable);
                        expenseReportClaimsSolrComponent.index((EdsExpenseReport) approvable);
                    } catch (InterruptedException e) {
                        e.printStackTrace();
                    }
                    break;
                case RelationItem.TYPE_SALEQUOTE:
                case RelationItem.TYPE_SALEORDER:
                    final EdsSaleQuote edsSaleQuote = (EdsSaleQuote) approvable;
                    if (!edsSaleQuote.isSalesOrder()) {
                        if (EdsSaleQuote.APPROVE.equals(edsSaleQuote.getOverallStatus().getCode())) {
                            //this piece of the code need to calculate project budget
                            if (edsSaleQuote.getRelatedProject() != null || this.genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.PROJECT_IN_LINE_ITEM_ENABLE)) {
                                final EdsBusinessEvent event = this.baseEventPostProcessor.registerEvent(ProjectBudgetCustomEventListenerImpl.TYPE, ProjectBudgetCustomEventListenerImpl.SALE_QUOTE_APPROVE, edsSaleQuote, null);
                                event.setCustomStringField(edsSaleQuote.getRelatedProject() != null && edsSaleQuote.getRelatedProject().getObjectID() != null ? edsSaleQuote.getRelatedProject().getObjectID().toString() : null);
                            }

                            if (this.genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.CREDIT_LIMIT_FOR_QUOTE_ENABLED)) {
                                this.quoteManager.calculateCustomerQuoteBalance(edsSaleQuote.getClient().getObjectID());
                            }
                        } else if (EdsSaleQuote.MANAGER_REJECT.equals(edsSaleQuote.getOverallStatus().getCode())) {
                            if (this.genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.CREDIT_LIMIT_FOR_QUOTE_ENABLED)) {
                                this.quoteManager.calculateCustomerQuoteBalance(edsSaleQuote.getClient().getObjectID());
                            }
                        }
                    }
                    final EdsPickList pickList = this.pickListManager.getPickListBySaleQuoteID(edsSaleQuote.getObjectID());
                    if (companyID != null) {
                        try {
                            saleQuoteSolrComponent.indexes(Collections.singletonList(edsSaleQuote), (pickList != null) ? Collections.singletonList(pickList) : null);
                        } catch (final IOException | SolrServerException | InterruptedException e) {
                            e.printStackTrace();
                        }
                    }
                    break;
                case RelationItem.TYPE_CUSTOM_FORM_ITEM:
                    final EdsCustomFormItems edsCustomFormItem = (EdsCustomFormItems) approvable;
                    try {
                        customFormItemSolrComponent.index(edsCustomFormItem);
                    } catch (final IOException | SolrServerException | InterruptedException e) {
                        e.printStackTrace();
                    }
                    break;
                case TYPE_CREDIT_NOTE, TYPE_SALEINVOICE:
                    final EdsSaleInvoice edsSaleInvoice = (EdsSaleInvoice) approvable;
                    log.info("||||||||||||||||||||||| THE STATUS IS: " + edsSaleInvoice.getStatus().getCode() + " |||||||||||||||||||||||");
                    log.info("||||||||||||||||||||||| THE OVERALL STATUS IS: " + edsSaleInvoice.getOverallStatus().getCode() + " |||||||||||||||||||||||");
                    if (Constants.APPROVE.equals(edsSaleInvoice.getOverallStatus().getCode()) || EdsSaleQuote.PENDING.equals(edsSaleInvoice.getOverallStatus().getCode())) {
                        this.invoiceServiceLocal.createInvoiceTransactionsAndCalculateProjectBugdet(edsSaleInvoice, this.userManager.getUser());
                        if (TYPE_CREDIT_NOTE.equals(entityType) && edsSaleInvoice.getCreditNoteInvoice() != null
                                && edsSaleInvoice.getCreditNoteInvoice().getObjectID() != null && edsSaleInvoice.getCreditNoteInvoice().getDueAmount() != null) {
                            NewInvoice data = new NewInvoice();
                            data.setCreditedInvoiceID(edsSaleInvoice.getCreditNoteInvoice().getObjectID());
                            data.setCreditedInvoiceAmount(edsSaleInvoice.getDueAmount());
                            if (edsSaleInvoice.getCreditNoteInvoice().getDueAmount().compareTo(BigDecimal.ZERO) != 0
                                    && edsSaleInvoice.getCreditNoteInvoice().getDueAmount().compareTo(edsSaleInvoice.getDueAmount()) >= 0) {

                                saveCreditedInvoicePayment(data, edsSaleInvoice);
                            }
                        }
                    } else if (Constants.SUBMITTED_TO_MANAGER.equals(edsSaleInvoice.getOverallStatus().getCode())) {
                        final EdsInvoiceTransaction transaction = this.transactionManager.getTransactionByInvoice(edsSaleInvoice);
                        if (transaction != null && !transaction.isDeleted()) {
                            this.invoiceServiceLocal.deleteInvoiceTransaction(edsSaleInvoice.getObjectID(), Constants.SALE_INVOICE);
                        }
                    }
                    try {
                        saleInvoiceSolrComponent.index(edsSaleInvoice);

                        // Update GDN Invoice Status here
                        Set<EdsShippingData> data = edsSaleInvoice.getConvertedShippingData();
                        if (CollectionUtils.isNotEmpty(data)) {
                            shippingDataSolrComponent.indexes(new ArrayList<>(data));
                            EventHandler.fireEvent(WfmUiEventType.ON_GDN_GRN_LIST_RELOAD, "Related Invoice is approved by manager");
                        }
                        EventHandler.fireEvent(WfmUiEventType.ON_SALES_INVOICE_APPROVAL, "Invoice status is updated");
                    } catch (final IOException | SolrServerException | InterruptedException e) {
                        e.printStackTrace();
                    }
                    break;
                case TYPE_DEBIT_NOTE, TYPE_PURCHASE_INVOICE:
                    final EdsPurchaseInvoice edsPurchaseInvoice = (EdsPurchaseInvoice) approvable;
                    if (Constants.APPROVE.equals(edsPurchaseInvoice.getOverallStatus().getCode()) || Constants.PENDING.equals(edsPurchaseInvoice.getOverallStatus().getCode()) || Constants.OVER_DUE.equals(edsPurchaseInvoice.getOverallStatus().getCode())) {
                        this.invoiceServiceLocal.createInvoiceTransactionsAndCalculateProjectBugdet(edsPurchaseInvoice, this.userManager.getUser());
                    } else if (Constants.SUBMITTED_TO_MANAGER.equals(edsPurchaseInvoice.getOverallStatus().getCode())) {
                        final EdsInvoiceTransaction transaction = this.transactionManager.getTransactionByInvoice(edsPurchaseInvoice);
                        if (transaction != null && !transaction.isDeleted()) {
                            this.invoiceServiceLocal.deleteInvoiceTransaction(edsPurchaseInvoice.getObjectID(), Constants.SALE_INVOICE);
                        }
                    }
                    try {
                        purchaseInvoiceSolrComponent.index(edsPurchaseInvoice);

                        // Update GRN Invoice Status here
                        Set<EdsShippingData> data = edsPurchaseInvoice.getConvertedShippingData();
                        if (CollectionUtils.isNotEmpty(data)) {
                            shippingDataSolrComponent.indexes(new ArrayList<>(data));
                            EventHandler.fireEvent(WfmUiEventType.ON_GDN_GRN_LIST_RELOAD, "Related Invoice is approved by manager");
                        }
                        EventHandler.fireEvent(WfmUiEventType.ON_PURCHASE_INVOICE_APPROVAL, "Invoice status is updated");
                    } catch (final IOException | SolrServerException | InterruptedException e) {
                        e.printStackTrace();
                    }
                    break;
                case RelationItem.TYPE_PURCHASE_ORDER:
                    final EdsPurchaseOrder edsPurchaseOrder = (EdsPurchaseOrder) approvable;
                    if (Constants.APPROVE.equals(edsPurchaseOrder.getOverallStatus().getCode())) {
                        //this piece of the code need to calculate project budget
                        if (edsPurchaseOrder.getRelatedProject() != null || this.genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.PROJECT_IN_LINE_ITEM_ENABLE)) {
                            final EdsBusinessEvent event = this.baseEventPostProcessor.registerEvent(ProjectBudgetCustomEventListenerImpl.TYPE, ProjectBudgetCustomEventListenerImpl.PURCHASE_ORDER_APPROVE, edsPurchaseOrder, null);
                            event.setCustomStringField(edsPurchaseOrder.getRelatedProject() != null ? edsPurchaseOrder.getRelatedProject().getObjectID().toString() : null);
                        }
                    }
                    try {
                        purchaseOrderSolrComponent.index(edsPurchaseOrder);
                        EventHandler.fireEvent(WfmUiEventType.ON_PURCHASEORDER_ADDED, "Purchase Order status is updated");
                    } catch (final IOException | SolrServerException | InterruptedException e) {
                        e.printStackTrace();
                    }
                    break;
                case TYPE_STOCK_TRANSFER:
                    EdsStockTransfer stockTransfer = (EdsStockTransfer) approvable;
                    if (stockTransfer.getOverallStatus() != null && (STOCK_ADJUSTMENT_APPROVED.equals(stockTransfer.getOverallStatus().getCode()) || Constants.PENDING.equals(stockTransfer.getOverallStatus().getCode()))) {
                        accountingServiceLocal.createTransactionForStockTransfer(stockTransfer);
                        baseEventPostProcessor.registerEvent(StockTransferEventListenerImpl.TYPE, StockTransferEventListenerImpl.STOCK_TRANSFER_TRANSFERRED, stockTransfer, userManager.getUser());
                    }
                    break;
                case TYPE_STOCK_ADJUSTMENT:
                    EdsStockAdjustment edsStockAdjustment = (EdsStockAdjustment) approvable;

                    if (edsStockAdjustment.getOverallStatus() != null && (STOCK_ADJUSTMENT_APPROVED.equals(edsStockAdjustment.getOverallStatus().getCode()) || Constants.PENDING.equals(edsStockAdjustment.getOverallStatus().getCode()))) {
                        Integer transactionId = accountingServiceLocal.createTransactionsForStockAdjustment(edsStockAdjustment);

                        for (EdsAdjustmentItem edsAdjustmentItem : edsStockAdjustment.getAdjustmentItemList()) {
                            if (edsAdjustmentItem.getItem() != null && edsAdjustmentItem.getItem().getInventoryTrackingEnabled()) {
                                itemSerialService.createForStockAdjustment(edsAdjustmentItem, transactionId);
                                itemSerialService.assignForStockAdjustment(edsAdjustmentItem, transactionId);
                            }
                        }
                        baseEventPostProcessor.registerEvent(StockAdjustmentEventListenerImpl.TYPE, StockAdjustmentEventListenerImpl.STOCK_ADJUSTMENT_APPROVED, edsStockAdjustment, userManager.getUser());
                    }
                    break;
                case RelationItem.TYPE_PLACEMENT:
                    EdsPlacement edsPlacement = (EdsPlacement) approvable;

                    if (edsPlacement.getOverallStatus() != null && Constants.PLACEMENT_STATUS_APPROVED.equals(edsPlacement.getOverallStatus().getCode())) {
                        recruitmentService.saveApprovedHiredPlacement(edsPlacement.getObjectID(), true, null);
                    }
                    break;
                case RelationItem.TYPE_CERTIFICATE_OF_EMPLOYMENT:
                    try {
                        certificateSolrComponent.index((EdsCertificateOfEmployment) approvable);
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                    break;
                case RelationItem.TYPE_MANUAL_JOURNAL:
                    break;
                case TYPE_REQUEST_FOR_QUOTE:
                    final EdsRFQ rfq = (EdsRFQ) approvable;
                    try {
                        rfqSolrComponent.index(rfq);
                    } catch (final IOException | SolrServerException | InterruptedException e) {
                        e.printStackTrace();
                    }
                    break;
                case RelationItem.TYPE_VACANCY:
                    final EdsVacancy vacancy = (EdsVacancy) approvable;
                    try {
                        vacancySolrComponent.index(vacancy);
                    } catch (final IOException | SolrServerException | InterruptedException e) {
                        e.printStackTrace();
                    }
                    break;
                case RelationItem.TYPE_ROTATION:
                    final EdsRotation rotation = (EdsRotation) approvable;
                    if (rotation.getOverallStatus() != null && ROTATION_APPROVED.equals(rotation.getOverallStatus().getCode())) {
                        this.hrmsServiceLocal.updateEmployeeByRotation(rotation);
                    }
                    break;
                case RelationItem.TYPE_RECURRING_PAY_DEDUCTION:
                    if (isOk(approvable.getOverallStatus()) && EdsRecurringPayDeduction.APPROVED.equals(approvable.getOverallStatus().getCode())) {
                        EdsRecurringPayDeduction payDeduction = (EdsRecurringPayDeduction) approvable;
                        payDeduction.setApprovedDate(new Date());
                        payrollServiceLocal.approvedActionForRecurringPayDeduction(payDeduction.getObjectID());
                    }
                    break;
                case TYPE_BUILD_ASSEMBLY:
                    final EdsSavedAssemblyItem edsSavedAssemblyItem = (EdsSavedAssemblyItem) approvable;
                    EdsReference overallStatus = edsSavedAssemblyItem.getOverallStatus();
                    if (overallStatus != null && overallStatus.getCode() != null) {
                        String statusCode = switch (overallStatus.getCode()) {
                            case BUILD_ASSEMBLY_STATUS_APPROVED -> "approved";
                            case BUILD_ASSEMBLY_STATUS_SUBMITTED -> "submitted";
                            case BUILD_ASSEMBLY_STATUS_REJECTED -> "rejected";
                            default -> "draft";
                        };
                        buildAssemblyServiceLocal.saveBuildAssemblyNote(edsSavedAssemblyItem.getObjectID(), new HistoryListItem(statusCode));

                        if (BUILD_ASSEMBLY_STATUS_APPROVED.equals(overallStatus.getCode())) {
                            buildAssemblyServiceLocal.saveBuildAssemblyHistory(edsSavedAssemblyItem);
                        }
                    }
                    break;
                case RelationItem.TYPE_OVERTIME:
                    final EdsOvertimeObject overtimeObject = (EdsOvertimeObject) approvable;
                    if (isOk(overtimeObject.getOverallStatus()) && OVERTIME_APPROVED.equals(overtimeObject.getOverallStatus().getCode())) {
                        try {
                            this.payrollService.createAdditionalPaymentFromOvertime(overtimeObject.getObjectID());
                        } catch (Exception ex) {
                            ex.printStackTrace();
                        }
                    }
                    break;
            }
        }
    }

    private void saveCreditedInvoicePayment(NewInvoice data, EdsInvoice creditNote) {
        EdsUser user = invoiceManager.getUser();

        EdsInvoicePayment refund = new EdsInvoicePayment();
        refund.setAmount(data.getCreditedInvoiceAmount());
        refund.setPaymentDate(creditNote.getInvoiceDate());
        if (RECEIVABLE.equals(creditNote.getType())) {
            refund.setAccount(accountingManager.getAccountByKey(EdsAccount.ACCOUNTS_RECEIVABLE));
        } else {
            refund.setAccount(accountingManager.getAccountByKey(EdsAccount.ACCOUNTS_PAYABLE));
        }
        EdsInvoice invoice = invoiceManager.get(data.getCreditedInvoiceID() == null ? data.getID() : data.getCreditedInvoiceID());
        refund.setCreditNote(creditNote);
        refund.setInvoice(invoice);

        refund.setReference(invoice.getNumber());
        refund.setExchangeRate(creditNote.getExchangeRate());
        refund.setCurrencyID(creditNote.getCurrency().getObjectID());
        refund.setUser(user);
        invoice.getPayments().add(refund);
        creditNote.getRefunds().add(refund);

        checkAndUpdateInvoiceCreditNoteStatuses(creditNote, true);
        checkAndUpdateInvoiceCreditNoteStatuses(invoice, false);

        accountingServiceLocal.createTransactionForCreditedInvoice(refund);

        if (RECEIVABLE.equals(creditNote.getType())) {
            baseEventPostProcessor.registerEvent(InvoicePaymentEventListenerImpl.TYPE, InvoicePaymentEventListenerImpl.EVENT_SALES_INVOICE_PAYMENT_RECEIVE, refund, user);
        } else {
            baseEventPostProcessor.registerEvent(InvoicePaymentEventListenerImpl.TYPE, InvoicePaymentEventListenerImpl.EVENT_PURCHASE_INVOICE_PAYMENT_PAY, refund, user);
        }
    }

    private void checkAndUpdateInvoiceCreditNoteStatuses(EdsInvoice invoiceOrNote, boolean isCreditNote) {
        EdsUser user = invoiceManager.getUser();

        Integer calculationScale = financialSettingsManager.getFinancialSettings().getAccountingCalculationScale();
        List<EdsInvoicePayment> refundsOrPayments = (isCreditNote ? invoiceOrNote.getRefunds() : invoiceOrNote.getPayments());

//        List<EdsInvoicePayment> refundsOrPayments;
//        if (isCreditNote) {
//            refundsOrPayments = invoicePaymentManager.getRefunds(invoiceOrNote);
//        } else {
//            refundsOrPayments = invoicePaymentManager.getPayments(invoiceOrNote);
//        }
//        BigDecimal fullPayments = ZERO;
//        for (EdsInvoicePayment item : refundsOrPayments) {
//            if (!item.isReversed()) {
//                fullPayments = fullPayments.add(item.getAmountInInvoiceCurrency() != null ? item.getAmountInInvoiceCurrency() : item.getAmount());
//            }
//        }

        BigDecimal totalInInvoiceCurrency = invoiceOrNote.getTotalInInvoiceCurrency() != null ? invoiceOrNote.getTotalInInvoiceCurrency()
                : invoiceOrNote.getTotal().multiply(invoiceOrNote.getExchangeRate());

        if (totalInInvoiceCurrency.setScale(calculationScale, RoundingMode.HALF_UP).compareTo(invoiceOrNote.getFullPayments().setScale(calculationScale, RoundingMode.HALF_UP)) <= 0) {
            invoiceOrNote.setPaidDate(getCompanyDate(user));
            invoiceOrNote.setStatus(referenceManager.findReference(INVOICE_STATUS, PAID));
        } else if (totalInInvoiceCurrency.compareTo(invoiceOrNote.getFullPayments()) >= 0 && PAID.equals(invoiceOrNote.getStatus().getCode())) {
            invoiceOrNote.setStatus(referenceManager.findReference(INVOICE_STATUS, APPROVE));
        }
        if (RECEIVABLE.equals(invoiceOrNote.getType())) {
            EdsSaleInvoice saleInvoice = invoiceManager.getSaleInvoice(invoiceOrNote.getObjectID());
            if (saleInvoice != null) {
                try {
                    if (isCreditNote) {
                        saleInvoice.setRefunds(refundsOrPayments);
                    } else {
                        saleInvoice.setPayments(refundsOrPayments);
                    }
                    saleInvoiceSolrComponent.index(saleInvoice);
                } catch (IOException | SolrServerException | InterruptedException e) {
                    e.printStackTrace();
                }
            }
        } else if (PAYABLE.equals(invoiceOrNote.getType())) {
            EdsPurchaseInvoice purchaseInvoice = invoiceManager.getPurchaseInvoice(invoiceOrNote.getObjectID());
            if (purchaseInvoice != null) {
                try {
                    if (isCreditNote) {
                        purchaseInvoice.setRefunds(refundsOrPayments);
                    } else {
                        purchaseInvoice.setPayments(refundsOrPayments);
                    }
                    purchaseInvoiceSolrComponent.index(purchaseInvoice);
                } catch (IOException | SolrServerException | InterruptedException e) {
                    e.printStackTrace();
                }
            }
        }
    }

    private Date getCompanyDate(EdsUser user) {
        Calendar companyTime = new GregorianCalendar(TimeZone
                .getTimeZone(user.getCompany().getCountryZone().getZone().getZoneID()));
        return companyTime.getTime();
    }

    private void calculateAdditionalLogicForBCLeaveReason(EdsSickRequest leaveRequest) {
        Integer employeeId = leaveRequest.getEmployee().getObjectID();
        Calendar calendar = Calendar.getInstance();
        calendar.setTime(leaveRequest.getStartDate() != null ? leaveRequest.getStartDate() : new Date());
        EdsLabourPeriod labourPeriod = labourPeriodManager.getPeriodByEmployeeIdAndDate(employeeId, leaveRequest.getStartDate(), leaveRequest.getEndDate());
        if (labourPeriod == null || labourPeriod.getStartDate() == null || labourPeriod.getEndDate() == null) {
            return;
        }
        ListingFilterParameter fp = new ListingFilterParameter();
        fp.setEmployeeId(leaveRequest.getEmployee().getObjectID());
        fp.setStartDate(labourPeriod.getStartDate());
        fp.setEndDate(labourPeriod.getEndDate());
        fp.setStatusCode(EdsSickRequest.APPROVED);
        fp.setReasonCode("Б/С");
        List<LeaveRequestLisItem> empLeaveRequests = availabilityService.getLeaveRequestList(fp).getList();
        BigDecimal summary = BigDecimal.ZERO;
        boolean isCurrentLeaveIncluded = false;
        for (LeaveRequestLisItem listItem : empLeaveRequests) {
            if (listItem.getObjectId() != null && listItem.getObjectId().equals(leaveRequest.getObjectID())) {
                isCurrentLeaveIncluded = true;
            }
            summary = summary.add(new BigDecimal(availabilityService.getLeaveDaysCount(fp, listItem.getStartDate(), listItem.getEndDate())));
        }
        if (!isCurrentLeaveIncluded) {
            summary = summary.add(new BigDecimal(availabilityService.getLeaveDaysCount(fp, new DateNonConvertable(leaveRequest.getStartDate()), new DateNonConvertable(leaveRequest.getEndDate())).replace(",", ".")));

        }
        double different = labourPeriod.getActualAllowanceDays() - (summary.divide(BigDecimal.valueOf(14), 2, RoundingMode.HALF_UP)).intValue();
        if (different >= 0.0) {
            labourPeriod.setAllowance(different);
            labourPeriodManager.createOrUpdate(labourPeriod);
        }
    }

