    private void createAndUploadPDF(EdsBaseInvoice baseInvoice, ByteArrayOutputStream baos, FolderResource folder, EdsApprovable approvable, EdsSickRequest edsSickRequest) {
        EdsUser user = this.userManager.getUser();
        String currentDate = ServerUtils.longDateFormat(user.getUserDate(new Date()), user);

        String approverFullName = approvable != null && approvable.getCurrentApprover() != null
                && approvable.getCurrentApprover().getExactEmployee() != null
                && approvable.getCurrentApprover().getExactEmployee().getFullName() != null
                ? approvable.getCurrentApprover().getExactEmployee().getFullName()
                : user.getFullName();
        String number = baseInvoice != null ? baseInvoice.getNumber() : edsSickRequest != null ? edsSickRequest.getNumberData() : "";
        String pdfFileName = "Approved_By_" + approverFullName + "_" + currentDate + "_" + number + ".pdf";
        ByteArrayInputStream bais = new ByteArrayInputStream(baos.toByteArray());

        EdsUpload upload = new EdsUpload();
        upload.setContentType("application/pdf");
        upload.setOriginalName(pdfFileName);
        upload.setType(referenceManager.findReference(_UPLOAD_TYPE, EdsContextParams.getUploadType()));
        upload.setInputStream(bais);
        uploadManager.create(upload);
        upload.setInputStream(uploadManager.getInputStream((EdsUpload) uploadManager.get(upload.getObjectID())));

        if (upload.getObjectID() != null) {
            saveFileResource(upload, folder);
        }
    }

    private void saveFileResource(EdsUpload upload, FolderResource folder) {
        FileResource f = new FileResource();
        f.setBodyId(upload.getObjectID());
        f.setName(upload.getOriginalName());
        f.setContentLength(upload.getSize());
        f.setContentType(upload.getContentType());
        f.setUploadType(upload.getType() != null ? upload.getType().getName() : "");

        DocumentItem fileBody = new DocumentItem();
        fileBody.setInputStream(upload.getInputStream());
        fileBody.setContentType(DocumentsServiceImpl.identifyMimeType(upload.getOriginalName()));
        fileBody.setName(upload.getOriginalName());
        fileBody.setFolderId(folder.getObjectId());
        fileBody.setDriveFolderId(folder.getDriveFolderId());
        fileBody.setDriveFolderName(folder.getDriveFolderName());
        fileBody.setDuration(folder.getDuration());
        fileBody.setDownloadable(f.isDownloadable());
        try {
            documentServiceLocal.createFile(fileBody, f.getUploadType(), folder.getFileType(), folder.getEntityId());
        } catch (DuplicateNameException | ObjectNotFoundException | QuotaExceededException |
                 InsufficientPermissionsException e) {
            e.printStackTrace();
        }
    }

