    @Override
    public String shortenLink(String link, CrmAccountItem item) {
        HttpHeaders httpHeaders = new HttpHeaders();
        httpHeaders.setContentType(MediaType.APPLICATION_JSON);
        httpHeaders.add("Authorization", "sk_aZggqoDqpJxAtClR");
        String requestBody = "{\n" +
                "  \"originalURL\": \"" + link + "\"," +
                "  \"domain\" : \"" + SHORTENER_DOMAIN + "\"" +
                "}";
        HttpEntity<String> entity = new HttpEntity<String>(requestBody, httpHeaders);
        ShortenedLinkResponse body = restTemplate.exchange(SHORTENER_API, HttpMethod.POST, entity, ShortenedLinkResponse.class).getBody();
        switch (item.getSaleType()) {
            case "invoice" -> {
                EdsInvoice invoice = this.invoiceManager.getInvoice(item.getObjectId());
                if (invoice == null) {
                    invoice = this.invoiceManager.getSaleInvoice(item.getObjectId());
                }
                if (invoice.getShortLink() != null) {
                    return invoice.getShortLink();
                }
                invoice.setShortLink(body.getShortURL());
                invoiceManager.update(invoice);
            }
            case "quote" -> {
                EdsSaleQuote invoice = quoteManager.getSaleQuote(item.getObjectId());
                if (invoice.getShortLink() != null) {
                    return invoice.getShortLink();
                }
                invoice.setShortLink(body.getShortURL());
                quoteManager.update(invoice);
            }
            case "order" -> {
                EdsQuote order = quoteManager.getOrderById(item.getObjectId());
                if (order.getShortLink() != null) {
                    return order.getShortLink();
                }
                order.setShortLink(body.getShortURL());
                quoteManager.update(order);
            }
        }
        return body.getShortURL();
    }

