    private SelectItem[] getCustomFieldAttributes(final SelectItem[] attributes) {
        if (this.userManager.getUser() != null && this.userManager.getUser().getCompany() != null) {
            if (Integer.valueOf(3737).equals(this.userManager.getUser().getCompany().getObjectID())) {
                final List<SelectItem> newAttributes = new ArrayList<>(Arrays.asList(attributes));
                newAttributes.add(new SelectItem(attributes.length, "Support Person Email", EmailTemplateConstants.CRM.CRM_CASE.CASE_SUPPORT_PERSON_EMAIL));
                return newAttributes.toArray(new SelectItem[]{});
            }
        }
        return attributes;
    }


    public Map<String, String> getLeaveReasonMap(final String formId) {
        final Map<String, String> leaveReasonMap = new HashMap<>();
        if (LayoutRPC.HRMS_EMPLOYEE_FORM.equals(formId)) {
            final List<EdsLeaveReason> annualLeaveReasons = this.leaveReasonManager.listActiveReasons();
            for (final EdsLeaveReason annualLeaveReason : annualLeaveReasons) {
                leaveReasonMap.put(annualLeaveReason.getCode(), annualLeaveReason.getName() + " (allowance)");
            }
        }
        return leaveReasonMap;
    }

    @Override
    @Transactional
    public SelectItem[] getLookUpItems(final ListingFilterParameter filterParameters, Integer type, String query) {
        if (type == null) {
            type = 0;
        }
        if (filterParameters != null) {
            if (filterParameters.isCRM()) {
                return this.crmServiceLocal.getLookUpItems(filterParameters, type).getList().toArray(new SelectItem[]{});
            } else if (filterParameters.isTrainingCenter()) {
                return this.tcService.getLookUpItems(filterParameters, type);
            } else if (filterParameters.isHRMS()) {
                return this.hrmsServiceLocal.getLookUpItems(filterParameters, type);
            } else if (filterParameters.isPM()) {
                return this.projectServiceLocal.getLookUpItems(filterParameters, type);
            } else if (filterParameters.getType() != null && CrmConstants.TYPE_CRM_CONTACT == filterParameters.getType()) {
                return this.accountingService.getClientList(filterParameters);
            } else if (filterParameters.getFormtype() != null) {
                return this.commonService.getCustomFormItemsForLookUp(filterParameters.getFormtype());
            } else if (filterParameters.getType() != null && LookUpConstants.BRIGADA_ID == filterParameters.getType()) {
                return this.crmService.getOwnersListByPermission(PermissionConstants.BRIGADA_OWNER_LIST);
            } else if (filterParameters.getType() != null && LookUpConstants.SHIFT_ID == filterParameters.getType()) {
                return this.crmService.getOwnersListByPermission(PermissionConstants.SHIFT_OWNER_LIST);
            } else if (filterParameters.getType() != null && LookUpConstants.LOCATION_OWNERS == filterParameters.getType()) {
                return this.locationService.getLocationOwnersByRole();
            } else if (filterParameters.getType() != null && LookUpConstants.VACANCIES.equals(filterParameters.getType())) {
                return this.recruitmentService.getVacancyLookUpItems(filterParameters);
            } else if (type == LookUpConstants.COUNTRY_ID) {
                return commonService.getCountries(filterParameters, true);
            } else if (type == LookUpConstants.CRM_OPPORTUNITY_ASSIGNEE_ID) {
                ListingFilterParameter filterParametrs = new ListingFilterParameter();
                filterParametrs.setListEmployees(true);
                filterParametrs.setPermissionCode(PermissionConstants.CRM_OPPORTUNITY_ASSIGNEE_LIST_VALUE);
                filterParametrs.setWithoutCode(true);
                return getEmployeesAsSelectItem(new ListLoadConfig(), filterParametrs);
            } else if (type == LookUpConstants.FIXEDASSET_OWNERS_ID) {
                return getEmployeesAsSelectItem(filterParameters);
            } else if (type == LookUpConstants.PRODUCT_SALES_ACCOUNT_ID) {
                ArrayList<String> types = new ArrayList<>(List.of(REVENUE, LIABILITIES));
                filterParameters.setSystem(false);
                filterParameters.setValidateChildAccounts(false);
                filterParameters.setAllByFilter(false);
                return getAccountsForInvoice(filterParameters, types);
            } else if (type == LookUpConstants.PRODUCT_PURCHASE_ACCOUNT_ID || type == LookUpConstants.FIXEDASSET_EXPENSE_ACCOUNT_ID) {
                filterParameters.setSystem(false);
                filterParameters.setValidateChildAccounts(false);
                filterParameters.setAllByFilter(false);
                ArrayList<String> types = new ArrayList<>(List.of(EXPENSES));
                return getAccountsForInvoice(filterParameters, types);
            } else if (type == LookUpConstants.PRODUCT_ASSETS_ACCOUNT_ID) {
                filterParameters.setSystem(false);
                filterParameters.setValidateChildAccounts(false);
                filterParameters.setAllByFilter(false);
                ArrayList<String> types = new ArrayList<>(List.of(ASSETS));
                return getAccountsForInvoice(filterParameters, types);
            } else if (type == LookUpConstants.FIXEDASSET_FINANCE_BY_ACCOUNT_ID) {
                filterParameters.setSystem(false);
                filterParameters.setValidateChildAccounts(false);
                filterParameters.setAllByFilter(false);
                ArrayList<String> types = new ArrayList<>(List.of(FINANCED_BY));
                return getAccountsForInvoice(filterParameters, types);
            } else if (type == LookUpConstants.PRODUCT_UNIT_MEASUREMENT_ID) {
                return getUnitMeasurements(filterParameters);
            } else if (type == LookUpConstants.FIXEDASSET_ACCOUNT_ID) {
                filterParameters.setSystem(false);
                filterParameters.setValidateChildAccounts(false);
                filterParameters.setAllByFilter(false);
                ArrayList<String> types = new ArrayList<>(List.of(FIXED_ASSET));
                return getAccountsForInvoice(filterParameters, types);
            } else if (query != null) {
                return getEntityCustomFieldLookUpData(query, filterParameters);
            }
        }
        return this.accountingService.getLookUpItems(filterParameters, type);
    }


