    @Override
    @Transactional
    public Integer saveModelForm(final ModelForm form) {
        System.out.println(form);
        EdsModel model = null;
        if (form.getObjectID() != null) {
            model = this.modelManager.get(form.getObjectID(), form.isCustom());
        }
        if (model == null) {
            model = new EdsModelCustom();
        }
        model.setActive(form.isActive());
        model.setFormID(form.getFormID());
        model.setTitle(form.getTitle());
        model.setViewName(form.getViewName());
        model.setStepForm(form.isStepForm());
        model.setCustomForm(form.isCustomForm());
        model.setCertificateForm(form.isCertificateForm());
        model.setQuizForm(form.isQuizForm());
        this.modelManager.createOrUpdate(model);

        EdsCustomFormSection formSection = this.customFormSectionManager.getCustomizeFormSection(form.getFormID(), CustomFormConstants.GENERAL_INFORMATION);
        if (formSection == null) {
            formSection = new EdsCustomFormSection();
        }
        EdsCustomFormLocalization localization = formSection.getEdsCustomFormLocalization() != null ? formSection.getEdsCustomFormLocalization() : new EdsCustomFormLocalization();
        localization.setType(Constants.SECTION);
        localization.setSection(CustomFormConstants.GENERAL_INFORMATION);
        localization.setDefaultName(CustomFormConstants.GENERAL_INFORMATION);
        localization.setEnglishName(CustomFormConstants.GENERAL_INFORMATION);
        localization.setArabicName(CustomFormConstants.GENERAL_INFORMATION);
        localization.setRussianName(CustomFormConstants.GENERAL_INFORMATION);
        localization.setUzbekName(CustomFormConstants.GENERAL_INFORMATION);
        localization.setFormId(form.getFormID());
        customFormLocalizationManager.createOrUpdate(localization);
        formSection.setEdsCustomFormLocalization(localization);
        formSection.setSection(CustomFormConstants.GENERAL_INFORMATION);
        formSection.setForm_ID(form.getFormID());
        formSection.setCustom(false);
        formSection.setActive(true);
        formSection.setSorder(0);
        this.customFormSectionManager.createOrUpdate(formSection);

        for (final ModelField field : form.getFields()) {
            this.saveModelField(field);
        }
        return model.getObjectID();
    }

