    private Integer saveModelField(final ModelField field) {
        EdsModelField edsField = null;
        if (field.getObjectID() != null) {
            edsField = this.modelFieldManager.get(field.getObjectID(), field.isCustom());
        }
        if (edsField == null) {
            edsField = new EdsModelFieldCustom();
        }
        edsField.setForm_ID(field.getForm_ID());
        edsField.setField_ID(field.getField_ID());
        edsField.setForder(field.getSorder());
        edsField.setFsection(field.getSection());
        edsField.setColumnType(field.getColumnType());
        edsField.setCustomField(field.isIsCustomField());
        edsField.setNoLabelFor(field.getNoLabelFor());
        edsField.setHide(field.isHide());
        edsField.setMandatory(field.isMandatory());
        edsField.setLabel(field.getLabel());
        edsField.setWidget(field.getWidget());
        edsField.setEntityField(field.isEntityField());
        edsField.setUsableByWorkflow(field.isUsableByWorkflow());
        edsField.setSource(field.getSource());
        this.modelFieldManager.createOrUpdate(edsField);


        return edsField.getObjectID();
    }

