    @Override
    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public SelectItem[] getAccountsForPayment(final ListingFilterParameter filterParameters) {
        final List<EdsAccount> accounts = this.accountingManager.getAccountsForPayment(filterParameters);
        final SelectItem[] items = new SelectItem[accounts.size()];
        int i = 0;
        if (filterParameters.isWithCode()) {
            for (final EdsAccount item : accounts) {
                items[i] = new SelectItem(item.getObjectID(), item.getAccountCode() + " -> " + item.getName(),
                        item.getBalance() != null ? item.getBalance().toString() : null, item.getCurrency().getObjectID());
                i++;
            }
        } else {
            for (final EdsAccount item : accounts) {
                items[i] = new SelectItem(item.getObjectID(), item.getName(), item.getBalance() != null ? item.getBalance().toString() : null, item.getCurrency().getObjectID());
                i++;
            }
        }

        return items;
    }

    @Transactional
    public void deleteEmailFilter(final Integer objectID) {
        if (objectID != null) {
            final EdsEmailFilter emailFilter = this.emailFilterManager.get(objectID);
            if (emailFilter != null) {
                if (emailFilter.getSubFilters() != null && emailFilter.getSubFilters().size() > 0) {
                    for (final EdsEmailFilter e : emailFilter.getSubFilters()) {
                        this.deleteEmailFilter(e.getObjectID());
                    }
                }
                emailFilter.setDeleted(true);
            }
        }
    }

