    @Override
    public InOutItem[] getInOutReportItems(Integer employeeId, Date fromDate, Date toDate) {
        List<InOutItem> reportItems = new ArrayList<>();
        Map<Integer, Map<Integer, FingerprintTimeDto>> fingerprintData = timeSlotManager.getFingerprintData(null, String.valueOf(employeeId), null, fromDate, toDate);
        Map<Integer, FingerprintTimeDto> integerFingerprintTimeDtoMap = fingerprintData.get(employeeId);
        Date newDate = new Date();
        DateFormat format = new SimpleDateFormat("yyyy-MM-dd");

        while (!fromDate.after(newDate)) {
            fromDate.setDate(fromDate.getDate() + 1);
            FingerprintTimeDto fingerprintTimeDto = integerFingerprintTimeDtoMap.get(fromDate.getDate());
            InOutItem item = new InOutItem();
            item.setDateName(format.format(fromDate));
            item.setEmployeeId(employeeId);
            if (fingerprintTimeDto != null) {
                if (fingerprintTimeDto.getIntime() != null) {
                    item.setInHours(new String[]{String.valueOf(formatMinutesToHHmm(fingerprintTimeDto.getIntime()))});
                }
                if (fingerprintTimeDto.getOuttime() != null) {
                    item.setOutHours(new String[]{String.valueOf(formatMinutesToHHmm(fingerprintTimeDto.getOuttime()))});
                }
                if (fingerprintTimeDto.getActualtime() != null) {
                    item.setDuration(new String[]{String.valueOf(formatMinutesToHHmm(fingerprintTimeDto.getActualtime()))});
                }
            }
            reportItems.add(item);
        }
        return reportItems.toArray(new InOutItem[0]);
    }

    private String formatMinutesToHHmm(int minutes) {
        int hours = minutes / 60;
        int mins = minutes % 60;
        String h = (hours < 10 ? "0" : "") + hours;
        String m = (mins < 10 ? "0" : "") + mins;
        return h + ":" + m;
    }

    @Override
    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public ArrayList<RelationItem> getAdditionalRelations(final Integer relationID, final String relationType,
                                                          final String relationName, final Integer fromID, final String fromType, final String fromName) {
        final ArrayList<RelationItem> result = new ArrayList<>();
        final RelationItem self = new RelationItem(null, relationID, relationType, this.getRelationName(relationID, relationType), fromID, fromType, fromName);
        result.add(self);
        if (RelationItem.TYPE_OPPORTUNITY.equals(relationType)) {
            final EdsOpportunity entity = this.opportunityManager.get(relationID);
            if (entity.getCrmAccount() != null) {
                final EdsCrmAccount edsAccount = entity.getCrmAccount();
                result.add(new RelationItem(null, edsAccount.getObjectID(), RelationItem.TYPE_CRM_ACCOUNT, edsAccount.getName(), fromID, fromType, fromName));
            }
            if (entity.getCrmContact() != null) {
                final EdsCrmContact crmContact = entity.getCrmContact();
                result.add(new RelationItem(null, crmContact.getObjectID(), RelationItem.TYPE_CONTACT, crmContact.getName(), fromID, fromType, fromName));
            }
        } else if (RelationItem.TYPE_CONTACT.equals(relationType) || RelationItem.TYPE_LEAD.equals(relationType) || RelationItem.TYPE_CANDIDATE.equals(relationType)) {
            final EdsCrmContact contact = this.crmContactManager.get(relationID);
            if (contact.getCrmAccount() != null) {
                final EdsCrmAccount edsAccount = contact.getCrmAccount();
                result.add(new RelationItem(null, edsAccount.getObjectID(), RelationItem.TYPE_CRM_ACCOUNT, edsAccount.getName(), fromID, fromType, fromName));
            }
        } else if (RelationItem.TYPE_PROJECT.equals(relationType)) {
            final EdsProject project = this.projectManager.get(relationID);
            if (project != null && project.getClient() != null) {
                result.add(new RelationItem(null, project.getClient().getObjectID(), RelationItem.TYPE_CRM_ACCOUNT, project.getClient().getName(), fromID, fromType, fromName));
            }
        } else if (RelationItem.TYPE_TASK.equals(relationType)) {
            final EdsTask task = this.taskManager.get(relationID);
            final EdsProject project = task.getProject();

            if (project != null) {
                result.add(new RelationItem(null, project.getObjectID(), RelationItem.TYPE_PROJECT, project.getNumber() != null ? project.getNumber() + "-" : " " + project.getName(), fromID, fromType, fromName));
            }
            if (project != null && project.getClient() != null) {
                result.add(new RelationItem(null, project.getClient().getObjectID(), RelationItem.TYPE_CRM_ACCOUNT, project.getClient().getName(), fromID, fromType, fromName));
            }
        } else if (RelationItem.TYPE_ISSUE.equals(relationType)) {
            final EdsIssue issue = this.issueManager.get(relationID);
            final EdsProject project = issue.getProject();

            if (project != null) {
                result.add(new RelationItem(null, project.getObjectID(), RelationItem.TYPE_PROJECT, project.getNumber() != null ? project.getNumber() + "-" : " " + project.getName(), fromID, fromType, fromName));
            }
            if (project != null && project.getClient() != null) {
                result.add(new RelationItem(null, project.getClient().getObjectID(), RelationItem.TYPE_CRM_ACCOUNT, project.getClient().getName(), fromID, fromType, fromName));
            }
        } else if (RelationItem.TYPE_SALEQUOTE.equals(relationType) || RelationItem.TYPE_SALEORDER.equals(relationType)) {
            final EdsSaleQuote saleQuote = (EdsSaleQuote) this.quoteManager.get(relationID);

            if (saleQuote != null && saleQuote.getClient() != null) {
                result.add(new RelationItem(null, saleQuote.getClient().getObjectID(), RelationItem.TYPE_CLIENT, saleQuote.getClient().getName(), fromID, fromType, fromName));
                result.add(new RelationItem(null, saleQuote.getClient().getObjectID(), RelationItem.TYPE_CRM_ACCOUNT, saleQuote.getClient().getName(), fromID, fromType, fromName));
            }
        } else if (RelationItem.REQUEST_FOR_PURCHASE.equals(relationType)) {
            final EdsRFP rfp = this.rfpManager.get(relationID);

            if (rfp != null && rfp.getClient() != null) {
                result.add(new RelationItem(null, rfp.getClient().getObjectID(), RelationItem.TYPE_CRM_ACCOUNT, rfp.getClient().getName(), fromID, fromType, fromName));
            }
        } else if (TYPE_REQUEST_FOR_QUOTE.equals(relationType)) {
            final EdsRFQ rfq = this.rfqManager.get(relationID);

            if (rfq != null && rfq.getClient() != null) {
                result.add(new RelationItem(null, rfq.getClient().getObjectID(), RelationItem.TYPE_CRM_ACCOUNT, rfq.getClient().getName(), fromID, fromType, fromName));
            }
        } else if (TYPE_SALEINVOICE.equals(relationType)) {
            final EdsSaleInvoice saleInvoice = (EdsSaleInvoice) this.invoiceManager.get(relationID);

            if (saleInvoice != null && saleInvoice.getClient() != null) {
                result.add(new RelationItem(null, saleInvoice.getClient().getObjectID(), RelationItem.TYPE_CLIENT, saleInvoice.getClient().getName(), fromID, fromType, fromName));
                result.add(new RelationItem(null, saleInvoice.getClient().getObjectID(), RelationItem.TYPE_CRM_ACCOUNT, saleInvoice.getClient().getName(), fromID, fromType, fromName));
            }
        } else if (RelationItem.TYPE_PURCHASE_ORDER.equals(relationType)) {
            final EdsPurchaseOrder purchaseOrder = (EdsPurchaseOrder) this.quoteManager.get(relationID);

            if (purchaseOrder != null && purchaseOrder.getSupplier() != null) {
                result.add(new RelationItem(null, purchaseOrder.getSupplier().getObjectID(), RelationItem.TYPE_SUPPLIER, purchaseOrder.getSupplier().getName(), fromID, fromType, fromName));
                result.add(new RelationItem(null, purchaseOrder.getSupplier().getObjectID(), RelationItem.TYPE_CRM_ACCOUNT, purchaseOrder.getSupplier().getName(), fromID, fromType, fromName));
            }
        } else if (RelationItem.TYPE_GDN.equals(relationType)) {
            final EdsShippingData gdn = this.shippingDataManager.get(relationID);

            if (gdn != null && gdn.getCrmAccount() != null) {
                result.add(new RelationItem(null, gdn.getCrmAccount().getObjectID(), RelationItem.TYPE_CRM_ACCOUNT, gdn.getCrmAccount().getName(), fromID, fromType, fromName));
            }
        } else if (RelationItem.TYPE_SHIPPING_DATA.equals(relationType)) {
            final EdsPickList pickList = this.pickListManager.get(relationID);

            if (pickList != null && pickList.getSaleQuote() != null && pickList.getSaleQuote().getClient() != null) {
                result.add(new RelationItem(null, pickList.getSaleQuote().getClient().getObjectID(), RelationItem.TYPE_CRM_ACCOUNT, pickList.getSaleQuote().getClient().getName(), fromID, fromType, fromName));
            }
        } else if (TYPE_PURCHASE_INVOICE.equals(relationType)) {
            final EdsPurchaseInvoice purchaseInvoice = (EdsPurchaseInvoice) this.invoiceManager.get(relationID);

            if (purchaseInvoice != null && purchaseInvoice.getSupplier() != null) {
                result.add(new RelationItem(null, purchaseInvoice.getSupplier().getObjectID(), RelationItem.TYPE_SUPPLIER, purchaseInvoice.getSupplier().getName(), fromID, fromType, fromName));
                result.add(new RelationItem(null, purchaseInvoice.getSupplier().getObjectID(), RelationItem.TYPE_CRM_ACCOUNT, purchaseInvoice.getSupplier().getName(), fromID, fromType, fromName));
            }
        } else if (TYPE_EXPENSE_CLAIM.equals(relationType)) {
            final EdsExpenseReport expenseReport = this.expenseReportManager.get(relationID);

            if (expenseReport != null && expenseReport.getSupplier() != null) {
                result.add(new RelationItem(null, expenseReport.getSupplier().getObjectID(), RelationItem.TYPE_CRM_ACCOUNT, expenseReport.getSupplier().getName(), fromID, fromType, fromName));
            }
        } else if (RelationItem.TYPE_VACANCY.equals(relationType)) {
            final EdsVacancy vacancy = this.vacancyManager.get(relationID);

            if (vacancy != null && vacancy.getObjectID() != null) {
                result.add(new RelationItem(null, vacancy.getObjectID(), RelationItem.TYPE_VACANCY, vacancy.getName(), fromID, fromType, fromName));
            }
        }
        return result;
    }

    @Override
    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public EmailTemplateItem getEventDetails(Integer eventID) {
        EdsEvent event = eventManager.get(eventID);
        EdsEmailSetting companyEmailSetting = emailSettingsManager.getCompanyEmailSetting(SecurityContext.getCompanyID());
        List<EdsRelation> edsRelationList = relationManager.getAllRelations(EdsRelation.TYPE_EVENT, event.getObjectID());
        String guests = messageManager.getEventGuests(event);

        String toEmail = "";

        if (edsRelationList != null && !edsRelationList.isEmpty()) {
            toEmail = edsRelationList.stream()
                    .map(r -> {
                        if (("candidate".equals(r.getToType()) || "contact".equals(r.getToType()) || "lead".equals(r.getToType())) && r.getToID() != null) {
                            EdsCrmContact edsCrmContact = crmContactManager.get(r.getToID());
                            if (edsCrmContact != null && edsCrmContact.getPrimaryEmail() != null) {
                                return edsCrmContact.getPrimaryEmail();
                            } else {
                                assert edsCrmContact != null;
                                return edsCrmContact.getEmails().stream()
                                        .filter(e -> e != null && !"".equals(e))
                                        .findFirst();
                            }
                        } else if ("client".equals(r.getToType()) && r.getToID() != null) {
                            EdsClientContact clientContact = clientContactManager.get(r.getToID());
                            EdsCrmContact client = clientContact.getCrmContact();
                            if (client != null && client.getPrimaryEmail() != null) {
                                return client.getPrimaryEmail();
                            } else {
                                assert client != null;
                                return client.getEmails().stream()
                                        .filter(e -> e != null && !"".equals(e))
                                        .findFirst();
                            }
                        } else if ("EMPLOYEE".equals(r.getToType()) && r.getToID() != null) {
                            return employeeManager.get(r.getToID()).getEmail();
                        }
                        return null;
                    })
                    .map(String::valueOf)
                    .collect(Collectors.joining(","));
        }

        EmailTemplateItem emailTemplateItem = new EmailTemplateItem();
        emailTemplateItem.setFromEmail(companyEmailSetting != null ? companyEmailSetting.getEmail() : null);
        emailTemplateItem.setToEmail(toEmail);
        emailTemplateItem.setSubject(event.getSubject());
        emailTemplateItem.setMessageHTML(event.getDescription());
        if (!"".equals(guests)) {
            emailTemplateItem.setCc(guests);
        }
        emailTemplateItem.setBcc(companyEmailManager.getCompanyEmail(SecurityContext.getCompanyID()));
        return emailTemplateItem;
    }

    @Override
    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public String getRelationName(final Integer relationID, final String relationType) {
        if (relationID == null) {
            return null;
        }
        String name = null;
        if (RelationItem.TYPE_TASK.equals(relationType)) {
            final EdsTask task = this.taskManager.get(relationID);
            name = task != null ? task.getName() : null;
        } else if (RelationItem.TYPE_PROJECT.equals(relationType)) {
            final EdsProject project = this.projectManager.get(relationID);
            name = project != null ? project.getName() : null;
        } else if (RelationItem.TYPE_ISSUE.equals(relationType)) {
            final EdsIssue issue = this.issueManager.get(relationID);
            name = issue != null ? issue.getName() : null;
        } else if (RelationItem.TYPE_OPPORTUNITY.equals(relationType)) {
            final EdsOpportunity entity = this.opportunityManager.get(relationID);
            name = entity != null ? entity.getName() : null;
        } else if (RelationItem.TYPE_CRM_ACCOUNT.equals(relationType) || RelationItem.TYPE_CLIENT.equals(relationType) || RelationItem.TYPE_SUPPLIER.equals(relationType)) {
            final EdsCrmAccount entity = this.crmAccountManager.get(relationID);
            name = entity != null ? entity.getName() : null;
        } else if (RelationItem.TYPE_EMPLOYEE.equals(relationType)) {
            final EdsEmployee entity = this.employeeManager.get(relationID);
            name = entity != null ? entity.getName() : null;
        } else if (RelationItem.TYPE_DEPARTMENT.equals(relationType)) {
            final EdsDepartment entity = this.departmentManager.get(relationID);
            name = entity != null ? entity.getName() : null;
        } else if (RelationItem.TYPE_CASE.equals(relationType)) {
            final EdsCase entity = this.caseManager.get(relationID);
            name = entity != null ? entity.getSubject() : null;
        } else if (RelationItem.TYPE_EVENT.equals(relationType)) {
            final EdsEvent entity = this.eventManager.get(relationID);
            name = entity != null ? entity.getName() : null;
        } else if (RelationItem.TYPE_CONTACT.equals(relationType) || RelationItem.TYPE_LEAD.equals(relationType) || RelationItem.TYPE_CANDIDATE.equals(relationType)) {
            final EdsCrmContact contact = this.crmContactManager.get(relationID);
            name = contact != null ? contact.getFullName() : null;
        } else if (RelationItem.REQUEST_FOR_PURCHASE.equals(relationType)) {
            final EdsRFP rfp = this.rfpManager.get(relationID);
            name = rfp != null ? rfp.getNumber() : null;
        } else if (TYPE_REQUEST_FOR_QUOTE.equals(relationType)) {
            final EdsRFQ rfq = this.rfqManager.get(relationID);
            name = rfq != null ? rfq.getNumber() : null;
        } else if (TYPE_STOCK_ADJUSTMENT.equals(relationType)) {
            EdsStockAdjustment edsStockAdjustment = stockAdjustmentManager.get(relationID);
            name = edsStockAdjustment != null ? edsStockAdjustment.getNumber() : null;
        }
        return name;
    }

