    public HashSet<PermissionHolder> getPermissions(final Integer emailSettingID) {
        final List<EdsUserEmailRbac> emailRbacs = this.userEmailRbacManager.getEmailRbacEntries(emailSettingID);
        final HashSet<PermissionHolder> permissionHolders = new HashSet<>();
        if (emailRbacs != null && emailRbacs.size() > 0) {
            PermissionHolder pHolder;
            for (final EdsUserEmailRbac emailRbac : emailRbacs) {
                pHolder = new PermissionHolder();
                if (EdsTrusteeType.GROUP.equals(emailRbac.getTrusteeType())) {
                    final GroupMembersViewItem groupM = emailRbac.getGroup().getDTO();
                    groupM.setGroupName(this.commonLocalizer.localize(groupM.getGroupConstantName(), groupM.getGroupName()));
                    pHolder.setGroup(groupM);
                }
                if (EdsTrusteeType.USER.equals(emailRbac.getTrusteeType())) {
                    pHolder.setUser(emailRbac.getUser().getDTO());
                }
                permissionHolders.add(pHolder);
            }
        }
        return permissionHolders;
    }


    @Transactional
    public void updateEmailRbacEntries(final UserEmailItem userEmailItem) {
        final EdsEmailSetting edsEmailSetting = this.emailSettingsManager.get(userEmailItem.getId());
        if (edsEmailSetting != null) {
            this.userEmailRbacManager.removeEmailEntries(edsEmailSetting.getObjectID());
            for (final PermissionHolder dto : userEmailItem.getPermissions()) {
                final EdsUserEmailRbac emailRbac = new EdsUserEmailRbac();
                if (dto.getGroup() != null) {
                    emailRbac.setGroup(this.groupManager.get(dto.getGroup().getGroupID()));
                    emailRbac.setTrusteeType(EdsTrusteeType.GROUP);
                } else if (dto.getUser() != null) {
                    emailRbac.setUser(this.userManager.get(dto.getUser().getObjectId()));
                    emailRbac.setTrusteeType(EdsTrusteeType.USER);
                }
                emailRbac.setEmailSetting(edsEmailSetting);
                emailRbac.setRelationship(EdsRelationship.EMAIL_VIEWER);
                this.userEmailRbacManager.create(emailRbac);
            }
        }
    }

    @Override
    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public HashMap<Integer, ArrayList<RelationItem>> getRelations(final String relationType,
                                                                  final ArrayList<Integer> relationIDs) {
        final HashMap<Integer, ArrayList<RelationItem>> map = new HashMap<>();
        final ArrayList<RelationItem> result = EdsRelation.wrapToRPCs(this.relationManager.getAllRelations(relationType, relationIDs));
        if (result != null && result.size() > 0) {
            for (final RelationItem relationItem : result) {
                final Integer key = relationItem.getIDByType(relationType);
                if (key != null) {
                    if (!map.containsKey(key)) {
                        map.put(key, new ArrayList<>());
                    }
                    map.get(key).add(relationItem);
                }
            }
        }
        return map;
    }

