    @Override
    @Transactional
    public Integer saveReference(final ReferenceItem item, final ArrayList<ReferenceItem> children,
                                 final boolean isChild) {
        EdsReference parent = null;
        boolean isNew = false;

        if (item != null) {
            final String code = (item.getName().trim().replaceAll(" +", " ").replace(" ", "_")).toUpperCase();

            final EdsReference reference = item.getId() != null ? this.referenceManager.getOriginal(item.getId()) : new EdsReference();
            //create customer the custom field which will be used in the workflow
            if (reference.isNew()) {
                reference.setCode(code);
                if (item.isLeaveToAll()) {
                    this.createNewWorkflowField(code);
                }
                if (item.getParentID() != null) {
                    parent = this.referenceManager.get(item.getParentID());
                } else if (item.getParent() != null) {
                    parent = this.referenceManager.getByCode(item.getParent());
                    reference.setParent(parent);
                }
            } else if (isChild && reference.isSystemReference() && item.isSelected()) {
                reference.setChanged(true);
            }

            if (isChild && item.getObjectID() == null) {
                isNew = true;
                if (item.getCode() == null && parent != null && parent.getCode() != null) {
                    final Integer parentsChildrenCount = this.referenceManager.listReferences(parent.getCode()).size();
                    item.setCode(item.getName() + "|" + parent.getCode() + "_" + parentsChildrenCount);
                }
                final EdsReference r = parent != null ? this.referenceManager.findReference(parent.getCode(), item.getCode()) : this.referenceManager.findReferenceByCode(item.getCode());
                if (r != null) {
                    item.setCode(r.getName() + "|" + r.getCode() + "_" + 1);
                }
                reference.setCode(item.getName());
                reference.setParent(parent);
            }
            reference.setCssStyle(item.getCssStyle());
            reference.setName(item.getName());
            reference.setDescription(item.getDescription());
            reference.setAntonym(item.getAntonym());
            reference.setSorder(item.getOrder());
            reference.setLeaveDays(item.getLeaveDays());
            reference.setDeleted(false);
            reference.setIncludeDayOffs(item.isIncludeDayOffs());
            reference.setIncludeHolidays(item.isIncludeHolidays());
            reference.setShortName(item.getShortName());
            reference.setRequiredComment(item.isRequiredComment());
            reference.setColor(item.getColorHex());
            if (!StringUtils.isEmpty(item.getColorHex())) {
                EdsReferenceColor color = item.getColorId() != null ? this.referenceColorManager.get(item.getColorId()) : this.referenceColorManager.getByHex(item.getColorHex());
                if (color == null) {
                    color = new EdsReferenceColor();
                    color.setHex(item.getColorHex());
                    referenceColorManager.create(color);
                }
                reference.setReferenceColorId(color.getObjectID());
            } else {
                reference.setReferenceColorId(null);
            }
            reference.setUpdatedDate(new Date());
            reference.setUpdater(userManager.getUser() != null ? userManager.getUser().getObjectID() : null);
            reference.setAttendanceLR(item.isAttendanceLR());
            reference.setAutoApprove(item.isAutoApprove());

            //Create Reference
            this.referenceManager.createOrUpdate(reference);
            if (isNew) {
                saveReferenceLocale(reference.getObjectID(), null);
            }

            if (!isChild) {
                this.referenceManager.deleteChildren(reference);
            }
            if (children != null && children.size() > 0) {
                for (final ReferenceItem referenceItem : children) {
                    if (referenceItem.getParentID() == null) {
                        referenceItem.setParentID(reference.getObjectID());
                    }
                    this.saveReference(referenceItem, null, true);
                }
            }

            return reference.getObjectID();
        }
        return null;
    }

    private void createNewWorkflowField(final String code) {
        EdsModelField field = this.modelFieldManager.getWorkflowField(LayoutRPC.HRMS_EMPLOYEE_FORM, code, CustomFormConstants.EMPLOYMENT_INFORMATION, false);
        if (field == null) {
            field = new EdsModelFieldCustom();
            field.setForm_ID(LayoutRPC.HRMS_EMPLOYEE_FORM);
            field.setField_ID(code);
            field.setFsection(CustomFormConstants.EMPLOYMENT_INFORMATION);
            field.setWidget(Constants.UI_TYPE_TEXTBOX);
            field.setSource(null);
            field.setUsableByWorkflow(true);
            field.setType(Constants.DATA_TYPE_NUMBER);
            this.modelFieldManager.createOrUpdate(field);
        }
    }

    private void removeWorkflowField(final String code) {
        final EdsModelField field = this.modelFieldManager.getWorkflowField(LayoutRPC.HRMS_EMPLOYEE_FORM, code, CustomFormConstants.EMPLOYMENT_INFORMATION, false);
        if (field != null) {
            this.modelFieldManager.delete(field);
        }
    }

    @Override
    public void deleteReference(final Integer objectId) {
        if (objectId != null) {
            final EdsReference reference = this.referenceManager.get(objectId);
            if (reference != null && !reference.isSystemReference()) {
                reference.setDeleted(true);
                reference.setUpdatedDate(new Date());
                reference.setUpdater(userManager.getUser() != null ? userManager.getUser().getObjectID() : null);
                this.referenceManager.update(reference);
                this.removeWorkflowField(reference.getCode());
            }
        }
    }

    public ListResult<ReferenceItem> getReferenceList(final ListingFilterParameter filterParameter) {
        if (filterParameter.getColumnCode() != null) {
            final EdsReference parentReference = this.referenceManager.getByCode(filterParameter.getColumnCode());
            filterParameter.setParentID(parentReference.getObjectID());
        }
        final ArrayList<ReferenceItem> items = this.referenceManager.listReferences(filterParameter).stream().map(EdsReference::getRPC).collect(Collectors.toCollection(ArrayList::new));
        final int totalCount = this.referenceManager.countReferences(filterParameter);
        return new ListResult<>(items, totalCount);
    }

