    @Override
    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public HashMap<String, Integer> findIDsBy(final ListingFilterParameter fp) {
        final HashMap<String, Integer> ids = new HashMap<>();
        if (fp.getOpportunityID() != null) {
            final EdsOpportunity opportunity = this.opportunityManager.get(fp.getOpportunityID());
            if (opportunity != null) {
                if (opportunity.getCrmAccount() != null) {
                    ids.put(LookUpConstants.CRM_ACCOUNT, opportunity.getCrmAccount().getObjectID());
                }
                if (opportunity.getCrmContact() != null) {
                    ids.put(LookUpConstants.CRM_CONTACT, opportunity.getCrmContact().getObjectID());
                }
                return ids;
            }
        }
        if (fp.getCrmContactId() != null) {
            final EdsCrmContact contact = this.crmContactManager.get(fp.getCrmContactId());
            if (contact != null) {
                if (contact.getCrmAccount() != null) {
                    ids.put(LookUpConstants.CRM_ACCOUNT, contact.getCrmAccount().getObjectID());
                }
            }
            return ids;
        }
        return ids;
    }

