    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public SelectItem[] getAccountTreeLookUpItems(ListingFilterParameter fp, final String treeLevel) {
        if (fp == null) {
            fp = new ListingFilterParameter();
        }
        fp.setLimit(20);

        final List<EdsCrmAccount> accounts = this.crmAccountManager.getAccountTreeLookUpItems(fp, treeLevel);
        if (accounts != null) {
            final SelectItem[] result = new SelectItem[accounts.size()];

            int index = 0;
            for (final EdsCrmAccount crmAccount : accounts) {
                result[index] = new SelectItem(crmAccount.getObjectID(), crmAccount.getName());

                index++;
            }

            return result;
        }

        return null;
    }

    @Override
    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public SelectItem[] getParentAccountsTreeList(final Integer objectID) {
        final List<SelectItem> list = new ArrayList<>();
        final EdsCrmAccount account = this.crmAccountManager.get(objectID);

        if (account.getParent() != null) {
            this.generateParentAccountTreeByRecur(account.getParent(), list);
        }

        if (list.size() > 0) {
            int index = list.size() - 1;
            final SelectItem[] items = new SelectItem[list.size()];
            for (final SelectItem item : list) {
                items[index] = item;
                index--;
            }

            return items;
        }

        return new SelectItem[0];
    }

    private void generateParentAccountTreeByRecur(final EdsCrmAccount parent, final List<SelectItem> list) {
        list.add(new SelectItem(parent.getObjectID(), parent.getName()));

        if (parent.getParent() != null) {
            this.generateParentAccountTreeByRecur(parent.getParent(), list);
        }
    }

