    @Override
    public Integer saveGoogleGadgetMail(final Email email) {
        if (email != null && email.getGeneratedGoogleID() != 0) {
            EdsEmail edsEmail = this.emailRepository.findByGeneratedGoogleID(email.getGeneratedGoogleID(), ServerSecurityContext.getInstance().getCompanyId());
            if (edsEmail == null) {
                edsEmail = new EdsEmail();
                edsEmail.setCompanyId(ServerSecurityContext.getInstance().getCompanyId());
                edsEmail.setSubject(email.getSubject());
                edsEmail.setFetched(false);
                edsEmail.setDescription(email.getContent());
                edsEmail.setGeneratedGoogleID(email.getGeneratedGoogleID());
                edsEmail.setFrom(email.getFromEmail());
                edsEmail.setTo(email.getToEmails());
                edsEmail.setCreatedDate(new Date());
                final EdsEmailTracker tracker = this.emailTrackerService.createTracker(null);
                if (tracker != null) {
                    edsEmail.setTrackerId(tracker.getObjectID());
                }
                this.emailRepository.save(edsEmail);
            }
            return edsEmail.getTrackerId();
        }
        return null;
    }

