    @Override
    public SelectItem convertEmailTo(final String emailID, final String relationType) {
        Optional<EdsEmail> emailOptional = emailRepository.findById(emailID);
        if (emailOptional.isPresent()) {
            EdsEmail email = emailOptional.get();
            if (RelationItem.TYPE_CASE.equals(relationType)) {
                email.setIgnoreFilters(true);
                return new SelectItem(this.convertEmailToCase(email), RelationItem.TYPE_CASE);
            } else if (RelationItem.TYPE_LEAD.equals(relationType)) {
                return this.convertEmailToLead(email);
            }
        }
        return null;
    }

    private SelectItem convertEmailToLead(final EdsEmail email) {
        final SelectItem item = new SelectItem();
        final Integer companyID = SecurityContext.getCompanyID();
        String from = email.getFrom();
        String fullName = "";
        if (from != null && from.contains("<") && from.contains(">")) {
            fullName = from.substring(0, from.indexOf("<"));
            final int start = from.indexOf("<") + 1;
            final int end = from.indexOf(">", start + 1);
            from = from.substring(start, end);
        }
        final EdsCrmContact crmContact = this.crmContactManager.getContactByEmail(from, companyID);
        final EdsEmailTracker emailTracker = this.emailTrackerManager.get(email.getTrackerId());
        if (crmContact == null) {
            EdsCrmContact lead = this.crmContactManager.getLeadByEmail(from, companyID);
            if (lead == null) {
                final EdsCrmAccount crmAccount = this.crmAccountManager.getCrmAccountByEmail(from, companyID);
                if (crmAccount == null) {
                    lead = new EdsCrmContact();
                    final ContactListItem leadRPC = new ContactListItem();
                    leadRPC.getHomeEmail().add(from);
                    if (!"".equals(fullName.trim())) {
                        if (fullName.contains(" ")) {
                            leadRPC.setFirstName(fullName.substring(0, fullName.indexOf(" ")));
                            leadRPC.setLastName(fullName.substring(fullName.indexOf(" ") + 1));
                        } else if (from.contains("@")) {
                            leadRPC.setLastName(from.substring(0, from.indexOf("@")));
                        } else {
                            leadRPC.setLastName(fullName);
                        }
                    }
                    leadRPC.addTrackerId(email.getTrackerId());
                    final Integer leadID = this.crmServiceLocal.saveLead(leadRPC, null);
                    if (emailTracker != null) {
                        emailTracker.setContactId(leadID);
                    }
                    item.setId(leadID);
                    item.setName(RelationItem.TYPE_LEAD);
                    item.setDefaultSelected(true);
                } else {
                    item.setId(crmAccount.getObjectID());
                    item.setName(RelationItem.TYPE_CRM_ACCOUNT);
                }
            } else {
                if (emailTracker != null) {
                    emailTracker.setContactId(lead.getObjectID());
                    lead.addTracker(emailTracker);
                }
                item.setId(lead.getObjectID());
                item.setName(RelationItem.TYPE_LEAD);
            }
        } else {
            if (emailTracker != null) {
                emailTracker.setContactId(crmContact.getObjectID());
                crmContact.addTracker(emailTracker);
            }
            item.setId(crmContact.getObjectID());
            item.setName(RelationItem.TYPE_CONTACT);
        }
        final ArrayList<RelationItem> relations = new ArrayList<>();
        relations.add(new RelationItem(null, email.getTrackerId(), RelationItem.TYPE_EMAIL_TRACKER, email.getSubject(), null, item.getName(), fullName));
        this.saveRelations(item.getName(), item.getId(), fullName, relations);
        return item;
    }

    private Integer convertEmailToCase(final EdsEmail email) {
        EdsCase crmCase = this.caseManager.getCaseByTrackerID(email.getTrackerId());
        if (crmCase != null) {
            if (crmCase.getDeleted() != null && crmCase.getDeleted()) {
                crmCase.setDeleted(false);
                crmCase.setAuditInfo(crmCase.getAuditInfo() == null ? new EdsAuditInfo() : crmCase.getAuditInfo());
                crmCase.getAuditInfo().setModifiedBy(this.caseManager.getUser());
                crmCase.getAuditInfo().setModificationDate(new Date());
                crmCase.setStatus(this.referenceManager.findReference(EdsCase._CASE_STATUS, EdsCase.WAITING_FOR_REPLY));
                this.caseManager.update(crmCase, true);
            }
            return crmCase.getObjectID();
        }
        final List<EdsEmail> messages = new ArrayList<>();
        messages.add(email);
        Map<Boolean, List<Integer>> solrIDsToUpdate = this.crmServiceLocal.convertEmailToCase(messages);

        final List<Integer> ids = new ArrayList<>();
        if (!solrIDsToUpdate.get(Boolean.TRUE).isEmpty()) {
            ids.addAll(solrIDsToUpdate.get(Boolean.TRUE));
            if (!ids.isEmpty()) {
                final String idsString = ServerUtils.getAsCommoDelimited(ids, "0", ",");
                crmCase = new EdsCase();
                crmCase.setObjectID(ids.get(0));
                final EdsBusinessEvent solrEvent = this.baseEventPostProcessor.registerEvent(CrmCaseEventListeneImpl.TYPE, BaseEventsPostProcessorImpl.EVENT_TYPE_ADD, crmCase, this.userManager.getUser());
                solrEvent.setCustomStringField(idsString);
                final EdsEmailSetting s = new EdsEmailSetting();
                s.setObjectID(email.getEmailSettingId());
                final EdsBusinessEvent autoResponseEvent = this.baseEventPostProcessor.registerEvent(EmailFetchingCustomEventListenerImpl.TYPE_EMAIL_FETCHING, EmailFetchingCustomEventListenerImpl.EVENT_SEND_AUTORESPONSE, s, this.userManager.getUser());
                autoResponseEvent.setCustomStringField(idsString);
            }
        }
        if (!solrIDsToUpdate.get(Boolean.FALSE).isEmpty()) {
            ids.addAll(solrIDsToUpdate.get(Boolean.FALSE));
        }
        if (!ids.isEmpty()) {
            final List<EdsCase> cases = this.caseManager.getCasesByIDs(ids);
            if (cases != null && !cases.isEmpty()) {
                try {
                    caseSolrComponent.indexes(cases);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }
            return ids.get(0);
        }
        return null;
    }

