    @Override
    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public boolean checkCrmAccountRelations(final Integer accountID, final String accountType) {

        if (EdsCrmAccount.CUSTOMER.equals(accountType)) {
            final List<EdsSaleQuote> listQuote = this.quoteManager.getUnDeletedSaleQuotesByCrmAccountID(accountID);
            if (listQuote != null && listQuote.size() > 0) {
                return true;
            }
            final List<EdsSaleInvoice> listInvoice = this.invoiceManager.getUnDeleteSaleInvoicesByCrmAccountID(accountID);
            if (listInvoice != null && listInvoice.size() > 0) {
                return true;
            }
            final List<EdsInvoicePayment> prePaymentList = this.invoicePaymentManager.getAccountPrePayments(accountID, AccountingConstants.RECEIVABLE_PREPAYMENT);
            if (prePaymentList != null && prePaymentList.size() > 0) {
                return true;
            }

        } else if (EdsCrmAccount.SUPPLIER.equals(accountType)) {
            final List<EdsPurchaseInvoice> purchaseInvoiceList = this.invoiceManager.getUndeletedPurchaseInvoicesByCrmAccountID(accountID);
            if (purchaseInvoiceList != null && purchaseInvoiceList.size() > 0) {
                return true;
            }
            final List<EdsPurchaseOrder> purchaseOrderList = this.quoteManager.getUnDeletedPurchaseOrdersByCrmAccountID(accountID);
            if (purchaseOrderList != null && purchaseOrderList.size() > 0) {
                return true;
            }
            final List<EdsBankCheckItem> checkItemList = this.bankCheckManager.getBankCheckItemsBySupplier(accountID, null);
            if (checkItemList != null && checkItemList.size() > 0) {
                return true;
            }
        }
        final List<TransactionAllocateItem> manualTransactionList = this.manualJournalManager.getManualTransactionsByCrmAccount(accountID, accountType);
        return manualTransactionList != null && manualTransactionList.size() > 0;
    }

