    public PositionsSelectItem getPositionItems(final Integer positionId) {
        final PositionsSelectItem item = new PositionsSelectItem();
        if (positionId != null) {
            final EdsPosition pos = this.positionManager.getPositionForEdit(positionId);

            if (pos.getLocation() != null) {
                item.setLocation(new SelectItem(pos.getLocation().getObjectID(), pos.getLocation().getName()));
            }
            if (pos.getDepartment() != null) {
                final EdsDepartment department = this.departmentManager.get(pos.getDepartment());
                item.setDepartment(department != null ? new SelectItem(pos.getDepartment(), department.getNumberData() != null ? department.getNumberData() + "-> " + department.getName() : department.getName()) : null);
            }
            if (pos.getCount() != null) {
                item.setPlannedPlaceCount(pos.getCount());
            }
            final List<EdsEmployee> employeeList = this.employeeManager.getPositionEmployees(pos);
            if (employeeList != null) {
                item.setHeadCount(String.valueOf(employeeList.size()));
            }
        }
        return item;
    }

