    @Override
    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public ListResult<ReferenceItem> getDeletableReferences(final ListingFilterParameter fp) {
        final ArrayList<ReferenceItem> list = new ArrayList<>();
        if (fp.getColumnCode() == null) {
            fp.setExcludedType(EdsSickRequest._LEAVE_REQUEST_TYPE);
        }
        final ListResult<ReferenceItem> referenceList = this.getReferenceList(fp);
        if (referenceList != null && referenceList.getList().size() > 0) {
            for (final ReferenceItem item : referenceList.getList()) {
                item.setCanDelete(!item.isSystemReference());
                list.add(item);
            }
            return new ListResult<>(list, this.referenceManager.countReferences(fp));
        }
        return new ListResult<>(new ArrayList<>(), 0);
    }

