    @Override
    public SpokenLanguageTO getLanguagesWithLevels() {
        final SpokenLanguageTO result = new SpokenLanguageTO();
        final List<EdsReference> languages = this.referenceManager.listReferences(EdsSpokenLanguages.LANGUAGE);
        if (languages != null && !languages.isEmpty()) {
            for (final EdsReference l : languages) {
                result.getLanguages().add(new SelectItem(l.getObjectID(), this.referenceWfmMessageSource.localize(l.getCode(), l.getName()), l.getDescription()));
            }
        }
        final List<EdsReference> languageLevels = this.referenceManager.listReferences(EdsSpokenLanguages.LANGUAGE_LEVELS);
        if (languageLevels != null && !languageLevels.isEmpty()) {
            for (final EdsReference l : languageLevels) {
                if (l.getLocale() != null) {
                    String lang = ServerUtils.getUserLocale().getLanguage();
                    if (org.apache.commons.lang.StringUtils.isNotBlank(l.getLocale().getLocaleByCode(lang))) {
                        result.getLanguageLevels().add(new SelectItem(l.getObjectID(), l.getLocale().getLocaleByCode(lang), l.getDescription()));
                    }
                } else {
                    result.getLanguageLevels().add(new SelectItem(l.getObjectID(), l.getName(), l.getDescription()));
                }
            }
        }
        return result;
    }


