    @Override
    @Transactional
    public void deleteReason(final Integer objectId) {
        if (objectId != null) {
            final EdsLeaveReason reason = this.leaveReasonManager.get(objectId);
            if (reason != null && !reason.isSystemReference()) {
                if (reason.getLocale() != null) {
                    referenceLocaleManager.delete(reason.getLocale());
                    reason.setLocale(null);
                }
                reason.setDeleted(true);
                this.leaveReasonManager.update(reason);
                this.leaveReasonRelationManager.deleteRelations(reason.getCode());

                if (StringUtils.isBlank(reason.getCode())) {
                    return;
                }
                this.removeWorkflowField(reason.getCode());
            }
        }
    }

    @Override
    @Transactional(readOnly = true, propagation = Propagation.SUPPORTS)
    public ListResult<ReasonItem> getReasonItems(final ListingFilterParameter fp) {

        final ArrayList<EdsLeaveReason> items = this.leaveReasonManager.listLeaveReasons(fp);

        final ArrayList<ReasonItem> list = items.stream()
                .map(EdsLeaveReason::toRPC)
                .collect(Collectors.toCollection(ArrayList::new));

        final int totalCount = this.leaveReasonManager.countReasons(fp);

        return new ListResult<>(list, totalCount);
    }

    @Override
    @Transactional(readOnly = true, propagation = Propagation.SUPPORTS)
    public ArrayList<ReasonItem> getReasonItemsByReasonId(Integer reasonID) {
        ArrayList<ReasonItem> itemList = new ArrayList<>();
        List<EdsLeaveReasonHistory> historyList = this.leaveReasonHistoryManager.leaveReasonHistoryListByReasonId(reasonID);
        for (EdsLeaveReasonHistory history : historyList) {
            ReasonItem item = new ReasonItem();
            item.setId(history.getObjectID());
            item.setLeaveDaysNew(history.getLeaveDaysNew());
            item.setEffectiveDate(ServerUtils.shortDateFormat(history.getEffectiveDate(), companyManager.get(Integer.valueOf(ServerSecurityContext.getInstance().getCompanyId())), true));
            if (history.getModifiedBy() != null) {
                item.setModifiedBy(history.getModifiedBy().getFullName());
            }
            itemList.add(item);
        }
        return itemList;
    }

    @Override
    @Transactional(readOnly = true, propagation = Propagation.SUPPORTS)
    public ReasonItem getReason(final Integer objectID) {
        if (objectID == null) {
            return null;
        }
        ReasonItem item = null;
        final EdsLeaveReason reason = this.leaveReasonManager.get(objectID);
        if (reason != null) {
            final EdsLeaveReasonHistory reasonHistory = this.leaveReasonHistoryManager.leaveReasonHistoryByReasonCode(reason.getCode(), null);
            item = reason.toRPC();
            if (reasonHistory != null) {
                item.setMinLeaveDays(reasonHistory.getMinLeaveDays());
                item.setModifiedBy(reasonHistory.getModifiedBy().getFullName());
                item.setEffectiveFrom(new DateNonConvertable(reasonHistory.getEffectiveDate()));
            }
            if (CustomFormConstants.LR_TYPE_ANNUAL_LEAVE.equals(reason.getCode())) {
                final EdsHRSettings hrSettings = this.hrSettingsManager.findOne();
                if (hrSettings != null && hrSettings.getOpeningBalanceDate() != null) {
                    item.setOpeningBalanceDate(new DateNonConvertable(hrSettings.getOpeningBalanceDate()));
                }
            }
            final List<EdsLeaveReasonRelation> relations = this.leaveReasonRelationManager.getRelations(reason.getCode());
            final List<LeaveReasonLocationDaysItem> locationDaysList = new ArrayList<>();
            for (EdsLeaveReasonRelation rel : relations) {
                if (LeaveReasonType.LOCATION.equals(rel.getRelatedType()) && rel.getLeaveDays() != null) {
                    final LeaveReasonLocationDaysItem ldItem = new LeaveReasonLocationDaysItem();
                    ldItem.setLocationId(rel.getRelationId());
                    ldItem.setLeaveDays(rel.getLeaveDays());
                    ldItem.setApplyToAll(rel.getApplyToAll());
                    if (rel.getEffectiveDate() != null) {
                        ldItem.setEffectiveFrom(new DateNonConvertable(rel.getEffectiveDate()));
                    }
                    final EdsLocation location = this.locationManager.get(rel.getRelationId());
                    if (location != null) {
                        ldItem.setLocationName(location.getName());
                    }
                    locationDaysList.add(ldItem);
                }
            }
            if (!locationDaysList.isEmpty()) {
                item.setLocationDaysList(locationDaysList);
            }
        }
        return item;
    }

    public void deleteLeaveReasonHistoryById(Integer reasonID) {
        this.leaveReasonHistoryManager.deleteLeaveReasonHistoryById(reasonID);
    }

    @Override
    @Transactional
    public Integer saveLeaveReason(final ReasonItem item) {
        final EdsLeaveReason reason;
        if (item == null) {
            return null;
        }
        String code = item.getCode();
        if (item.getId() == null) {
            final String name = item.getName().trim().toLowerCase().replaceAll(" +", " ");
            code = name.replace(" ", "_").toUpperCase();
            EdsLeaveReason reasonByName = this.leaveReasonManager.getReasonByName(name, code);
            if (reasonByName != null) {
                return ReasonItem.NAME_EXISTS;
            } else if (StringUtils.isNotBlank(item.getShortName())) {
                reasonByName = this.leaveReasonManager.getReasonByShortName(item.getShortName().toLowerCase());
                if (reasonByName != null) {
                    return ReasonItem.SHORT_NAME_EXISTS;
                }
            }
            reason = new EdsLeaveReason();
        } else {
            reason = this.leaveReasonManager.get(item.getId());
            this.leaveReasonRelationManager.deleteRelations(reason.getCode());
        }

        if (item.getId() != null && !Objects.equals(reason.getName(), item.getName())) {
            final EdsBusinessEvent businessEvent = this.baseEventPostProcessor.registerEvent(LeaveRequestEventListenerImpl.TYPE, LeaveRequestEventListenerImpl.LEAVE_REQUEST_REINDEX, null, this.userManager.getUser());
            businessEvent.setEntityType(LayoutRPC.LEAVE_REASON_FORM);
            businessEvent.setSourceID(reason.getObjectID());
        }

        reason.setName(item.getName());
        reason.setCode(code);
        reason.setDescription(item.getDescription());
        reason.setActive(item.isActive());
        reason.setProbationDays(item.getProbationDays());
        reason.setLeaveDays(item.getLeaveDaysNew());
        reason.setDeleted(false);
        reason.setIncludeDayOffs(item.isIncludeDayOffs());
        reason.setExceptionalTimeslot(item.isExceptionalWorkingDay());
        reason.setIncludeHolidays(item.isIncludeHolidays());
        reason.setShortName(item.getShortName());
        reason.setUpdatedDate(new Date());
        reason.setAttendanceLR(item.isAttendanceLR());
        reason.setAutoApprove(item.isAutoApprove());
        reason.setHasProrata(item.isHasProrata());
        reason.setGender(item.getGender());
        reason.setUnitType(item.getUnitType());
        reason.setTypeOption(item.getTypeOption());
        reason.setColor(item.getHexColor());
        reason.setDuration(item.getDuration());
        reason.setIntegrationCode(item.getIntegrationCode());
        reason.setRedirectUrl(item.getRedirectUrl());
        reason.setMarkAsDraft(item.isMarkAsDraft());
        if (item.getReferenceLocale() != null && checkReferenceLocale(item.getReferenceLocale())) {
            reason.setLocale(saveEntityLocale(item.getReferenceLocale()));
        }
        EdsLeaveReasonHistory leaveReasonHistory = new EdsLeaveReasonHistory();
        if (reason.getLeaveDays() != null) {
            leaveReasonHistory.setLeaveDaysOld(reason.getLeaveDays());
        }
        reason.setMinLeaveDays(item.getMinLeaveDays() != null ? item.getMinLeaveDays() : 0);
        leaveReasonHistory.setLeaveDaysNew(item.getLeaveDaysNew());
        leaveReasonHistory.setReasonCode(item.getCode());
        leaveReasonHistory.setEffectiveDate(item.getEffectiveFrom().getDate());
        leaveReasonHistory.setModifiedDate(new Date());
        leaveReasonHistory.setModifiedBy((EdsUser) ServerSecurityContext.getInstance().getUser());
        leaveReasonHistory.setMinLeaveDays(item.getMinLeaveDays() != null ? item.getMinLeaveDays() : 0);
        if (item.isLeaveToAll() && reason.getLeaveDays() != null) {
            final List<EdsEmployee> employees = this.employeeManager.list(new ListingFilterParameter());
            for (final EdsEmployee employee : employees) {
                this.availabilityService.createOrUpdateLeaveAllowance(employee.getObjectID(), reason, item.getEffectiveFrom().getDate());
            }
            if ("LR_TYPE_ANNUAL_LEAVE".equals(reason.getDescription())) {
                labourPeriodManager.updatePeriods(reason.getLeaveDays());
            }
        }

        if (item.isProbationToAll() && item.getProbationDays() != null) {
            this.employeeManager.setProbationDaystoAllEmployees(item.getProbationDays());
        }

        if (CustomFormConstants.LR_TYPE_ANNUAL_LEAVE.equals(reason.getCode())) {
            EdsHRSettings edsHRSettings = this.hrSettingsManager.findOne();
            if (edsHRSettings == null) {
                edsHRSettings = new EdsHRSettings();
            }
            if (item.getOpeningBalanceDate() != null) {
                edsHRSettings.setOpeningBalanceDate(item.getOpeningBalanceDate().getNonConvertedDate());
            } else {
                edsHRSettings.setOpeningBalanceDate(null);
            }
            this.hrSettingsManager.createOrUpdate(edsHRSettings);
        }

        this.leaveReasonManager.createOrUpdate(reason);
        leaveReasonHistory.setReason(reason);
        leaveReasonHistoryManager.create(leaveReasonHistory);

        final Map<Integer, LeaveReasonLocationDaysItem> locationDaysMap = new HashMap<>();
        if (item.getLocationDaysList() != null) {
            for (LeaveReasonLocationDaysItem ldItem : item.getLocationDaysList()) {
                if (ldItem.getLocationId() != null) {
                    locationDaysMap.put(ldItem.getLocationId(), ldItem);
                }
            }
        }

        if (item.getRelationMap() != null && item.getRelationMap().size() > 0) {
            item.getRelationMap().forEach((type, value) ->
                    value.forEach(select -> {
                        final EdsLeaveReasonRelation relation = new EdsLeaveReasonRelation();
                        relation.setReasonCode(reason.getCode());
                        relation.setRelatedType(type);
                        relation.setRelationId(select.getId());
                        if (LeaveReasonType.LOCATION.equals(type)) {
                            final LeaveReasonLocationDaysItem ldItem = locationDaysMap.remove(select.getId());
                            if (ldItem != null) {
                                relation.setLeaveDays(ldItem.getLeaveDays());
                                relation.setApplyToAll(ldItem.isApplyToAll());
                                relation.setEffectiveDate(ldItem.getEffectiveFrom() != null
                                        ? ldItem.getEffectiveFrom().getDate()
                                        : item.getEffectiveFrom().getDate());
                            }
                        }
                        this.leaveReasonRelationManager.create(relation);
                    })
            );
        }

        // location-days rows whose location was not in the "applicable for" list still need a relation record
        for (LeaveReasonLocationDaysItem ldItem : locationDaysMap.values()) {
            if (ldItem.getLocationId() == null) {
                continue;
            }
            final EdsLeaveReasonRelation relation = new EdsLeaveReasonRelation();
            relation.setReasonCode(reason.getCode());
            relation.setRelatedType(LeaveReasonType.LOCATION);
            relation.setRelationId(ldItem.getLocationId());
            relation.setLeaveDays(ldItem.getLeaveDays());
            relation.setApplyToAll(ldItem.isApplyToAll());
            relation.setEffectiveDate(ldItem.getEffectiveFrom() != null
                    ? ldItem.getEffectiveFrom().getDate()
                    : item.getEffectiveFrom().getDate());
            this.leaveReasonRelationManager.create(relation);
        }

        if (item.getLocationDaysList() != null) {
            for (LeaveReasonLocationDaysItem ldItem : item.getLocationDaysList()) {
                if (ldItem.getLeaveDays() == null || !ldItem.isApplyToAll()) {
                    continue;
                }
                final ListingFilterParameter locationFp = new ListingFilterParameter();
                locationFp.setLocationId(ldItem.getLocationId());
                final List<EdsEmployee> locationEmployees = this.employeeManager.list(locationFp);
                final Date effectiveDate = ldItem.getEffectiveFrom() != null
                        ? ldItem.getEffectiveFrom().getDate()
                        : item.getEffectiveFrom().getDate();
                for (final EdsEmployee employee : locationEmployees) {
                    this.availabilityService.createOrUpdateLeaveAllowanceWithDays(
                            employee.getObjectID(), reason, effectiveDate, ldItem.getLeaveDays());
                }
            }
        }

        return reason.getObjectID();
    }

    private boolean checkReferenceLocale(ReferenceLocale referenceLocale) {
        return (referenceLocale.getUzbek() != null ||
                referenceLocale.getRussian() != null ||
                referenceLocale.getEnglish() != null ||
                referenceLocale.getArabic() != null);
    }

    @Override
    public HashMap<LeaveReasonType, ArrayList<SelectItem>> getSelectOptions(final Integer reasonId) {
        final HashMap<LeaveReasonType, ArrayList<Integer>> map = new HashMap<>();
        final EdsLeaveReason reason = this.leaveReasonManager.get(reasonId);
        if (reasonId != null) {
            final List<EdsLeaveReasonRelation> relations = this.leaveReasonRelationManager.getRelations(reason.getCode());
            if (!CollectionUtils.isEmpty(relations)) {
                relations.stream()
                        .filter(Objects::nonNull)
                        .forEach(relation ->
                                map.computeIfAbsent(relation.getRelatedType(), value -> new ArrayList<>())
                                        .add(relation.getRelationId()));
            }
        }
        final HashMap<LeaveReasonType, ArrayList<SelectItem>> resultMap = new HashMap<>();
        final ListingFilterParameter fp = new ListingFilterParameter();

        {//department list
            EdsUser user = employeeManager.getUser();
            if (fp.getViewAsId() == null) {
                EdsRole maximumRole = user.getRolesSortedByPattern().get(0);
                fp.setViewAsId(maximumRole.getObjectID());
            }
            final List<EdsDepartment> departments = this.departmentManager.list(fp);
            final List<Integer> selectedDepartmentIds = map.get(LeaveReasonType.DEPARTMENT) != null ? map.get(LeaveReasonType.DEPARTMENT) : new ArrayList<>();
            resultMap.put(LeaveReasonType.DEPARTMENT, this.getSelectedItems(departments, selectedDepartmentIds));
        }

        {//position list
            final List<EdsPosition> positionList = this.positionManager.list();
            final List<Integer> selectedPositiontIds = map.get(LeaveReasonType.POSITION) != null ? map.get(LeaveReasonType.POSITION) : new ArrayList<>();
            resultMap.put(LeaveReasonType.POSITION, this.getSelectedItems(positionList, selectedPositiontIds));
        }

        {
            final List<EdsLocation> locationList = this.locationManager.list(new ListingFilterParameter());
            final List<Integer> selectedLocationIds = map.get(LeaveReasonType.LOCATION) != null ? map.get(LeaveReasonType.LOCATION) : new ArrayList<>();
            resultMap.put(LeaveReasonType.LOCATION, this.getSelectedItems(locationList, selectedLocationIds));
        }

        {//role list
            final List<EdsRole> roleList = this.roleManager.list();
            final List<Integer> selectedRoleIds = map.get(LeaveReasonType.ROLE) != null ? map.get(LeaveReasonType.ROLE) : new ArrayList<>();
            resultMap.put(LeaveReasonType.ROLE, this.getSelectedItems(roleList, selectedRoleIds));
        }

        {//employee list
            final ArrayList<SelectItem> employeeSelect = new ArrayList<>();
            if (map.get(LeaveReasonType.EMPLOYEE) != null) {
                map.get(LeaveReasonType.EMPLOYEE).forEach(id -> {
                    final EdsEmployee employee = this.employeeManager.get(id);
                    employeeSelect.add(new SelectItem(employee.getObjectID(), employee.getName()));
                });
            }
            resultMap.put(LeaveReasonType.EMPLOYEE, employeeSelect);
        }

        return resultMap;
    }

    @Override
    public ListResult<WorkflowRule> getWorkflowActivitiesList(final ListingFilterParameter fp) {
        final ArrayList<WorkflowRule> results = new ArrayList<>();
        final int totalCount = this.workflowRuleManager.getActivitiesListCount();
        if (totalCount > 0) {
            final List<Object[]> activities = this.workflowRuleManager.getListForActivities(fp);
            for (final Object[] item : activities) {
                final WorkflowRule result = new WorkflowRule();
                if (item[1] != null) {
                    result.setObjectID((Integer) item[0]);
                    result.setEntityId((Integer) item[1]);
                    result.setName((String) item[2]);
                    result.setExecutionDate((Date) item[3]);
                    result.setExecutionCriteria(WorkflowExecutionCriteriaEnum.valueOf((String) item[4]));
                    result.setModule((String) item[5]);
                    Integer relationID = null;
                    if (item.length > 11 && item[11] != null) {
                        final String[] params = ((String) item[11]).split(",");
                        relationID = Integer.valueOf(params[4]);
                    }
                    if (relationID != null) {
                        switch (result.getModule()) {
                            case WorkflowRule._WORKFLOW_MODULE_LEAD -> {
                                final EdsCrmContact edsLead = this.crmContactManager.get(relationID);
                                result.setEntityLink("Crm.html#lead|summary/" + edsLead.getObjectID() + "/" + (edsLead.getCrmAccount() != null ? edsLead.getCrmAccount().getObjectID() : ""));
                                result.setEntityName(edsLead.getName());
                            }
                            case WorkflowRule._WORKFLOW_MODULE_CONTACT -> {
                                final EdsCrmContact edsContact = this.crmContactManager.get(relationID);
                                result.setEntityLink("Crm.html#contact|summary/" + edsContact.getObjectID() + "//" + (edsContact.getCrmAccount() != null ? edsContact.getCrmAccount().getObjectID() : ""));
                                result.setEntityName(edsContact.getName());
                            }
                            case WorkflowRule._WORKFLOW_MODULE_CASE -> {
                                final EdsCase edsCase = this.caseManager.get(relationID);
                                result.setEntityLink("Crm.html#case|add/add/" + edsCase.getObjectID());
                                result.setEntityName(edsCase.getCaseNumberString());
                            }
                            case WorkflowRule._WORKFLOW_MODULE_PAYRUN -> {
                                final EdsPayslipTable payslipTable = this.payslipTableManager.get(relationID);
                                result.setEntityLink("Payroll.html#payslipTable|summary/" + payslipTable.getObjectID() + "/" + (payslipTable.getStatus() != null ? payslipTable.getStatus().getName() : ""));
                                result.setEntityName(payslipTable.getMonth() + "-" + payslipTable.getYear());
                            }
                            case WorkflowRule._WORKFLOW_MODULE_CASH_ADVANCE -> {
                                final EdsCashAdvance cashAdvance = this.cashAdvanceManager.get(relationID);
                                result.setEntityLink("Payroll.html#cashAdvance|summary/view/" + cashAdvance.getObjectID() + "/" + cashAdvance.getStatus().getCode());
                                result.setEntityName(cashAdvance.getNumber());
                            }
                            case WorkflowRule._WORKFLOW_MODULE_ACTIVITY, WorkflowRule._WORKFLOW_MODULE_LOGACALL -> {
                                final EdsEvent event = this.eventManager.get(relationID);
                                result.setEntityLink("Crm.html#event|summary/" + event.getObjectID());
                                result.setEntityName(event.getSubject());
                            }
                            case WorkflowRule._WORKFLOW_MODULE_SCHEDULED_COURSE -> {
                                final EdsCourseSchedule courseSchedule = this.scheduledCourseManager.get(relationID);
                                result.setEntityLink("TrainingCenter.html" + TCConstants.TC_SCHEDULED_COURSE + "|summary/" + courseSchedule.getObjectID() + "/" + (courseSchedule.getInstructor() == null));
                                result.setEntityName(courseSchedule.getName());
                            }
                            case WorkflowRule._WORKFLOW_MODULE_SALE_INVOICE -> {
                                final EdsInvoice invoice = this.invoiceManager.get(relationID);
                                result.setEntityLink("Accounting.html#" + Constants.SALE_INVOICE + "|summary/" + invoice.getObjectID());
                                result.setEntityName(invoice.getNumber());
                            }
                            case WorkflowRule._WORKFLOW_MODULE_SALEQUOTE -> {
                                final EdsQuote quote = this.quoteManager.get(relationID);
                                result.setEntityLink("Accounting.html#" + Constants.SALE_QUOTE + "|summary/" + quote.getObjectID());
                                result.setEntityName(quote.getNumber());
                            }
                            case WorkflowRule._WORKFLOW_MODULE_REQUEST_FOR_PURCHASE -> {
                                final EdsRFP rfp = this.rfpManager.get(relationID);
                                result.setEntityLink("Accounting.html#requestforpurchase|summary/" + rfp.getObjectID());
                                result.setEntityName(rfp.getNumber());
                            }
                            case WorkflowRule._WORKFLOW_MODULE_PURCHASEORDER -> {
                                final EdsQuote purchaseOrder = this.quoteManager.get(relationID);
                                result.setEntityLink("Accounting.html" + Constants.PURCHASE_ORDER + "|summary/" + purchaseOrder.getObjectID());
                                result.setEntityName(purchaseOrder.getNumber());
                            }
                            case WorkflowRule._WORKFLOW_MODULE_HRMS_EMPLOYEE -> {
                                final EdsEmployee employee = this.employeeManager.get(relationID);
                                result.setEntityLink("Hrms.html#employeeProfile|" + Constants.EMPLOYEE_PROFILE_VIEW + "/" + employee.getObjectID());
                                result.setEntityName(employee.getFullName());
                            }
                            case WorkflowRule._WORKFLOW_MODULE_OPPORTUNITY -> {
                                final EdsOpportunity opportunity = this.opportunityManager.get(relationID);
                                result.setEntityLink("Crm.html#opportunity|summary/" + opportunity.getObjectID() + "/" + opportunity.getConvertedFromLead() + "/" + (opportunity.getCrmContact() != null ? opportunity.getCrmContact().getObjectID() : null) + "/" + (opportunity.getCrmAccount() != null ? opportunity.getCrmAccount().getObjectID() : null));
                                result.setEntityName(opportunity.getName());
                            }
                            case WorkflowRule._WORKFLOW_MODULE_CERTIFICATE -> {
                                final EdsCertificate certificate = this.certificateManager.get(relationID);
                                result.setEntityLink("Hrms.html#certificate|summary/" + certificate.getObjectID());
                                result.setEntityName(certificate.getNumber());
                            }
                            case WorkflowRule._WORKFLOW_MODULE_PROJECT -> {
                                final EdsProject project = this.projectManager.get(relationID);
                                result.setEntityLink("ProjectManagement.html#project|summary/" + project.getObjectID() + "/" + (project.getParent() != null ? project.getParent() : "") + "/" + !Constants.PS_CLOSED.equals(project.getStatus().getCode()));
                                result.setEntityName(project.getNumber());
                            }
                            case WorkflowRule._WORKFLOW_MODULE_PRODUCT -> {
                                final EdsItem edsProduct = this.itemManager.get(relationID);
                                result.setEntityLink("Accounting.html#product|summary/" + edsProduct.getObjectID() + "/" + edsProduct.getTypeName());
                                result.setEntityName(edsProduct.getProductNumber());
                            }
                            case WorkflowRule._WORKFLOW_MODULE_ACCOUNT -> {
                                final EdsCrmAccount crmAccount = this.crmAccountManager.get(relationID);
                                result.setEntityLink("Crm.html#account|summary/" + crmAccount.getObjectID() + "/" + crmAccount.isBlocked());
                                result.setEntityName(crmAccount.getName());
                            }
                            case WorkflowRule._WORKFLOW_MODULE_MANUAL_JOURNAL -> {
                                final EdsManualJournal manualJournal = this.manualJournalManager.get(relationID);
                                result.setEntityLink("Accounting.html#manual|summary/" + manualJournal.getObjectID());
                                result.setEntityName(manualJournal.getNumber());
                            }
                            case WorkflowRule._WORKFLOW_MODULE_VACANCY -> {
                                final EdsVacancy vacancy = this.vacancyManager.get(relationID);
                                result.setEntityLink("Hrms.html#vacancy|summary/" + vacancy.getObjectID());
                                result.setEntityName(vacancy.getVacancyNumber());
                            }
                            default -> {
                                final EdsStepEmployee stepEmployee = this.stepEmployeeManager.get(relationID);
                                result.setEntityLink("Hrms.html#" + Constants.EMPLOYEE_STEP + "|add/add/" + stepEmployee.getObjectID() + "/" + stepEmployee.getOnboardingStep().getObjectID() + "/" + stepEmployee.getFormID() + "/" + stepEmployee.getEmployee().getFullName());
                                result.setEntityName(stepEmployee.getEmployee().getFullName());
                            }
                        }
                    }

                    if (item[6] != null) {
                        result.setCreator(this.userManager.get((Integer) item[6]) != null ? this.userManager.get((Integer) item[6]).getFullName() : null);
                    }
                    final String type = (String) item[7];
                    if (type != null) {
                        switch (type) {
                            case WorkflowRule.WORKFLOW_ALERT:
                                result.setActivitiesType(type);
                                break;
                            case WorkflowRule.WORKFLOW_EVENT:
                                result.setActivitiesType(type);
                                break;
                            case WorkflowRule.WORKFLOW_TASK:
                                result.setActivitiesType(type);
                                break;
                            case WorkflowRule.WORKFLOW_SMS_ALERT:
                                result.setActivitiesType(type);
                                break;
                            case WorkflowRule.WORKFLOW_ONBOARDING_STEP:
                                result.setActivitiesType(type);
                                break;
                        }
                    }
                    if (item[8] != null) {
                        final int eventType = (Integer) item[8];
                        if (eventType == 2) {
                            result.setCallLog(true);
                        }
                    }
                    if (item[9] != null) {
                        result.setRecurrenceID((Integer) item[9]);
                    }
                    if (item[10] != null) {
                        result.setActivitiesRuleName((String) item[10]);
                    }
                }
                results.add(result);
            }
        }

        return new ListResult<>(results, totalCount);
    }

