    @Override
    public ReferenceLocale getReferenceLocaleByReferenceId(final Integer referenceId) {
        final EdsReference edsReference = this.referenceManager.get(referenceId);
        if (edsReference != null && edsReference.getLocale() != null) {
            return edsReference.getLocale().toRPC();
        }
        return null;
    }

    @Override
    public void saveReferenceLocale(final Integer referenceId, final ReferenceLocale referenceLocale) {
        final EdsReference edsReference = this.referenceManager.get(referenceId);
        EdsReferenceLocale edsReferenceLocale = saveEntityLocale(edsReference, referenceLocale);
        if (edsReference != null) {
            edsReference.setLocale(edsReferenceLocale);
            this.referenceManager.update(edsReference);
        }
    }

    @Override
    public EdsReferenceLocale saveEntityLocale(EdsReference edsReference, ReferenceLocale referenceLocale) {
        if (referenceLocale == null) {
            referenceLocale = new ReferenceLocale();
            if (edsReference == null) {
                return null;
            }
            referenceLocale.setEnglish(edsReference.getName());
            referenceLocale.setRussian(edsReference.getName());
            referenceLocale.setArabic(edsReference.getName());
            referenceLocale.setUzbek(edsReference.getName());
        }
        EdsReferenceLocale edsReferenceLocale = this.referenceLocaleManager.get(referenceLocale.getObjectId());
        if (edsReferenceLocale == null) {
            edsReferenceLocale = new EdsReferenceLocale();
        }
        edsReferenceLocale.setEnglish(referenceLocale.getEnglish());
        edsReferenceLocale.setRussian(referenceLocale.getRussian());
        edsReferenceLocale.setArabic(referenceLocale.getArabic());
        edsReferenceLocale.setUzbek(referenceLocale.getUzbek());

        this.referenceLocaleManager.createOrUpdate(edsReferenceLocale);

        return edsReferenceLocale;
    }

