    @Override
    public void saveReferencePermission(final ReferenceItem item) {
        if (item != null && item.getObjectID() != null) {

            final EdsReference reference = this.referenceManager.get(item.getObjectID());
            if (reference != null) {

                reference.getAllowedRoles().clear();
                if (item.getAllowedRoles() != null && !item.getAllowedRoles().isEmpty()) {
                    for (final SelectItem selectItem : item.getAllowedRoles()) {
                        if (selectItem != null && selectItem.getId() != null) {
                            reference.getAllowedRoles().add(this.roleManager.get(selectItem.getId()));
                        }
                    }
                }

                reference.getViewOnlyRoles().clear();
                if (item.getAllowedRolesView() != null && !item.getAllowedRolesView().isEmpty()) {
                    for (final SelectItem selectItem : item.getAllowedRolesView()) {
                        if (selectItem != null && selectItem.getId() != null) {
                            reference.getViewOnlyRoles().add(this.roleManager.get(selectItem.getId()));
                        }
                    }
                }

                reference.getOppEditBtnRole().clear();
                if (item.getOppEditBtnRole() != null && !item.getOppEditBtnRole().isEmpty()) {
                    for (final SelectItem selectItem : item.getOppEditBtnRole()) {
                        if (selectItem != null && selectItem.getId() != null) {
                            reference.getOppEditBtnRole().add(this.roleManager.get(selectItem.getId()));
                        }
                    }
                }

                reference.getEmployeesCanEdit().clear();
                if (item.getEmployeeCanEdit() != null && !item.getEmployeeCanEdit().isEmpty()) {
                    for (final SelectItem selectItem : item.getEmployeeCanEdit()) {
                        if (selectItem != null && selectItem.getId() != null) {
                            reference.getEmployeesCanEdit().add(this.employeeManager.get(selectItem.getId()));
                        }
                    }
                }
                reference.getEmployeesCanView().clear();
                if (item.getEmployeeCanView() != null && !item.getEmployeeCanView().isEmpty()) {
                    for (final SelectItem selectItem : item.getEmployeeCanView()) {
                        if (selectItem != null && selectItem.getId() != null) {
                            reference.getEmployeesCanView().add(this.employeeManager.get(selectItem.getId()));
                        }
                    }
                }
                reference.getEmployeesCanEditBtn().clear();
                if (item.getEmployeeCanEditButton() != null && !item.getEmployeeCanEditButton().isEmpty()) {
                    for (final SelectItem selectItem : item.getEmployeeCanEditButton()) {
                        if (selectItem != null && selectItem.getId() != null) {
                            reference.getEmployeesCanEditBtn().add(this.employeeManager.get(selectItem.getId()));
                        }
                    }
                }
                this.referenceManager.createOrUpdate(reference);
            }
        }
    }

    @Override
    public SelectItem getAccountItemByRelation(final RelationItem firstPhoneRelationItem) {
        final SelectItem item = new SelectItem();

        if (RelationItem.TYPE_CONTACT.equals(firstPhoneRelationItem.getToType())
                || RelationItem.TYPE_LEAD.equals(firstPhoneRelationItem.getToType())
                || RelationItem.TYPE_CANDIDATE.equals(firstPhoneRelationItem.getToType())) {
            final EdsCrmContact contact = this.crmContactManager.get(firstPhoneRelationItem.getToID());
            if (contact != null && contact.getPrimaryPhone() != null) {
                item.setDescription(contact.getPrimaryPhone());
            }
            item.setId(firstPhoneRelationItem.getToID());
            item.setName(firstPhoneRelationItem.getToType());
        } else if (RelationItem.TYPE_CRM_ACCOUNT.equals(firstPhoneRelationItem.getToType())) {
            final EdsCrmAccount account = this.crmAccountManager.get(firstPhoneRelationItem.getToID());
            if (account != null && account.getPhone() != null) {
                item.setDescription(account.getPhone());
            }
            item.setId(firstPhoneRelationItem.getToID());
            item.setName(firstPhoneRelationItem.getToType());
        }

        return item;
    }

    private ArrayList<SelectItem> getSelectedItems(final List<? extends EdsObject> list,
                                                   final List<Integer> selectedIds) {
        final ArrayList<SelectItem> options = new ArrayList<>();
        if (CollectionUtils.isNotEmpty(list)) {
            list.forEach(obj -> {
                final SelectItem selectItem = new SelectItem(obj.getObjectID(), obj.getName());
                selectItem.setSelected(selectedIds.size() > 0 && selectedIds.contains(obj.getObjectID()));
                options.add(selectItem);
            });
        }
        return options;
    }

    @Override
    public SelectItem[] getCustomFieldLookUpData(final ListingFilterParameter fp,
                                                 final CustomFieldLookUpTypeEnum typeEnum) {
        if (typeEnum == null) {
            return new SelectItem[0];
        }

        switch (typeEnum) {
            case SALES_INVOICE, SALES_QUOTE, PURCHASE_ORDER, PURCHASE_INVOICE, SALES_ORDER -> {
                return this.invoiceCircularResolver.getInvoiceAndQuoteLookUpItems(fp, typeEnum);
            }
            case COUNTRY -> {
                return this.commonService.getCountries(fp, false);
            }
            case CURRENCY -> {
                return this.invoiceServiceLocal.getCurrencies(fp);
            }
            case TERMS -> {
                return this.clientService.getInvoiceTermsForLookUp(fp);
            }
            case UNIT_MEASUREMENT -> {
                return this.accountingServiceLocal.getUnitMeasurementsAsSelectItem();
            }
            case PERSONAL_GOAL -> {
                fp.setViewType(Constants.PERSONAL_GOAL);
                return this.hrmsServiceLocal.getGoalLookUpItems(fp);
            }
            case DEPARTMENT_GOAL -> {
                fp.setViewType(Constants.DEPARTMENT_GOAL);
                return this.hrmsServiceLocal.getGoalLookUpItems(fp);
            }
            case PROJECT_GOAL -> {
                fp.setViewType(Constants.PROJECT_GOAL);
                return this.hrmsServiceLocal.getGoalLookUpItems(fp);
            }
            case BUSINESS_GOAL -> {
                fp.setViewType(Constants.BUSINESS_GOAL);
                return this.hrmsServiceLocal.getGoalLookUpItems(fp);
            }
            case CUSTOM_FORM -> {
                fp.setViewType(Constants.CUSTOM_FORM);
                return this.customFormManager.getLookUpItems(fp);
            }
            case COMPANY_GOAL -> {
                fp.setViewType(Constants.COMPANY_GOAL);
                return this.hrmsServiceLocal.getGoalLookUpItems(fp);
            }
            case PROJECT -> {
                return this.invoiceServiceLocal.getRelatedProjectsWithFilter(fp);
            }
            case PRODUCT -> {
                return this.productServiceLocal.getCompanyProductsByType(fp);
            }
            case CUSTOMER -> {
                fp.setAccountType(Constants.CUSTOMER);
                fp.setWithCode(true);
                return this.crmServiceLocal.getLookUpItems(fp, LookUpConstants.CRM_ACCOUNT_ID).getList().toArray(new SelectItem[]{});
            }
            case SUPPLIER -> {
                fp.setAccountType(Constants.SUPPLIER);
                fp.setWithCode(true);
                return this.crmServiceLocal.getLookUpItems(fp, LookUpConstants.CRM_ACCOUNT_ID).getList().toArray(new SelectItem[]{});
            }
            case LEAD -> {
                fp.setAccountType(CrmConstants.LEAD);
                return this.crmServiceLocal.getLookUpItems(fp, LookUpConstants.CRM_LEAD_ID).getList().toArray(new SelectItem[]{});
            }
            case EMPLOYEE -> {
                return this.employeeServiceLocal.getCompanyEmployeesAsSelectItems(fp);
            }
            case USER -> {
                return this.employeeServiceLocal.getCompanyEmployeesAsSelectItems(fp);
            }
            case CASE, CONTACT, OPPORTUNITY, CANDIDATE, OPPORTUNITY_NAME -> {
                return this.crmServiceLocal.getCrmSubItemsLookUpItems(fp, typeEnum);
            }
            case TASK -> {
                return this.taskService.getTaskLookUpItems(fp);
            }
            case VACANCY -> {
                return this.recruitmentService.getVacancyLookUpItems(fp);
            }
            case PRODUCT_CATEGORY -> {
                return this.accountingService.getProductCategoriesAsSelectItem(fp);
            }
            case REFERENCE -> {
                return this.getReferenceChildren(fp.getParentID()) != null ? this.getReferenceChildren(fp.getParentID()).toArray(new SelectItem[]{}) : null;
            }
            case PAYMENT_METHOD -> {
                return this.getPaymentMethodsAsSelected(this.paymentMethodManager.getPaymentMethods(fp));
            }
            case DEPARTMENT -> {
                return departmentService.getDepartmentsAsSelectItem(fp);
            }
            case POSITION -> {
                return positionManager.getPositionListAsSelectItem(fp);
            }
            case LOCATION -> {
                return locationManager.getLocationsAsSelectItems(fp);
            }
            case TIMESLOT -> {
                fp.setLookUp(false);
                return timeSlotManager.getTimeslotsAsSelectItem(fp);
            }
            case CONTRACT -> {
                return contractManager.getAsSelectItem(fp);
            }
        }
        return new SelectItem[0];
    }

    private SelectItem[] getPaymentMethodsAsSelected(final List<EdsPaymentMethod> items) {
        final List<SelectItem> selectItems = new ArrayList<>();
        items.forEach(item -> {
            final SelectItem selectItem = new SelectItem();
            selectItem.setId(item.getObjectID());
            selectItem.setName(item.getName());
            selectItems.add(selectItem);
        });
        return selectItems.toArray(new SelectItem[0]);
    }

