    @Override
    public Integer checkCustomFormQuota(String formId, boolean isUpdate) {
        EdsCustomForm customForm = customFormManager.findByFormID(formId);
        EdsUser user = userManager.getUser();
        boolean canAdd = false;
        Integer result = 0;
        CustomFormRuleItem ruleItem = customForm.toRpc(true).getRuleItem();
        if (ruleItem == null) {
            canAdd = true;
        }
        canAdd = checkCustomFormDate(ruleItem);
        result = canAdd ? 0 : -1;
        if (result == -1)
            return result;

        if (customForm.getQuotaPerUser() == null && customForm.getQuotaPerForm() == null) {
            return result;
        }

        ListingFilterParameter fp = new ListingFilterParameter();
        fp.setForm(formId);

        if (customForm.getQuotaPerForm() != null) {
            Integer count = customFormItemManager.count(fp);
            if (customForm.getQuotaPerForm() <= count) {
                result = -2;
                return result;
            }
        }

        if (customForm.getQuotaPerUser() != null) {
            fp.setUserID(user.getObjectID());
            Integer count = customFormItemManager.count(fp);
            result = customForm.getQuotaPerUser() > count ? 0 : -2;
            return result;
        }

        return result;
    }

    private boolean checkCustomFormDate(CustomFormRuleItem ruleItem) {
        if (ruleItem == null) {
            return true;
        }
        EdsUser user = userManager.getUser();
        Calendar hireDate = null;
        if (user.getEmployee() != null) {
            hireDate = user.getEmployee().getStartDate() != null ? getCalendarByMillsWithoutSeconds(user.getEmployee().getStartDate().getTime()) : null;
        }
        if (hireDate == null)
            return false;

        boolean canAdd = true;
        if (CustomFormConstants.CUSTOM.equals(ruleItem.getConditionType())) {
            Long now = new Date().getTime();
            canAdd = ruleItem.getStartDate() <= now && now <= ruleItem.getEndDate();
        } else if (CustomFormConstants.AGE_IN_DAYS.equals(ruleItem.getConditionType())) {
            String range = ruleItem.getRange();
            Integer conditionValue = ruleItem.getConditionValue();
            long duration = ChronoUnit.DAYS.between(LocalDate.of(
                    hireDate.get(Calendar.YEAR), hireDate.get(Calendar.MONTH) + 1,
                    hireDate.get(Calendar.DAY_OF_MONTH)), LocalDate.now()
            );
            switch (range) {
                case "<=" -> canAdd = duration <= conditionValue;
                case ">=" -> canAdd = duration >= conditionValue;
                case "=" -> canAdd = duration == conditionValue;
                case "<" -> canAdd = duration < conditionValue;
                case ">" -> canAdd = duration > conditionValue;
                default -> canAdd = false;
            }
        }
        return canAdd;
    }

    private Calendar getCalendarByMillsWithoutSeconds(Long mills) {
        Calendar calendar = Calendar.getInstance();
        calendar.setTimeInMillis(mills);
        calendar.set(Calendar.SECOND, 0);
        calendar.set(Calendar.MILLISECOND, 0);
        return calendar;
    }

