    @Override
    public Boolean makeCallUsingSipuni(String phoneNumber) {
        EdsUser edsUser = userManager.getUser();
        EdsSipuniSettings sipuniSettings = sipuniSettingsManager.getSipuniSettingsByUser(edsUser.getObjectID());
        if (sipuniSettings != null) {
            String user = sipuniSettings.getOperatorNumber();
            String reverse = "1";
            String antiaon = "0";
            String sipnumber = sipuniSettings.getSipNumber();
            String secret = sipuniSettings.getSecretKey();
            String phone = phoneNumber.replaceAll("\\+", "");
            phone = phone.replaceAll("\\s", "");
            String hashString = String.join("+", Arrays.asList(antiaon, phone, reverse, sipnumber, user, secret));
            String hash = org.apache.commons.codec.digest.DigestUtils.md5Hex(hashString);

            String url = "https://sipuni.com/api/callback/call_number";

            HttpHeaders headers = new HttpHeaders();
            headers.setContentType(MediaType.APPLICATION_FORM_URLENCODED);

            UriComponentsBuilder builder = UriComponentsBuilder.fromHttpUrl(url)
                    .queryParam("antiaon", antiaon)
                    .queryParam("phone", phone)
                    .queryParam("reverse", reverse)
                    .queryParam("sipnumber", sipnumber)
                    .queryParam("user", user)
                    .queryParam("hash", hash);

            HttpEntity<String> entity = new HttpEntity<>(headers);

            RestTemplate restTemplate = new RestTemplate();
            String result = restTemplate.exchange(builder.toUriString(), HttpMethod.GET, entity, String.class).getBody();
            System.out.println(result);
            return true;
        }

        return false;

    }

    @Override
    public byte[] getSipuniAudio(String callId, String userId, String secret) {

        String hashString = String.join("+", Arrays.asList(callId, userId, secret));
        String hash = org.apache.commons.codec.digest.DigestUtils.md5Hex(hashString);

        String url = "https://sipuni.com/api/statistic/record";

        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_FORM_URLENCODED);

        UriComponentsBuilder builder = UriComponentsBuilder.fromHttpUrl(url)
                .queryParam("id", callId)
                .queryParam("user", userId)
                .queryParam("hash", hash);

        HttpEntity<String> entity = new HttpEntity<>(headers);

        RestTemplate restTemplate = new RestTemplate();
        String output = restTemplate.exchange(builder.toUriString(), HttpMethod.POST, entity, String.class).getBody();

        // Set the Content-Disposition header for downloading the file
        HttpHeaders responseHeaders = new HttpHeaders();
        responseHeaders.set(HttpHeaders.CONTENT_DISPOSITION, "attachment; filename=" + callId + ".mp3");

        // Send the response with the file content
        // Assuming the response is in byte array format, you might need to adjust this based on the actual response format
        ResponseEntity<byte[]> responseEntity = new ResponseEntity<>(output.getBytes(), responseHeaders, HttpStatus.OK);
        return responseEntity.getBody();
    }

    @Override
    public ContactTo createContactFromCalls(String phoneNumber, String contactFullName) {
        EdsCompanySettings companySettings = userManager.getUser().getCompany().getCompanySettings();
        ContactTo contactTO = new ContactTo();
        boolean isAccount = companySettings.getSipuniContactType() != null && companySettings.getSipuniContactType().equals(CrmConstants.TYPE_ACCOUNT);
        EdsCrmAccount account = null;
        EdsCrmContact contact = null;
        if (isAccount) {
            account = new EdsCrmAccount();
            ArrayList<EdsUser> owners = new ArrayList<>();
            owners.add(userManager.getUser());
            account.setOwners(owners);
            account.setName(contactFullName != null && !contactFullName.isEmpty() ? contactFullName : phoneNumber);
            account.setPhone(phoneNumber);
            EdsCrmContactItemParams itemParams = new EdsCrmContactItemParams();
            itemParams.setParam(1);
            itemParams.setRelation(2);
            itemParams.setValue(phoneNumber);
            crmContactItemParamsManager.createOrUpdate(itemParams);
            account.setItemParams(new ArrayList<>(List.of(itemParams)));
            crmAccountManager.createOrUpdate(account);
            try {
                accountSolrComponent.index(account);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        } else {
            contact = new EdsCrmContact();
            contact.setFirstName(contactFullName != null && !contactFullName.isEmpty() ? contactFullName : phoneNumber);
            contact.setOwner(userManager.getUser());
            contact.setPrimaryPhone(phoneNumber);
            if (companySettings.getSipuniContactType() != null) {
                contact.setContactType(companySettings.getSipuniContactType());
            }
            EdsCrmContactItemParams itemParams = new EdsCrmContactItemParams();
            itemParams.setParam(1);
            itemParams.setRelation(2);
            itemParams.setValue(phoneNumber);
            crmContactItemParamsManager.createOrUpdate(itemParams);
            contact.setItemParams(new ArrayList<>(List.of(itemParams)));

            crmContactManager.createOrUpdate(contact);
            try {
                contactSolrComponent.index(contact);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }

        contactTO.setPhone(phoneNumber);
        contactTO.setItem_id(isAccount ? account.getObjectID() : contact.getObjectID());
        contactTO.setFirst_name(isAccount ? account.getName() : contact.getFirstName());
        contactTO.setLast_name(isAccount ? null : contact.getLastName());
        contactTO.setName(isAccount ? account.getName() : contact.getName());
        contactTO.setContactType(companySettings.getSipuniContactType() != null ? String.valueOf(companySettings.getSipuniContactType()) : null);
        return contactTO;
    }

